INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1048566-phys102', 'stk-the_giant', 'PHYS 102', 'info', '{"desc": "الكورس برأي أسهل من الـ 101 , طالما جاي لموضوع الـ102 أكيد أخذت الـ 101 🙂\nلكن أطول من سابقه بكثير وقوانينه أكثر بكثير وتلخبط أكثر , لكن الكونسبت بسيط\n\nالكورس يحتاج متابعة , صعب إنك تذاكر آخر يوم وتجيب جريد لأن معظم أسئلتهم تجي سالب وموجب والمجال داخل الورقة وخارج الورقة ومن هالكلام , فتحتاج وقت وتدريب على الأسئلة حتى تعرف الفروق بينهم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/5", "user": "The_Giant", "ts": 1338472962000, "tid": 120503, "pn": 5}}', 1338472962000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1140324-phys102', 'stk-user4492', 'PHYS 102', 'info', '{"desc": "جودة المقرر بشكل عام :\nبيستفيد منه اللي بيتخصص كهرب ،\nوفيه أشياء (كل) مهندس لازم يكون ملم فيها 🌹\n\nالمواضيع التي يغطيها المقرر\n15 شابتر ، من 16 إلى 30 …\n\n16: 1 Waves\n17: Waves 2\n18: Temperature and heat\n19: the kinetic theory of gases\n20: Entropy\n21: electric charge\n22: electric field\nالشغل يبدى من هنا 😆\n23: gauss law\n24: electric potential\n25: capacitance\n26: current and resistance\n27: circuits\n28: magnetic field\n29: magnetic field due to current\n30: induction\n\n> منقوشه من السيلابس ههههه\n\nالميجر الأول سهل مقارنة ب(أسئلة) الميجر الثاني 😆\nشدوا حيلكم وجيبوا درجة حلوة في الأول لأنه سهل وستريت فورود !\nالميجر الثاني تحتاجون لليوتيوب كثير للشرح حتى توصلون للفهم الأكيد 😆\nمتريل الفاينل : سهالات ويمديك تحصل فيه درجاااات بس حاول تذاكر ولا تيأس 🌹\n\nطيب يا شباب تنصحون بالكورس هدا صيف ولالا\nلو بيدي كان أحطها ماتنزل الا بالصيف بس 😆\nتفضى لها، والصيف يخلص بسرعه، وعن تجربة أسئلة الصيف أسهل 🌹\n\nبالتوفيق ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/7", "user": "user4492", "ts": 1355443043000, "tid": 120503, "pn": 7}}', 1355443043000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1157456-phys102', 'stk-osaid', 'PHYS 102', 'info', '{"desc": "الكورس جميل و رائع لكن مو سهل ولا صعب =… يحتاج تتابعه أول بأول و تنزل عند مدرس كويس نسبياً\nمجير ون سهل جداً وما يحتاج الى إنك تفهم الكونسبت و تبدأ تشغل مخك وراح تستمع مع الأسئلة\nأما ميجر تو تحتاج تعرف الإشتقاقات في الـ إلكتريك فيلد و موجب و سالب مع فهم الكونسبت\nأما الفاينل راح يكون سهل عليك جداً إذا فهمت ميجر تو : )\nأشوفه أسهل ومباشر أكثر من فزكس 101 - في نظري - لكن يحتاج متابعه أكثر\n\nبالتوفيق للجميع ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/9", "user": "Osaid", "ts": 1357518581000, "tid": 120503, "pn": 9}}', 1357518581000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1232489-phys102', 'stk-user8577', 'PHYS 102', 'info', '{"desc": "لما نقول اسهل من 101 اعتقد لان اسئلة الاختبارات اقل صعوبة وتركات من 101 بس قسم الفزكس ما يقدر يترك حركاته 😆 😞\n\nبس لما تيجي للمتريال عكس 101 تبدأ على طول في مواضيع صعبة مقارنة في المواضيع إلي في بداية 101 🥊 بس مافي أي شابتر في 102 بصعوبة الكونسبت اللي في شابتر 10 و 11 في 101.\n\nطبعا في 102 انت تأخذ اكثر من موضوع مالها دخل في بعض فممكن تكون شباتر الثيرمو اسهل بالنسبة لك من شباتر الكهرباء او العكس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/11", "user": "user8577", "ts": 1370548574000, "tid": 120503, "pn": 11}}', 1370548574000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1252291-phys102', 'stk-guest', 'PHYS 102', 'info', '{"desc": "أخذت المادة في صيف 123\n\nالمادة بشكل عام أسهل من 101 في نظري لكن فيها قوانين كثير ونسبة لا بأس بها مو مكتوبة في الفورميلا شيت ، سلايدات الجلال كافية ووافية تماما وشاملة للمنهج كله وأراها مرجع ممتاز لمذاكرة الكونسبت، في أولد اكزام محلول لأبوأدهم ومرتب حسب السكشن أنصح فيه جيد ومنظم والحل بالخطوات (اشتريته من مركز التصوير في المكتبة مبنى 8)، قبل الميجر بأسبوع أنصح بحل الاولد اكزامز المحلولة في موقع الديبارتمنت وتراها مفيدة جدا جدا جدا وفي الفزيكس ما يكفي أنك تحل أولد اكزام واحد أو اثنين على أقل تقدير حل ثلاثة اذا تبغى تجيب درجة كويسة\n\nبالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/15", "user": "Guest", "ts": 1376253553000, "tid": 120503, "pn": 15}}', 1376253553000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1258172-phys102', 'stk-user8713', 'PHYS 102', 'info', '{"desc": "السلام عليكم و رحمة الله و بركاته\nاللهم صل على خاتم الأنبياء محمد و آله الأصفياء\n\nسلام خاص لعزيزي و حبيبي ماث 002\n\nأخ ماث 002\n\nهذه بعض الخطوات التي سوف تحقق _بها بعد توفيق الله سبحانه وتعالى_ ال A+ :\n\nاتكل على خالق السموات بلا عمد و اسأل والديك أو أقربائك الدعاء.\n\nكن مصراً عازماً على أخذ ال A+.\n\nذاكر من أي مكان و الأفضل الكتاب.\n\nفي كل فصل في طالب ينزل حل الواجب للطلاب, كن أنت هذا الطالب أو ممن يصحح حل هذا الطالب ان أخطأ.\n\nاذا ذاكرت ابدأ حل الأمثلة (Sample Problems) ثم حل المسائل (Problems) ولا أقولك حل كل المسائل\n\nأقولك أي مسألة عليها 3 نقاط لا تحلها و المسائل اللي ما عليها ولا نقطة (ِAdditional Problems) لا تحلها.\n\nمسائل الكتاب (Problems) جداً مهمة و مهمة جداً, و هي القاسم المشتك الأكبر ,\n\nو أهم شيء للحصولل على ال A+ , ,أنا أشوف المسألة الواحدة في الكتاب عن 4 مسائل من\n\nتجميع الكحيلي (by chapter).", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/16", "user": "user8713", "ts": 1378067815000, "tid": 120503, "pn": 16}}', 1378067815000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1373550-phys102', 'stk-abo-da7m', 'PHYS 102', 'info', '{"desc": "الفصل 132\n\nجودة المقرر بشكل عام\n\nممتاز\n\nالمواضيع التي يغطيها المقرر\n\nالموجات الطولية والمستعرضة … الديناميكيا الحرارية … الغازات … الكهرباء الساكنة والمتحركة … المغناطيسية\n\nبشكل عام وما فيه تعمق زايد\n\nالكتاب المستخدم للمقرر\n\nFundamentals of Physics 9th Halliday\n\nممتاز إلى حد بعيد بالشرح بس بعض المواضيع موب واضح مرة ولازم تعيد قرايته 3 إلى 4 مرات\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nالأمثلة اللي بوسط الدرس مشروحة بشكل جيد وواضح\n\nالأسئلة نهاية كل فصل متنوعة وشااملة جدا جدا لو تحل نصه صرت أطلق واحد 🙂\n\nمدى فائدته في الناحية التطبيقية\nمفيد جدا خصوصا لطلاب الهندسة الكهربائية والكيميائية وأي قسم يهتم بالحرارة وانتقالها أو بالكهرباء والمغناطيسية\n\n* أنصح وأنصح بشدة على حل أكبر عدد من أسئلة الكتاب وأشوفه مفتاح التفوق بالاختبارات، ولو شي صعب عليك أرجع للسلوشن مانوال ( موجود بالمنتدى ) أو رح للمدرس بالساعات المكتبية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/20", "user": "abo-da7m", "ts": 1401311359000, "tid": 120503, "pn": 20}}', 1401311359000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1389578-phys102', 'stk-medoalkebsi', 'PHYS 102', 'info', '{"desc": "الفصل 133\n\nجودة المقرر بشكل عام\n\nجيده جدآ\n\nالمواضيع التي يغطيها المقرر\n\nالموجات الطولية والمستعرضة … الديناميكيا الحرارية … الغازات … الكهرباء الساكنة والمتحركة … المغناطيسية\n\nالكتاب المستخدم للمقرر\n\nFundamentals of Physics 9th Halliday\n\nخايس جدآ\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nالأمثلة غير جيده\n\nالأسئلة ممتازه\n\nاضافات\nالكورس الكورس سهل , اسهل من 101 بكثير , الاسئله تقريبا نفس الافكار تتكرر من الاولد اقزامز. مفتاح هذا الكورس \" نوت عبيد + سلايدات كنوار \"", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/21", "user": "Medoalkebsi", "ts": 1407937992000, "tid": 120503, "pn": 21}}', 1407937992000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1390274-phys102', 'stk-user8581', 'PHYS 102', 'info', '{"desc": "جودة المقرر بشكل عام\nممتاز واشوفه مفيد خصوصا للميكانيكال والكهرب لأنه يعطيك بعض الأفكار الأساسية عن بعض المواضيع فيهم مثل الحرارة وقوانين كيرشوف والدوائر بشكل بسيط . البعض يشوفه اسهل من 101 والصراحة انا اشوف هالعكس لكن سهولته يمكن ان الأسئلة والمياجر تجي غالبا مشابهة كثير للأولداقزامات فأحسن طريقة للمذاكرة انك تركز على الأولداقزامات.\nوالكورس نوعا ما سهل لكن يحتاج متابعة + فيه قوانين كثيرة وبعضها ماهي موجودة في الفورملا شيت.\n\nالمواضيع التي يغطيها المقرر\nفي البداية عن الموجات والصوت ثم الحرارة وفي النهاية عن الكهرب وقوانين الكيرشوف .\nوهذي الشابتر\nhttp://www.kfupm.edu.sa/sites/phys102/SitePages/en/ContentDetailsPage.aspx?CUSTOMID=13&LinkID=LinkV4\n\nالكتاب المستخدم للمقرر & الأسئلة والأمثلة المستخدمة في المقرر\nممتاز في الأسئلة الي تكون نهاية الشابتر … لكن كشرح اشوفه ملخبط فالبديل سلايدات دكتورك .\n\nإضافات :\n- في الصيف لاتنزل مادة ثقيلة معاه لأنه ياخذ وقتك منك خصوصا في حل المسائل الااذا كانت عندك القدرة انك تنظم وقت وتعطي كل مادة حقها .\n-حاول لاتضيع المياجر وركز على الاولداقزامات لأن المياجر تتكرر فيها الاسئلة اللهم يكون تغيير بسيط فيها واحيانا تجي بالنص خصوصا conceptual questions الي في اولداقزام الكحيلي .\n-التركيز مع دكتورك في الكلاس راح يغنيك عن ساعات من السيلف ستدي وحاول تستعد للمياجر بفترة كافية وتحل اولداقزامات قد ماتقدر .\n- اهم شي في 102 والفزكس بشكل عام هو الفهم فطريقة انك تحفظ القوانين ماراح تفيدك لا في المياجر ولا الفانيل وفي احسن الأحوال بتاخذ c & التدريب مهم عشان تفهم الكونسبت .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/22", "user": "user8581", "ts": 1408223996000, "tid": 120503, "pn": 22}}', 1408223996000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1437745-phys102', 'stk-strange_phantom', 'PHYS 102', 'info', '{"desc": "يمكن أنا اخر طالب المفروض يقييم هالكورس … وحتى تعمدت ما أقيم أي دكتور عشان ما أظلمه\nبس عندي ملاحظة على كورسين الفيزكس بالفريشمان\n\" خصوصا 102\"\n\nالكورسين طريقة تدرسيهم وشرحهم و الاختبارات الموضوعة لهم اشوفها ظالمة جدا ومحبطة كثير من الطلاب ومنهم انا\nواجهت مشاكل كثيرة مع هالكورسين … وكنت أحس الخلل مني لكن ولله الحمد بعد ما تجاوزتهم تأكدت ان القسم متخلف وكثير من الطلاب مثل الحال اذا مو أسوء \"طبعا اتكلم عن الطلاب اللي عندهم حياة يعيشونها مو متقوقعين حول الكتب \"\n\nكل اللي ابغى اقوله لكل طالب حس بيأس مع المادتين او شعر بالاحباط لا تخاف … توكل على الله واعتبره تحدي أو عقبة محتاج تتجاوزها وتنساها\nالله لا يعيده من كورس ولا قسم غثيث …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/23", "user": "Strange_Phantom", "ts": 1451727889000, "tid": 120503, "pn": 23}}', 1451727889000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1438088-phys102', 'stk-user10422', 'PHYS 102', 'info', '{"desc": "كلامك صح،ولكن انا اشوفه اهم كورس في فريشمان،و نحس ان نمط تفكرينا تغير كليا عن سابق،بغض النظر عن درجاتنا،صراحة برأي اشوفهم امتع كورسين في جامعة بتحداتهم:)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/24", "user": "user10422", "ts": 1451994013000, "tid": 120503, "pn": 24}}', 1451994013000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1438112-phys102', 'stk-user9893', 'PHYS 102', 'info', '{"desc": "أتوقع قصدك عن الطلاب اللي يبذلون جهد ويدرسون بذكاء , الدوافير مهم ديدان كتب. الدوافير هم ناس يعطون المذاكرة حقها , مو تجيلي تذاكر قبل الميجر بيوم أو ثلاثة أيام وتبغى درجة حلوة !", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/25", "user": "user9893", "ts": 1452023864000, "tid": 120503, "pn": 25}}', 1452023864000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1439412-phys102', 'stk-user9534', 'PHYS 102', 'info', '{"desc": "ذاكر سلايدات الجلال والاولد اكزام وان شاء الله تجيب شيء كويس 🌹\n\nماراح أقول قريد عالي لأنه قسم الفزكس أغرب قسم بالحياة … يلعبون زي مايبون اذا يبونه سهل خلوه سهل واذا يبونه صعب بيجيك صعب 😆 يعني مافيه طريقة معينة عشان تضمن قريد 🙄\n\nسلايدات الجلال واولد اكزام وأمورك بتكون طيبة 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/26", "user": "user9534", "ts": 1453076100000, "tid": 120503, "pn": 26}}', 1453076100000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1456518-phys102', 'stk-m_nd_m', 'PHYS 102', 'info', '{"desc": "جودة المقرر بشكل عام/\nماتيريال المادة ممتع و مهم جدًا بغض النظر عن تخصصك… أساسيات لازم تعرفها كمهندس\n\nالمواضيع التي يغطيها المقرر/\nيبدأ بالـWaves ثم كل ما يتعلق بالـThermodynamics ثم للـElectric Force&Field ثم للـElectric Circuits و أخيرًا كل ما يتعلق بالـMagnatic Field\n\nالكتاب المستخدم للمقرر/\nلا بأس… لغة الكتابة ليست بتلك التعقيد و المصطلحات بسيطة\n\nhttp://media.wiley.com/product_data/coverImage300/44/11182307/1118230744.jpg\n\nالأسئلة والأمثلة المستخدمة في المقرر/\nلإكزامبلز تدرجها سيء + صياغتها معقدة\n\nمدى فائدته في الناحية التطبيقية\nكبيرة 🚬\n\nالسيلابس للترم الصيفي/\nhttp://c.top4top.net/p_246y3h21.png\n\nموضوع لأحد الأخوة فيه سلايدات كل الدكاترة + أسئلة أولد إكزامز الكحيلي/\n[هنا تجد نوتات الكحيلي والجلال ومكّي ، بعد نكبات مواقعهم ! phys 102]](https://www.stkfupm.com/forum/threads/هنا-تجد-نوتات-الكحيلي-والجلال-ومكّي-،-بعد-نكبات-مواقعهم-phys-102.132238/)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/27", "user": "M_nd_m", "ts": 1472891571000, "tid": 120503, "pn": 27}}', 1472891571000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1473787-phys102', 'stk-abdullah2015', 'PHYS 102', 'info', '{"desc": "مواضيع المقرر غطوها الأخوة اللي قبلي …\n\nبصراحة أنا أختلف مع الأخوة اللي يقولون إن فيزكس 102 أسهل من فيزكس 101 … الكورس أصعب ويحتاج إلى متابعة أكبر …\n\nأنا بذلت في فيزكس 101 جهد أقل وطلعت منه بقريد أعلى من اللي طلعت به من فيزكس 102 …\n\nالأمر نسبي لكن في فيزكس 101 المواضيع مترابطة … والشباتر الأولى راح تظل تستخدمها في التشباتر اللاحقة، بحيث إنها تصير من المسلمات مع الوقت وبكذا راح تسهل عليك كثير من الأمور لما تجي تراجع للفاينل بعدين\n\nبينما فيزكس 102 … فيه تقريبًا 4 مواضيع منفصلة عن بعض! أول تشابترين عن الWaves وهذا يعتبر من الMechanics\n\nوبعدين تدخل في الThermodynamics (الديناميكا الحرارية)، وهذا أبد ما له شغل باللي قبله … وبعدين في الشحنات الكهربائية والمجال الكهربائي … وإلخ\n\nوالتشابترات الأخيرة راح تكون عن Magnetic field … هذول تقريبًا 4 مواضيع منفصلة عن بعض\n\nقد يكون فيه ربط نوعًا ما بين دروس الكهرباء والمغناطيس … لكنهم يظلون مواضيع مختلفة …\n\nبكذا لما تجي تذاكر للفاينل، تحس إنك قاعد تدرس 4 كورسات مختلفة، خصوصاً إن معلومات التشابترات الأولى تكون طارت مع الوقت … وأنت ما تستعملها\n\nعمومًا، الكورس راح يكون مقدور عليه بالمتابعة أول بأول إن شاء الله … أي تأجيل راح يكلفك الكثير خصوصًا في دروس الكهرباء … وبالتوفيق 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/33", "user": "Abdullah2015", "ts": 1495650535000, "tid": 120503, "pn": 33}}', 1495650535000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1473895-phys102', 'stk-user10578', 'PHYS 102', 'info', '{"desc": "كثير يسألون هذا السؤال\nهل فيزيكس 102 اسهل من 101 ؟\nهذا الجواب يختلف من طالب لاخر\nفبعضهم يقولون انه اسهل لانه خلاص عرفت طريقة مذاكرة الفيزيكس\nبالنسبة لي أشوف انهم بنفس المستوى فكلاهما يحتوي على مواضيع صعبة و سهلة\nلكن فيزكيس 101 كانت فيه الكثير من المواضيع السهلة جداً ، 102 تقدر تقول مواضعيه اصعب\nو بصراحة أشوف فيزيكس 102 أصعب كورس مر على حتى الان\nكورس غثيث و صعب لكنه مو مستحيل ، تحتاج فقط وقت و فهم و مسائل و الله يعين الجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/34", "user": "user10578", "ts": 1495877313000, "tid": 120503, "pn": 34}}', 1495877313000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1497901-phys102', 'stk-ahm2d1', 'PHYS 102', 'info', '{"desc": "ما يحتاج افصل في الماده عن ايش تتكلم الشباب اللي قبلي ماقصرو …\n\nالكورس اخذته ترم 173\nوالصراحه كان اسهل من فزكس 101 …\nافكار كثيره في المياجر تتكر من الاولد اقزام فا احرص انك تفتح عالاقل ٣ اولد اقزامات قبل الاختبار …\nبشكل عام يعتبر كورس متوسط وينفع تنزله صيفي .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/35", "user": "Ahm2d1", "ts": 1534552968000, "tid": 120503, "pn": 35}}', 1534552968000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1518232-phys102', 'stk-abofordan2004', 'PHYS 102', 'info', '{"desc": "ترم 191\n\nالمادة هذي جدا دسمة وقوانينها كثيره وغير كذا انها صعبة فيها تركات لليل بصراحة اخيس واصعب كورس اخذته , اللي يقول انه ممتع ما ادري اذا هو بعقله ولا يقول هالكلام علشانه خلص المادة .\n\nانا عتبي على اللي يقول ان ذا الكورس اسهل من 101 يعني اسالكم بالله هل ال magnetic field و ال electric field والكرنت والماقنيتيك فورس والخرابيط ذي اسهل من دروس 101 ؟ خصوصا البداية في ذا المادة صدمة صراحة ولا هي سهله وتافه مثل 101 .\n\nلا ترسمون في عقول اللي بعدكم حلم وردي وتورطونهم زي ما ورطتوني\n\nانا يوم قريت كلامكم خصوصا اللي في اول صفحة صدقت صراحة انه كورس سهل لدرجة اني نزلت 16 ساعة شامله الفيزيكس 102 وتورطت , كم مرة فكرت احذف الترم والسبب كلامكم اللي يفتقر للصدق .\n\nراعو ان الناس مستوياتها تفرق عن بعض ومو شرط انك اذا خلصت المادة تقول للي بعدك انها سهله وتجيب فيه العيد\n\nاتمنى من الاداره ما تحذف هذا التعليق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/36", "user": "AboFordan2004", "ts": 1577089922000, "tid": 120503, "pn": 36}}', 1577089922000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1518637-phys102', 'stk-mr.power', 'PHYS 102', 'info', '{"desc": "بسم الله الرحمن الرحيم …\n\nالكورس هذا ٤ كورسات في كورس واحد …\nيعني مفصل إلى ٤ فصول وكلها تقريباً مختلفة عن بعض …\n\nولكن بالمجمل ، الكورس أسهل من ناحية الكونسبت ومن ناحية اسئلة الاختبارات من PHYS 101 ، ومن شابتر ٢١ إلى ٣٠ تقريباً كله عن الفيزياء الكهربائية وهذا ممتع جداً لطلاب الكهرباء والتركيز فيه وفهم الكونسبت فيه راح يخليك ترتاح في بداية كورس EE 202 …\n\nللي وده يأخذ A أو A+ ، عليك بالمذاكرة من سلايدات الجلال عشان تأخذ رؤوس الأقلام وبعد ذلك مباشرة مقاطع الاون لاين ، وبخصوص الاسئلة ، فأشوف مقاطع دفرة زون إذا اتيحت لك الإمكانية وأن لن تتمكن فأطبع اسئلة الدكتور الكحيلي وحلها بنفسك وأفضل كل جزئية تحل ١٠ اسئلة والأهم تكون افكارهم مختلفة عن بعض ، وقبل الميجر، حل مايقل عن ٣ أولد اقزامس ، ولو أني أرشح أكثر قبل الميجر بحل اسئلة الكتاب صراحة لانه كثير يجيبون منها .\n\nوفقكم الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/37", "user": "Mr.power", "ts": 1577940152000, "tid": 120503, "pn": 37}}', 1577940152000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1530962-phys102', 'stk-hajjar', 'PHYS 102', 'info', '{"desc": "كورس تطبيقي اكثر من 101 لكن اصعب بمراحل ومدري ليش كثير يقولون انه اسهل\nبمقارنة المواضيع راح تعرف ان 102 اصعب ويبيله شغل\nعن نفسي كنت اتابع مقاطع البلاك بورد والخصها مع دفره زون(اشتراك ) وبعدها احل الكحيلي معه وقبل الميد والفيانل افتح اولد قونزال\nوالحمد لله طلعت بقريد ممتاز\n\nاهم شي تشوف مصدر يناسبك دكتورك ولا مقاطع الاونلاين ولا اليويتيوب وبعدها تحل الكحيلي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-general-physics-ii/120503/40", "user": "hajjar", "ts": 1626927585000, "tid": 120503, "pn": 40}}', 1626927585000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p272729-phys102', 'stk-user2165', 'PHYS 102', 'info', '{"desc": "^^^^^^^^^^^^^^\n\nالحمد لله … مبدأي بالحياه إذا قالوا نص الوقت أسلم الورقه و أمشي لو وش يكون …\n\nوتفوتني احداث الأكشن اللي تصير بالأخير …<<<<<< معقده العطاس بالاوريا يوم كان يحبسنا بالمسلخ ويقول ما حد يطلع 😐\n\nعلى كل حال … الاختبار عندي كان أسهل من الماث 😦 … لكن الشهاده لله صعب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102/63590/28", "user": "user2165", "ts": 1213016750000, "tid": 63590, "pn": 28}}', 1213016750000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p272869-phys102', 'stk-user3804', 'PHYS 102', 'info', '{"desc": "أخوي عزوز جدة:\nبالنسبة للجارالله\n\nالحضور ورقة و توقع لكن يطال فيها بعد 10 دقايق من الوقت يعني تراه يسجل تأخير(أحيانا)…\n\nالكويزات شرحت طريقتها في الرد السابق سؤال هدية وسؤال لا 🙂\n\nأخلاق حللوه بس لا يعصب:) و إذا عصب يبقى يحترمك بعد يعني بس يرفع صوته عليك 🙂\nلكن ممكن يخربها شوي مع اللي مخربينها مررررررررررره > افهم قصدي\n\nبعد أي نقطة يسأل إذا فيه أحد ما فهم شي و خبرك ماشاء الله ربعنا كلهم نيوتن وطقته 🙂\nلكن الحق والله انه يكرر السؤال كذا مره\n\nوترا من مميزاته عن الجلال إنه يمشي بالمنهج مهوب يتاخر زي الجلال + يراجعلك قبل الاختبار من أولد اكسامز\nبس لا تفكر انه يراجع المنهج بس يحل اسئلة\n\nالريسايتيشن يحل أسئلة من الكتاب بينما الجلال أولد إكسامز\n\nالجلال 3 درجات من كل كويز مضمونه 🙂 الجارالله لا 😦\n\nو الله يوفقك 🙂\n\nاخوك\nأبو ثابت", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102/63590/36", "user": "user3804", "ts": 1213031922000, "tid": 63590, "pn": 36}}', 1213031922000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p50391-phys102', 'stk-user890', 'PHYS 102', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته …\n\nفي الحقيقة … أنا آخذ النوت من موقع البروفيسور ناصر (الكوردنيتر) …\nلأنها نوتة مضبطة … وفيها حل Examples وفيها في الأخير أسئلة المياجر اللي جات على هذا التشابتر …\n\nولكن ما حصل …\nأن نوتة Chapers 30 و 31 ما نزلها …\nفقط نزل أسألة مياجر على هذين التشابترين …\n\nيا أخوان إذا ممكن أحد يساعدني في هذه المشكلة ويدبر لي نوتة لهذين التشبترين … لأني فعلا في ورطة …\n\nاللي عنده …\nإذا كانت إليكتورنية … يرسلها لي … ويكون مشكور …\nوإذا كانت مطبوعة … اتفق معاه عشان أقابله … مع خالص شكري وامتناني …\n\nتمنياتي للجميع بالتوفيق في الفاينلات …\n\nأخوكم / نادي المسرح", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys102/36019/1", "user": "user890", "ts": 1085495147000, "tid": 36019, "pn": 1}}', 1085495147000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p186665-phys102', 'stk-user1091', 'PHYS 102', 'info', '{"desc": "يرجال أصلا غالبا الميجر الثاني للفيزكس في أي سمستر يكون صعب\n\nيويو يقولك صعب لأنه أخذها في 062\n\nعالعموم الدكتور ختك في أحد السمسترات كان يراجع لطلابه أسئلة من الكتاب قبل الميجر الثاني\n\nوأفرج سكاشنه طلع من أعلى السكاشن\n\nفكثير من الأسئلة تجي من الكتاب\n\nالله يوفقك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys102-major2-062-solution/57634/5", "user": "user1091", "ts": 1186743761000, "tid": 57634, "pn": 5}}', 1186743761000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p168996-phys102', 'stk-user2352', 'PHYS 102', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته،،،\n\nمن خلال خبرتي في هذا الكورس سأعرض عليكم أفضل الطرق للإستعداد للإختبار النهائيfinal exam:-\n1- سيكون على final exam 30% من الدرجة الكلية موزعة كالتالي (60% من شبتر\n{27,28,29 ,30} و 40 % من شبتر 16 إلى شبتر 26 التي قد تم اختبار مايجور 1 و2 فيها.\n\n2- استوعب المفاهيم الأساسية (main concepts ) في الكورس كامل خصوصا في المتيريال التي لم تدخل في المايجورين 1و 2 (من شبتر 27 إلى 30)\n\n3- ركز وافهم جميع المسائل التي على شكل (checkpoints) الموجودة في الكتاب حيث سيأتي مالا يقل عن خمسة مسائل فيها من شبتر 27 إلى 30\n\n4- عود نفسك على حل sample problem وافهم الأفكار الرئيسية وطرق ومفاتيح حلها.\n\n5- تدرب على حل مسائل كثيرةمن الكتاب خصوصا HW والامتحانات السابقة لشبتر 27 من الآن وذلك لكثرة الترك والمطبات في هذا الشبتر، وينصح بطبع نسخة من الامتحانات السابقة التي يوزعها الدكتور ختك والدكتور نقفي على طلابه أو )review problems) التي يضعها الدكتور الكحيلي في الوب سيتي لطلابه.\n\nوطبق ذلك في شبتر 28 و29 و30 . ويفترض أنك قد طبقته فيما سبق في مايجور 1و2\n\nوبالنسبة لطلاب الدكتور مكي والكحيلي وختك على وجه الخصوص فليس عند الذي يحظر من طلابهم الكلاسات أي مشكلة ،، لذلك ينصح بتصوير النوت منهم لفائدته الكبيره والتركيز عليه بعد الكتاب,\n\n6- اطبع لك نسخة من الفورملا شيت وتعرف على كل قانون وتطبيقه في حل أي نوع من المسائل من الآن وانتبه لبعض القونين التي لم تكتب في الفورملا أو بعض الثوابت،،،\n\n7- تدرب على الاستخدام الأمثل للآلة الحاسبة في حساب النواتج,\n\n8- إقرأ السؤال بوضوح واستخرج المعطيات والمطلوب وطريقة وقانون الحل…إلخ\n\n9- قيم نفسك خلال الاستعداد بأن لا تأخذ أكثر من 6 دقائق في حل المسألة الحسابية الواحدة\n\n10 حط في بالك بأنك كلما أعطيت الفزكس من المجهود فإنها تعطيك على قد المسائل التي تحلها من الآن وتأكد أن ما يقارب 45% من الاختبار مسائل مكررة مع تغيير الالفاظ والارقام،،،\n\n11- تأكد من استيعابك الكامل لجميع المعلومات الموجودة في هذا الرابط ملخص الدكتور مكي للكتاب http://faculty.kfupm.edu.sa/phys/akm...maries-HRW.htm\n\n12 - كما هو معلوم فهم السؤال نصف الإجابة لذلك افهم أكثر الأفكار المتكررة في الامتحانات السابقة بشكل دوري،،،\n\n13- ضع لك جدولا لمذاكرة كل شبتر من 27 إلى 30 على حده وأي شي يصعب عليك إذهب للدكتور في الأفس أور واستغلها بشكل دوري ،،،،\n\n14- يستحسن أن تذاكر مع لك زميل فاهم من طلاب مكي أو الكحيلي وتتدرب معه على حل المسائل وذلك بتبادل الشرح والتوضيح حتى تستفيد أكثر( الشارح يستفيد أكثر من المشروح له)،،،\n\n15- استفد من هذا الرابط في المراجعة النهائية قبل الاختبار بيومين على الأقل\nhttp://cwx.prenhall.com/bookbind/pubbooks/giancoli3/\n\nستجد قائمة في أسفل الصفحة واختر الشبتر الذي تريد ثم اختر من القائمة التي ستظهر على اليسار practice ثم اختبر نفسك في ال 25 المسألة الاختيارية واستفد من hint إذا صعبت عليك المسألة،،،\n\nوأخيرا لا ترهق نفسك في يوم الاختبار PHYS102 GENERAL PHYSICS II 7:00 PM June 11, 2007 Monday\n\nبل استعد وتناول وجبة الفطور والغداء مع أكل كمية من الفاكهة الطازجة فقد ثبت نتائجها الصحية وتخفيفها للقلق وتصفية الذهن أيام الاختبارات والابداع فيها،،،،\n\n16- تذكر مدة الاختبار ثلاث ساعات متواصلة من السابعة مساء إلى العاشرة ؛ لذلك أحضر معك علبه مياه صحية فقد تحتاجها مع مرور الوقت والتفكير في مسائل الاختبار (30 مسألة)،،،\n\n17- أحضر جميع أدواتك الهامة( قلم رصاص وممحاة وآلة حاسبة علمية) وأغلق جوالك ،،،\n\nوبالتوفيق لكم جميعا في final exams )good luck)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys102-final-exam/56333/1", "user": "user2352", "ts": 1179260680000, "tid": 56333, "pn": 1}}', 1179260680000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1198330-phys102', 'stk-user5628', 'PHYS 102', 'info', '{"desc": "والله ما اقصد كذا …\nقصدي زي ما قال i.s.w.r.t.w ،، اذا كان الأفرج مرة عالي في الميجر الأول\nراح يجيبون ميجر 2 مرة نااااار ، لأنو وإن كانت المادة ستاندرد إلا ان الديبارتمنت يراعي\nان الافرج العام للكورس يكون في معدل معين ، وعشان كذا يلعبون في المياجر ، يسهلون الأول\nويصعبون الثاني ويكون الفاينل متوسط …\nوأتمنى التوفيق للجميع ، واللي جاب درجة سيئة في ميجر1 الله يوفقه ويعوضها في ميجر2 ❤️ 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/1-phys-102/141773/35", "user": "user5628", "ts": 1363003969000, "tid": 141773, "pn": 35}}', 1363003969000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1198370-phys102', 'stk-user8941', 'PHYS 102', 'info', '{"desc": "المواضيع هذي خلاص الواحد ما يستاهل يتعب نفسه يشوفها ،،، افرج سكشني 12.5 ،، الاختبار بجد بجد تااااافه الي مذاكر المتيريال مثل طالب “” بتروول “” المفترض ما يقل عن 16 … ولو عنده وقت المفترض اكثر ،، مثل ما ذكر الاخ 3 اسئلة بالنظر تنحل وغيرها كثييير تعويض مباشر ،، الطالب الي ذاكر بس متيريال بدون اولد اكزام المفروض 12 ،، اشك ان الي يصايحون جايبين 12 - 15 ومو عاجبتهم *ــــــ^ ويقولون صعب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/1-phys-102/141773/36", "user": "user8941", "ts": 1363015043000, "tid": 141773, "pn": 36}}', 1363015043000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p43888-phys102', 'stk-user786', 'PHYS 102', 'info', '{"desc": "اهلا وسهلا اخوي الاسير\n\nالسلام عليكم\nاخوي الاسير اذا بتنزل الماده بالصيف لمدة 3 سنوات دائما الدكتور الفعر هو اللي يمسك الماده بالصيف\nالدكتور الفعر انا ادرس عنده 102 دكتور ممتاز بالشرح يعني تطلع من المحاضره وانت فاهم لكن الى الآن ما اخذنا كويزات معه\nلكن ال INSTRUCTION حقته مره معقده لكن اسمع كلامه وبربح اذا ما صار الفعر شوف اما عويمرين او فتوحي او اختر اي واحد وسلامتكم\n🙂 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102/32056/9", "user": "user786", "ts": 1077241518000, "tid": 32056, "pn": 9}}', 1077241518000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p246649-phys102', 'stk-user2872', 'PHYS 102', 'info', '{"desc": "هلا النشممممي\n\nالله يعافيك ومشكوور\n\nأبشوف نوت قوندال\n\nطيب 😊 المادة ستاندرد يا حلو 😛 لا تدرعم ثانية\n\nشوكرن عالتنبيه كوكي 👍\n\nالكتاب 😛\n\nاي والله انك صادز للحين محيوسين\n\nشووووكرن بحاول أذاكر من الكتاب مع انه يخوّف ويجيب الهم 😦 لكن بحاول\n\nشوووكرن\n\nالعفو بالنيابة\n\nالله يعين عليها أحس 102 أصعب من 101 لكن ربك يسهّل\n\nالله يسهّل … ربك كريم يآحبيبي شد حيلك 😊\n\n👍\n\nجاني احساس انك تلبس نظارات دبل (وردة) الله يعافيك وهذي مشكلتنا فعلا\n\nوشسمه\n\nاللي هو (وردة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys102/61684/16", "user": "user2872", "ts": 1203792754000, "tid": 61684, "pn": 16}}', 1203792754000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p375554-phys102', 'stk-satellite_ise', 'PHYS 102', 'info', '{"desc": "وعليكم السلام\n\nأولا : نصيحة لوجه الله \" لا تقرب نوت أو مذكرة أبو أدهم واسأل دفعة 26 العام الماضي مانكبهم إلا هي\"\nثانيا: أنصحك قدر الإمكان تحاول تفهم وتقرأ من الكتاب المقرر وتستغل سلايدات الجلال\nوإن كنت تعرف لك صاحب أو أي شخص سبق له دراسة هذا الكورس مع الدكتور الكحيلي أو الدكتور مكي خذ نوته فهو نوت مرتب وواضح يساعدك على الفهم ولكن ما هو يغنيك عن الكتاب،،\nوأخيرا أنصحك “حل old exams” وتمرس قد ما تقدر على كل شبتر بانتظام واستغل o.h لدكتورك غذا كان يفهم،،\nبالتوفيق،،،،", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102/71129/2", "user": "satellite_ISE", "ts": 1236070097000, "tid": 71129, "pn": 2}}', 1236070097000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p532699-phys102', 'stk-user3630', 'PHYS 102', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nطبعا حبيت افتح موضوع لهذا علشان ترتفع المعنويات قبل الفاينل:)\n\nتم تعديل نظام درجات الهووم ورك من استاندرد الى افرج\n\nحيث سوف يتم ضرب درجة الطالب الحالية ب 5\n\nمثلا اذا كنت ماخذ 0.6 تصير 5*0.6=3\n\nوالخبر من الدكتور ابراهيم ناصر الكوردينيتر بتاع المادة\n\nوهذا الايميل من الدكتور :\n\nYou are right, the average of the homework was written 0.6/5, and it should\nbe 3/5. So, we have to scale it by multiplying the each student’ home work\ngrade by 5 to have the average 3/5. This will be done by Mr. Khateeb, our\nassistant coordinator.\n\nThanks for pointing out to us this discrepancy.\nNote that: with the scaling, the maximum grade should not be greater than 5.\n=========================\n\nشدوا الحيل في الفاينل المتوقع يجي سهل 👍\n\nوشكرا للعضو ميمو على المبادرة في التفاعل مع القضية مسبقا\n\nتحياتي : بوخلي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys102/82867/1", "user": "user3630", "ts": 1264932580000, "tid": 82867, "pn": 1}}', 1264932580000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p682338-phys102', 'stk-che-240', 'PHYS 102', 'info', '{"desc": "الاختبار كان متوسط نوعا ما\n\nمن الظلم نقول صعب , ومن الظلم نقول سهل\n\nوالدليل خلنا نمشي سؤال سؤال على ترتيب السلوشن اللي موجود بالموقع / 👍\n\nالسؤال الاول / سهل ومكرر\nالسؤال الثاني / سهل ومكرر\nالسؤال الثالث / صعب في تحديد الزاويه هل هي 35 ام 145 ,؟؟ وصعب في الاتجاه (out - in )\nالسؤال الرابع / سؤال صعب بصراحة\nالسؤال الخامس / سؤال سهل غير مكرر\nالسؤال السادس / سؤال سهل مع اني غلطت فيه هع , تفلسفت وقلت ان النت فلوكس لاي شكل منتظم = صفر\nالسؤال السابع / سؤال متوسط\nالسؤال الثامن / سهل ومكرر\nالسؤال التاسع / سؤال (صعب) في تحديد الاشاره ( الاينر شيل عكس اشاره السنتر ) فـ تصير (سالب)\nالسؤال العاشر / سهل ومكرر\nالسؤال الحادي عشر / متوسط\nالسؤال الثاني عشر / للحين ماعرفت احله ( صعب )\nالسؤال الثالث عشر / (صعب) فيه لعبه في الانقليش , هو يقصد (higher-lower) بالنسبه لـ الاوريجن (0,0)\nالسؤال الرابع عشر / بصراحة اشتقيت وطلع لي صفر و صفر , لكن واحد قال لي لازم تشتق مرة بالنسبه لـ x ومرة لـ y ( صعب )\nالسؤال الخامس عشر / سؤال جا مثله بالهوم وورك , لكن جا هنا كـ ستيتمينت , كلاااام مو حل (متوسط)\nالسؤال السادس عشر / جا عكس طريقة الحل العاده , يعني كأنك تبدا من ورا ( متوسط )\nالسؤال السابع عشر / اممممممم متوسط نوعا ما\nالسؤال الثامن عشر / سهل ومكرر\nالسؤال التاسع عشر / سهل ومكرر\nالسؤال العشرين / سهل ومكرر\n\n===============\nانا ماني بروفوسور او عالم بالكورس عشان اقيم الاختبار بادق التفاصيل , لكني اجتهدت وبحثت وعلى حسب مذاكرتي و مراجعتي حطيت هالكلام و اعتقد نوعا ما راح توافقوني الراي :\n\nالاحصائية على مااتى في ماسبق / 🤴\n9 اسئله سهله\n5 اسئله متوسطه\n6 اسئله صعبه\n\n=========================\n\nاتمنى لكمـ التوفيق والسدآد 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys102-second-major-exam-key-here/93418/15", "user": "CHE-240", "ts": 1281717431000, "tid": 93418, "pn": 15}}', 1281717431000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p840819-phys102', 'stk-user5812', 'PHYS 102', 'info', '{"desc": "😆 😆 😆 😆 😆 😆 😆\n😆 😆 😆 😆 😆 😆 😆\n\n^^^\nهذا المستخدم فلسع بعد الميجر :\\ :\\\n\n…\n\nالسلام عليكم ورحمة الله وبركاته ❤️ ❤️\n\nآرائكم عن الميجر يا شباب وكيف وكان وضعه\n\nصعب ولا سهل … واقتراحاتكم لقسم الفيزياء عشان يسهل على طلابه المساكين في آخر كورس لهم فيه :@ 🤠\n\nبالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-major-echoes-p/107207/1", "user": "user5812", "ts": 1304617833000, "tid": 107207, "pn": 1}}', 1304617833000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p842241-phys102', 'stk-abu_3zzoz', 'PHYS 102', 'info', '{"desc": "^^^\nههههههههههههه والله العظيم والله العظيم والله العظيم وقسم بالله ماني دافور , قسم يا اني من شلة الداجييييين وخلها على ربك\nوالا أكيد اني زي أي واحد أتمنى اني أصير دافور , بس ربك ما اراد\n\nع العموم اللي ماجاب درجة حلوه , لسى قدامه الفاينل يشد حيله\nعلى كلام الدكتور الكحيلي يقول من شابتر 26 الى 30 أسهل بكثييير مقارنة بشباتر الميجر الثاني وراح يجي عليها تقريبا 18 سؤال , فهذي فرصة للي مجموعه مو حلو انه يشد حيله وفالكم الفل ماركات فردا فردا ان شاء الله.\nلاتنسون ان الفاينل يقدر يرفعك تقريبا 4 قريدات بالراحه اذا جبت درجه حلوه 🌹 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-major-echoes-p/107207/25", "user": "Abu_3zzoz", "ts": 1304888135000, "tid": 107207, "pn": 25}}', 1304888135000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p800394-phys102', 'stk-user7226', 'PHYS 102', 'info', '{"desc": "يا شباب انا عندي فكره وش رايكم نطرحها على الدكتور الحرابي\n\nنبغى نسخه مع الحل للسؤال بالتفصيل من قبل الدكتور تنزل مع الدرجات يعني النتيجه وطريقة الحل\n\nبالطريقه هذي نقدر نتلافى الاخطاء في الاختبار ويرتفع مستوى اداء الطالب وهذا هو المهم بالنسبه للجامعه وبالنسبه للطالب\n\nبالشكل هذا نقدر نقول تحقققت الفائده الكامله من اسئلة الهومورك ولكن اللي صاير هالحين ما فيه استفاده فعليه من اسئلة الهومورك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-102/102646/202", "user": "user7226", "ts": 1298674631000, "tid": 102646, "pn": 202}}', 1298674631000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p773187-phys102', 'stk-abu_abdullah', 'PHYS 102', 'info', '{"desc": "الدرجات\n\nرابط / http://www.kfupm.edu.sa/phys102/phys102-101-Final-Exam-Grades-Post.pdf\n\nمبرووووك للي أنتهى من كورسات الفزكس … وهارد لك للبقية !!\n\nتوزيع الدرجات كالتالي ::\n\nA+ ≥ 80.0\n77.0 ≤ A < 80.0\n73.0 ≤ B+ < 77.0\n67.0 ≤ B < 73.0\n60.0 ≤ C+ < 67.0\n53.0 ≤ C < 60.0\n47.0 ≤ D+ < 53.0\n41.0 ≤ D < 47.0\nF < 41.0\n\nكل من له 5 غيابات و أقل … و كان باقي له درجة واحده أو أقل راح يرفع تلقائيا للقريد اللي بعده …\nمثلا :: واحد جاب 40.2 … راح يرفع الى 41.2 و يعدي الكورس …\n\nكل الأماني لكم بالتوفيق !!\n❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/final-exam-grades-for-phys102/101407/1", "user": "Abu_Abdullah", "ts": 1295953167000, "tid": 101407, "pn": 1}}', 1295953167000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p648960-phys102', 'stk-physicist', 'PHYS 102', 'info', '{"desc": "يا ناس\nترا والله ختك مظلوم\nانا اخذت معه 102 السمستر الماضي\nوالله انه من اطيب الدكاترة اللي مروا علي\nما يبين طيبته بالفصل عشان بعض الطلاب ما يهجدون الا بالعين الحمرا\nلكن والله اذا رحت له الأوفيس انحرج من طيبته\nيبتسم ويضحك ويسأل عن الأحوال\nطبعا هذا الكلام كله اذا شافك مهتم\nاما انك تسحب على المادة وتبي المدرس يعطيك وجه فانسى\nتخيل نفسك مكانه وشف وش تسوي\n\nاما بالنسبة للأختبارات\nانا اقولكم من الحين\n80% ان ما كان 100% من الأفكار اللي راح يستعملها في الاختبارات راح تكون من الأولد اكزامز\nيعني يوم كان يشرح لنا كان يركز تركيز عليها\nحتى كويزاته كله منها\nوكل ما خلصنا اختبار جا عندنا وبدا يمشي على الأسئلة واحد واحد ويورينا شبهه في الأولد اكزامز", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/syllabus-phys-102/90936/6", "user": "Physicist", "ts": 1277986521000, "tid": 90936, "pn": 6}}', 1277986521000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p743966-phys102', 'stk-user6441', 'PHYS 102', 'info', '{"desc": "انا انصح بالفيزكس لانها اولا ستاندرد ثانيا المياجر اسهل>>>مجربها 👍\nاما الكيميستري افرجها بالصيف دائما بالعلالي (قد تصل للـ80 ) اما في الترم العادي ما تتعدى 60\n\nملاحظه\nالفزكس102 لها كو ركوزت مع الماث 102\nوبرضوه الفزكس بري ركوزت لبعض مواد التخصص وغيرها\nفاختاروا الخيار الصح 🚬\n\nبالتوفيق في التسجيل 🤠", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102/99088/10", "user": "user6441", "ts": 1292332710000, "tid": 99088, "pn": 10}}', 1292332710000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p845994-phys102', 'stk-user4626', 'PHYS 102', 'info', '{"desc": "الترم الماضي كان الفاينل حسب وجهة نظري أسهل من المياجر (درجتي في الفاينل كانت أكثر من مجوعي في الميجرين و طلعت بقريد لا بأس به )\nأهم شئ تركز على الشباتر الأخيرة لأن في أسئلة منها في الكتاب تجي بالنص و ممكن حتى بالارقام\nفنصيحتي ذاكر أسئلة الكتاب بعدين ذاكر لك فاينلين و افهم حل جميع أسئلتهم و بإذن الله ممكن تجيب من ١٥ -٢٠ حتى لو كنت مضيع طول الترم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/101-phys102/107636/7", "user": "user4626", "ts": 1307072142000, "tid": 107636, "pn": 7}}', 1307072142000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1375812-phys102', 'stk-abo_yazeed6', 'PHYS 102', 'info', '{"desc": "أنا أخذت الكورس هذا الصيف الماضي وجبت فيه +A بعد توفيق الله سبحانه وتعالى ومع اتباع التالي:\n\n1-مرجعك الأول هو الكتاب ,مهم جدا تقرأ الدرس من بدايته الى نهايته في اليوم تدرسونه في اللكتشر ,الشيء هذا راح يعطيك كونسبت قوي,لا تهمل أبدا هالموضوع.\n\n2-حل جميع sample problems+check points اللي تجيك في نص الدرس.\n\n3- لا تغيب نهائيا عن اللكتشر او الريسايتيشن.\n\n4- اذا ما فهمت نقطة أو درس من الكتاب روح لسلايدات الجلال\"لا مانع أنك تقرى السلايدات وتحل أسئلة الجلال بعد ماتنهي مذاكرة الكتاب\" ,أو روح لدكتورك في الأوفس أور.\n\n5-اذا تأكدت أنك فهمت الشابتر مضبوط,اشتر لك اولد اقزامز عبيد من الجمعية ,المذكرة نفسها كبيرة وفيها عدد كبير جدا من الأسئلة ,انا حليت كل الأسئلة من بدايتها الى نهايتها طبعا بدون ما أشوف الأجوبة واذا ما فهمت سؤال لا مانع من أنك تشوف الجواب لكن تأكد أنك تفهمه,وحتى ما فتحت الأولد اقزامز اللي موجودة في موقع الفيزكس,والحمد لله بدعت في كل المياجر والفاينل.\n\n6- كمراجعة أخيرة قبل الميجر ,فيه تلخيص لكل شابتر للدكتور عبدالكريم مكي موجود في موقعه,هذي التلخيصات فادتني كثير وأكرر كمراجعة أخيرة الي تكون قبل الاختبار بساعات قليلة.\n\nيفضل أنك تحل الأولد اقزامز الي في مذكرة عبيد بعد ما تنهي الشابتر نفسه ,او في كل ويكند, اهم شيء أنك ما تتأخر عن مذاكرة الشابتر اللي بعده,يعني حل أسئلة من الأولد اقزامز لكن في نفس اليوم لا تنس تذاكر الدروس الجديدة الي تاخذها في الشابتر اللي بعده عشان ما تضيع فيه.\n\nانا طبقت هذي الأمور وبدعت في هذا الكورس مع اني كنت جايب العيد في فيزكس 101,ممكن هالأمور ما تمشي معك لأن كل طالب يختلف عن الثاني وكل واحد له أسلوبه في المذاكرة ,لكن حبيت أفيدك في تجربتي.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys102/162100/3", "user": "abo_yazeed6", "ts": 1401703814000, "tid": 162100, "pn": 3}}', 1401703814000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1448298-phys102', 'stk-user10520', 'PHYS 102', 'info', '{"desc": "هنا تجد نوتات الكحيلي والجلال ومكّي ، بعد نكبات مواقعهم ! phys 102 & 101]\n\nبسم الله الرحمن الرحيم\n\nالسلاااام علييكم\n\nبما أن في هذه الفترة تكثر نكبات موقع قسم الفيزياء ومواقع بعض الدكاترة وأيضا موقع الريسورسس !! :speech_balloon:\nتتعطل وتتعطل مذاكرتك لأنك تعتمد على نوتاتهم أو أسئلتهم … 😢\n\nساضع هنا بعض الملفات حمّلتها على الدروب بوكس لتسهيل الوصول إليها ، وسأضعها مفرّقة ليقل حجم الملف وليسهل التحميل /\n\n* وغدي الروابط هذي ما تتعطل بعد 🤣 ! هههههههه *\n\nPHYS 102\n\naljalal slides\nDropbox - JALAL SLIDES\n\nalkuhaili UNSOLVED major problems\nالأسلة الكثيرة المجمّعة ، بالإضافة إلى أسئلة الكونسبت مع الجواب النهائي فقط\nمن تشابتر 21 إلى 30\n\nDropbox - Unsolved Exam Problems Alkuhali\n\nalkuhaili SOLVED major problems\nبعض أسئلته اللي جمعها مع طريقة الحل\nDropbox - Solved Exam Problems Alkohali\n\nملخصات مكي الرهيبة\nDropbox - smmaries by Mekki\n\nموفّقين يا شباب 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102/173200/1", "user": "user10520", "ts": 1462628692000, "tid": 173200, "pn": 1}}', 1462628692000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p819765-phys102', 'stk-equal', 'PHYS 102', 'info', '{"desc": "اذا ممكن رفعها على سيرفر ثاني او التراكر اذا ما عليك كلافه\nمتوفرة على صفحات الدكاترة …\nhttp://faculty.kfupm.edu.sa/PHYS/akmekki/Phys102-PP-lectures.htm\nhttp://faculty.kfupm.edu.sa/PHYS/aljalal/phsy102-032-web/phys102-Lectures-and-Recitations.htm\n\nمشكلتي ماحب اذاكر واحل مسائل مالها حلول لازم حلول والا مابفهم شي.\nفأتمنى الشباب ينصحوني بوحده من هذول تفيد اكثر شي.\nأنصحك بأسئلة الكتاب + السلوشن مانول … أسئلة المياجر تجي بالنص منها وكل الأفكار موجودة فيها … وهذه لاحظتها شخصياً …\nاذا خلصت منها عندك … كوزات ومسائل مكي والرمضان … او اي مسائل ثانية محلولة …\nوبعدها عندك اولد اقزام محلول تلقاه في الجمعية بإسم العُمري … 3omary14 … الله يكتب له الأجر والثواب … متعوب عليها والله وأنصح فيها …\nوفي الأخير تستلم اولد اقزام الكحيلي الغير محلول من طقطق الى السلام عليكم … وانتهينا !\nكل هذا طبعاً بعد ما تفصفص الكونسبت وتفهمه مزبوط (سلايدات الجلال، كتاب، نوتات، لوين، بطيخ !!) أهم شيء تفهم الكونسبت صح ومن اي مصدر ! … بدون كونسبت ما تقدر تسوي اي شيء !!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-resources/103706/16", "user": "equal", "ts": 1300556292000, "tid": 103706, "pn": 16}}', 1300556292000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1497870-phys102', 'stk-nawaf_d_albaqami', 'PHYS 102', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته …\n\nحبيت أقول تجربتي في هذا الكورس ، طبعًا من بداية الترم وانا كنت عارف ايش المصادر اللي راح اعتمد عليها في هذا الكورس وهذي نقطة جدًا مهمة لك عشان ماتشتت نفسك ، طريقة مذاكرتي كنت معتمد على ٣ مصادر فقط وهي كالتالي :-\n١- اشوف مقاطع الاونلاين كورس لشرح الكونسبت واكتب معهم ملخص بأسلوبي + شرح الامثلة اللي باللاونلاين كورس .\n٢- بعد ما أشوف مقاطع الاونلاين كورس للشابتر ، اقرأ ملخصي اللي سويته بأسلوبي ثم ابدأ احل اسئلة الشابتر كامل من نوت “العبيد” وركز على النوته البطلة ذي موجودة بقرطاسية المول .\n٣- قبل المياجر والفاينل ، أحل تقريبا ٣-٤ اولد اقزامز ، والاولد اقزامز يفضل تكون انها تبع الكوردينتر حق الترم حقكم بأترام سابقة له .\n\nصراحة كنت متبع الطريقة البسيطة الحلوة ذي وجبت فيها قريد محترم ولله الحمد …\nموفقين ان شاء الله .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102/171581/5", "user": "Nawaf_D_Albaqami", "ts": 1534465470000, "tid": 171581, "pn": 5}}', 1534465470000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1003090-phys102', 'stk-delpi', 'PHYS 102', 'info', '{"desc": "شباب انا بالنسبه مذاكر زين ولله الحمد وحال اغلب الاختبارات القديمه بصراحه هذا اصعب اختبار فيهم ولله الحمد حليت اغلب الاسئله بس بصعوبه واخذو وقت الاختبار كله والسبب ان الاسئله في هذا الاختبار اتت على شكل الغاز في اكثرها\nيعني خرجو من العدف الرئيسي وهو قياس فهم الطالب وتقييمه الى قياس مهارة الطالب في فك الالغاز\nوبصراحه انا بنظري ان اغلب الطلاب مايذاكرون وفي الاخير يقولون الاختبار صعب\nعموما انا سعيد ان الاختبار هذا جاء صعب لأن الماتيريال جداً سهل واتوقع انو ميجر ٢ بيكون سهل كتعويض لأنو متيريال ميجر ٢ مره صعب وملل\nواللي ماتوفقو في هذا الاختبار اتمنى يشدون حيلهم في ميجر 2 والفاينل\nودمتم بخير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-1/122542/12", "user": "delpi", "ts": 1331224317000, "tid": 122542, "pn": 12}}', 1331224317000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1166439-phys102', 'stk-user4195', 'PHYS 102', 'info', '{"desc": "ee204 اسهل مواد التيكنيكال اليكتيف …اذا ما اخذتها اخذها\n\nماده فيها لاب بس لابها سهل\n\nواحسن ما في الماده هذي مفاهيم كثيره من الي راح تدرسها انت دارسها في phys102\n\nوعندك ماده cise301 الماده سهله والماتيريال حقها -بإستثناء الفاينل - سهل جداً جداً …اما ماتيريال الفاينل مستوى صعوبته متوسط\n\nفرايي ان ما حصل ee204 خذ cise301", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/138605/2", "user": "user4195", "ts": 1358655904000, "tid": 138605, "pn": 2}}', 1358655904000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p642743-phys102', 'stk-mmkhoj', 'PHYS 102', 'info', '{"desc": "أنا أنصحك وبقوة بثلاث أشياء\n\nأولا : الكتاب إذا تقدر … وإذا ما ودك فخليك على سلايدات الجلال (طبعا حاول أول بأول)\n\nثانيا : السمري حق مكي مرة مفيد وكذلك سمري الكتاب جيدين جيدين جيدين\n\nثالثا : حل أولد أقزام .\n\nتجد هنا سلايدات الجلال :\nhttp://faculty.kfupm.edu.sa/phys/aljalal/phsy102-032-web/phys102-Lectures-and-Recitations.htm\n\nسمري مكي (بس لاتعتمد عليه كليا يعني بعد ما تذاكر راجع منه):\nhttp://faculty.kfupm.edu.sa/PHYS/akmekki/Phys102summaries-HRW.htm\n\nوفقك الله 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phy102/90719/11", "user": "mmkhoj", "ts": 1277292352000, "tid": 90719, "pn": 11}}', 1277292352000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1031767-phys102', 'stk-user5900', 'PHYS 102', 'info', '{"desc": "السلام عليكم\n\nيا أخوان وش هو ماتيريال الفاينل لاب للدكتور فؤاد عناية phys 102\n\nأنا سمعت أن كل التجارب مطلوبة لكن هل راح نسوي التجارب والا الاختبار\n\nwritten 😲\n\nوبعدين وش نذاكر له … لأن والله ناسي أغلب التجارب 🤠 🤠\n\nأرجوووووا الرد سريعاً حتى يستفيد الطلاب …\n\nتحياتي … ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/125108/1", "user": "user5900", "ts": 1335999249000, "tid": 125108, "pn": 1}}', 1335999249000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p514929-phys102', 'stk-mamoo', 'PHYS 102', 'info', '{"desc": "السلام عليكم\nمثل ماهو واضح من العنوان الدرجات نزلت\n\nhttp://www.kfupm.edu.sa/phys102/Phys102-091-M2-Grades-Post.pdf\n\nللاسف اغلب الطلاب اقل من 8 قليل اللي عشره وفوق 😦\n\nاختبار صعب بكل المقاييس الله يعين ان شاء الله في الفاينل والاختبارات القادمه\n\nتحياتي وبالتوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/81658/1", "user": "mamoo", "ts": 1262525083000, "tid": 81658, "pn": 1}}', 1262525083000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p262357-phys102', 'stk-242424', 'PHYS 102', 'info', '{"desc": "اللي يبغا يرفع معدلة لا ينزل واجد …لكن يدرس واجد\nبمعن انك تتزل ساعات اقل و تزيد المذكرة …لكن اذا المذاكرة ما زادة فادعس مدامك كذا كذا منت مذكر …بس ان شاء الله تذاكر\nالمهم الصيف اذا انت مصمم تنزل phys102 نصائحي لك انك تنزل معاها سلام او عربي لوحدها لكن بتتعب اذا نزلتهم ثلاثهم مع بعض مع ان العربي والاسلام سهل …بس ما بتشتهي عيشتك\n\nونصحية ثانية (وهاذي اهم) اذا كان الاب انستركتر سيىء مثل برمانا-او حاجة زي كذا- فلا تنزل معاه و لو تاخرت لان صحيح بتكرة عيشتك في الصيف…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/62859/5", "user": "242424", "ts": 1209508458000, "tid": 62859, "pn": 5}}', 1209508458000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p569967-phys102', 'stk-user4459', 'PHYS 102', 'info', '{"desc": "انا اتكلم كصفه عامه\n\n--\n\nالماده سهله مره والافضل انك تأخذها بعد phys 102 لصلتها الكبيره بها\n\nاللاب مواضيعه سهله جدا واغلب الي يدرسون اللاب مو دكاتره ومتفاهمين مع الطلاب ومتساعدين كثير وكمان تقدر تجيب في اللاب درجه حلوه اذا مشيت مع مدرسك وما غبت\n\nالماده لها سليوشن مانيوال في الجمعيه لاغلب الاسئله واتوقع حتى البري لاب موجود هناك , ومن الافضل ان تأخذ السليوشن من الان حتى اذا جيت تحل تعرف انت ماشي صح او لا والميجر الاول تفاهه وتقدر تجيب فل مارك اذا ركزت لان الماتيريال قليله وبسيطه\n\nيفضل انك تمر على الاولد اكزامز اذا فيه وقت لتعرف نمط وطريقة الاسئله الي راح تجيك واذا جاء الاختبار اكتب الي تعرف والي ما تعرف عشان تاخذ بارشال كرديت افضل من لا شي\n\nوبالنسبه للصيف انا اشوفها عايديه اذا اضطريت انك تنزلها لان كلها 8 لابات فقط في الترم كامل يعني ما راح تأثر عليك بالمره\n\nيعني الماده سهله ولا تطلع من الكورس الا بقريد حلو , حتى وان جيت في المياجر على الافرج اهم شي انك تطلع من اللاب بدرجه كويسه وشد حيلك في الفاينال … لاني كنت كذا , كان الافرج عندنا مرتفع في الميجرين وانا كنت جايب على الافرج بالضبط وقلت خلاص ما عاد يمديني اجيب درجه حلوه , رحت بعد كذا كلمت الدكتور وقلت له هل يمديني اطلع بقريد مرتفع قال الفاينال واللاب هما الي راح يرفعون درجتك والحمد لله بدعت في اللاب و الفاينال وطلعت بقريد ما كنت اتوقعه\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/85702/4", "user": "user4459", "ts": 1269087131000, "tid": 85702, "pn": 4}}', 1269087131000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p733149-phys102', 'stk-user7726', 'PHYS 102', 'info', '{"desc": "انا من ميجر الماث يوم الربوع وانا غاسل يدي منهم …\n\nوالله حرام الواحد يذاكر ويجيه شي ثاني …\n\nانا اشوف انه صعب الى صعب جدا …\n\nتلقى اربع الى خمس اسئلة نفس الفكرة زين وش الفايدة من الاختبار اجل …\n\nالله يوفقكم جميعا وترا نزل السليوشن …\n\nhttp://www.kfupm.edu.sa/phys102/phys102-101-First%20Major-Post.pdf", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/97837/4", "user": "user7726", "ts": 1289068309000, "tid": 97837, "pn": 4}}', 1289068309000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1208565-phys102', 'stk-chemist', 'PHYS 102', 'info', '{"desc": "أعارض رأيك وبشدة 🌹 >>> عادنا بنتضارب انا وياك ❤️\n\nراح يكون عنده ضغط مو طبيعي أصعب كورسات الكيمستري وهو الأورقانك + أصعب كورسات الماث 201 + PHYS 102\nوجهة نظري\n\nلا انصح بهذا إطلاقا دام الأورقانك ما تفتح شي يجلها ان شاء الله ماينزلها إلا وهو سينير ماعنده مشكلة\n\nأما الدكاترة تبع الأورقانك فمستحيل ثلاث سنين قدام يعني 6 سمسترات مايجي دكتور كويس!!!!!! 5سكاشن كلها سيئين لا مستحيل\n\nاسمع نصيحة الشايب وخلك من رابط خربان الدافور 😛 تراه بينكبك 😛\n\nلا امزح الأمر راجع لك أخ D7eeM أما تأخذ برأيي أو برأيه\n\nونسأل الله لك التوفيق ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/123-131/142396/94", "user": "Chemist", "ts": 1365627216000, "tid": 142396, "pn": 94}}', 1365627216000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
