INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1464028-phys102', 'stk-user10429', 'PHYS 102', 'srcU', '{"html": "وعليكم السلام ورحمة الله وبركاته<br><br>​<span data-fid=\"stk-f1464028-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f1464028-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1464028-0": {"name": "Lect PP Ch 21.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/586e5401d1b99aae79af877b19e63e2230bdd7c768389828db2c3948e0b5bcd2"}, "stk-f1464028-1": {"name": "Lect PP Ch 22.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/320b84427bf783cd5d3a843b21825679f2f30c7d7b8d2d91dd07ce8f4425fd3e"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-saleem-rao-notes/175494/2", "user": "user10429", "ts": 1481218212000, "tid": 175494, "pn": 2}}', 1481218212000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p770700-phys102', 'stk-tooooti', 'PHYS 102', 'srcP', '{"html": "اتفضل في المرفقات<br><br>​<span data-fid=\"stk-f770700-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f770700-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f770700-0": {"name": "Phys102-101-M2-Post.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/b7d46879b9bac24fdacba1a71dabbd6116f71abb8a5903009153891dcc84ca3a"}, "stk-f770700-1": {"name": "phys102-101-M1-Post .pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/8eea7b5c338f1299b25df4c305c941fad9fea97a11b45bbdec90a45db7c0a55c"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys102-101-1-2/101142/2", "user": "tooooti", "ts": 1295797074000, "tid": 101142, "pn": 2}}', 1295797074000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p666783-phys102', 'stk-_140', 'PHYS 102', 'srcP', '{"html": "صبحكم الله بالخير<br><br>زي مو واضح من العنوان نزل السلوشن حق الميجر<br><br>والملف في المرفقات<br><br>بالتوفيق للجميع<br><br>تحياتي<br><br>​<span data-fid=\"stk-f666783-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f666783-0": {"name": "Phys102-093-M1-Key-Post.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/a26dd54a2e179c776652a84acf91e46902052d3ee50220fda274d070eae8ebe3"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys102-first-major-exam-key-solution/92564/1", "user": "_140", "ts": 1280041051000, "tid": 92564, "pn": 1}}', 1280041051000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p682209-phys102', 'stk-meshoo', 'PHYS 102', 'srcP', '{"html": "السلام عليكم وكل عام وأنتم بخير:)<br>الكي سلوشن للإختبار نزل وبالتوفيق للجميع 👍 👍<br>الملف في المرفقات 🤴<br><br>​<span data-fid=\"stk-f682209-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f682209-0": {"name": "Phys102-093-M2-Post.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/8dd3b60f45752e6324ab2eb8195fd552387a6e667ac3faf0eabcd680e3346ea7"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys102-second-major-exam-key-here/93418/1", "user": "Meshoo", "ts": 1281703901000, "tid": 93418, "pn": 1}}', 1281703901000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p514850-phys102', 'stk-scatter', 'PHYS 102', 'srcP', '{"html": "بالمرفقات 🙂<br><br>​<span data-fid=\"stk-f514850-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f514850-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f514850-0": {"name": "Phys102-091-M2-Post.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/af17a9d92746f5698e584531808831cf1bfc95977712869c79019f8344a97122"}, "stk-f514850-1": {"name": "phys102-091-M1-proct-post…pdf", "v": "data:application/octet-stream;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-2/81625/19", "user": "Scatter", "ts": 1262517060000, "tid": 81625, "pn": 19}}', 1262517060000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p532172-phys102', 'stk-user3354', 'PHYS 102', 'srcU', '{"html": "السلام عليكم ورحمة الله وبركاته…<br><br>الله يعيننا واياكم ويوفق الجميع…<br><br>الوقت هذا ابدا مو وقت تشكي ونبش مشاكل ولكن صاحب الحق لابد ان يأخذ حقه…<br><br>ومصدقاً لقول الله تعالى ( يا أَيُّهَا الَّذِينَ آمَنُواْ أَوْفُواْ بِالْعُقُودِ )<br><br>وقول الرسول صلى الله عليه وسلم { وَالْمُؤْمِنُونَ عَلَى شُرُوطِهِمْ إلَّا شَرْطًا حَرَّمَ حَلَالًا أَوْ أَحَلَّ حَرَامًا } . رَوَاهُ التِّرْمِذِيُّ وَصَحَّحَهُ<br><br>تفاجأت اليوم عند نزول قريدات الاونلاين هووموورك انها ليست على أساس<br><br>الـ Coordination and Grading Policy واللي كانت موجودة بالموقع بداية السمستر 091<br><br>حيث تنص هذه القوانين واللي بدينا السمستر 091 على اساسها ان درجات الـ<br><br>online homework تمثل %5 من مجموع الدرجات الكلي وتخضع لنظام الافرج وهو 30/50 …<br><br>واليوم اذا بي اتفاجأ عند نزول درجات الاونلاين هووموورك ان الافرج 6.4/50 والمعروف ان الونلاين<br><br>هووموورك يطبق عليه نظام الافرج 30/50 من عدة سمسترات ماضية وحتى بداية هذا الترم 091 …<br><br>فرق جداااااا كبير والمشكلة في هذي الماده ان جزء منها يخضع لنظام الافرج مثل الكلاس وورك<br><br>ودراجات اللاب والدرجة الكلية للمادة ستناندرد يعني الجزء اللي تقدر تجيب فيه درجات ينزلونك<br><br>فيه والجزء اللي تخبص فيه يخلونك على تخبيصك …!! لماذا ؟؟!<br><br>وحيث أننا بدأنا هذا الفصل 091 بناء على قانون واضح متبع في هذا الماده وهو قانون توزيع<br><br>الدرجات Coordination and Grading Policy وهذا مثل الشروط في العقد يجب الوفاء بها تمام<br><br>من قبل الطرفين…<br><br>الا ان النظام تغير فجأة ولم يخبر اي من الطلاب بهذا التغيير…<br><br>هكذا كان قانون نظام درجات الاونلاين هووموورك (Home work (with average score 30/50<br><br>اما الحين اتفاجأ ودون سابق انذار ان النظام اصبح (Home work (no averaging<br><br>وهذا ملف للا Coordination and Grading Policy for term 091 في البداية المرفق الاول<br><br>وهذا ملف للـ Coordination and Grading Policy for term 091 بالوقت الحالي المرفق الثاني<br><br>الحين نبغى كلنا نستعين بالله ونتكاتف في ابدا وجهة نظرنا تجاة المشكلة بحيث انو<br><br>كل واحد ينسخ الكلام اللي هنا او يكتب بطريقته ويرسل…<br><br>لوكيل الجامعة للشؤون الاكاديمية الدكتور عبدالعزيز الصويان suwayyan@kfupm.edu.sa<br><br>لرئيس كلية العلوم الدكتور وليد الصباح cs.dean@kfupm.edu.sa<br><br>لرئيس قسم الفزكس الدكتور عبدالعزيز الجلال aljalal@kfupm.edu.sa<br><br>لمنسق مادة phys-102 الدكتور ابراهيم ناصر imnasser@kfupm.edu.sa<br><br>صحيح ان الوقت مايسمح لكن ان شاء الله ماتاخذ اكثر من خمس دقايق كلها…<br><br>وجزاكم الله خير… الله الله بالارسال ترون خمس درجات تأثر على القريد النهائي…<br><br>​<span data-fid=\"stk-f532172-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f532172-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f532172-0": {"name": "Phys102-091-syllab.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/f7c3a1ba6a4b1a7c2a9c3062c93e6d5397128b22174f0de917c9c97261639eb5"}, "stk-f532172-1": {"name": "Phys102-091-policy.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/7107283ddcafb62781a912edcdf5f3599070d4b8e3ab89f091bcfe15d7e862dd"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102/82835/1", "user": "user3354", "ts": 1264875333000, "tid": 82835, "pn": 1}}', 1264875333000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
