INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1234239-phys102', 'stk-abo_yazeed6', 'PHYS 102', 'srcU', '{"html": "بالضبط,<br><br>بالنسبة للسؤال الأول اللي انا فهمته انه الفرق لازم يكون عدد فردي مضروب في pi<br><br>طبعا هالجواب مو موجود فنحوله ل wavelength فيصير عدد فردي مضروب في lambda/2<br><br>الحين سؤالي مو المفروض بالخيارات يكتبون lambda/2 بدل L/2<br><br>لأنه L مو شرط تساوي lambda 😐 😐<br>وبالنسبة للسؤال الثاني مو المفروض نقرب الزاوية في النهاية لعدد صحيح بدون فواصل؟<br>😐 😐<br>​<span data-fid=\"stk-f1234239-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f1234239-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f1234239-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1234239-0": {"name": "Bader Alghamdi Resume.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/d74bd3b393115f983ee06ce80f4ea4351bafd32351baf65976caafb3999522ea"}, "stk-f1234239-1": {"name": "Faris-CVN copy.docx", "v": "data:application/vnd.openxmlformats-officedocument.wordprocessingml.document;base64,"}, "stk-f1234239-2": {"name": "cv 77.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/4d1456987f6d04fa30df95172446e43c921fbd3e5dfa88a855aa63de54e92547"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys102-123/145825/24", "user": "abo_yazeed6", "ts": 1370979575000, "tid": 145825, "pn": 24}}', 1370979575000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p792305-phys102', 'stk-hussain-as', 'PHYS 102', 'srcU', '{"html": "شوف أخي<br><br>القنون هو skfupm.com - Informationen zum Thema skfupm.<br><br>آخر عنصر على اليمين هو amplitude<br><br>فإذا تضاعف فيكون ×2 تحت التربيع --- فتصير 4<br><br>القانون في الكتاب صفحة 436 --- آخر واحد في العمود الأيسر<br><br>==================================================<br><br>ولمن لا يريد أن يقوم بالحساب بشكل يدوي --- برمجت لكم برنامج بلغة C في المرفقات<br><br>وهذي صورة للبرنامج --- طبعا راح يبقى عليك تسوي السقنفكنت فقر بنفسك<br><br>skfupm.com skfupm.com - Informationen zum Thema skfupm.<br><br>skfupm.com ist die beste Quelle für alle Informationen die Sie suchen. Von allgemeinen Themen bis hin zu speziellen Sachverhalten, finden Sie auf skfupm.com alles. Wir hoffen, dass Sie hier das Gesuchte finden!<br><br>وهذا هو الكود لمن يريد التأكد من سلامة البرنامجة<br><br>\\#include &lt;stdio.h\\&gt;main\\(\\) \\{ double x,y; printf\\(\"\\\\n Enter amplitude in cm \\-\\-\\-\\-\\&gt; \"\\); scanf\\(\"%lf\",&amp;x\\); x\\=x/100.0; y\\=x\\*39.73835306; printf\\(\"\\\\n \\\\n %.5f \\\\n\\\\n\\\\n\",y\\); printf\\(\" Programmed by Hussain \\\\n\\\\n\\\\n\"\\); system \\(\"PAUSE\"\\); return 0;\\}البرنامج تم تجربته على الأرقام من هذه المشاركة<br><br>skfupm.com - Informationen zum Thema skfupm.<br><br>تحياتي<br><br>حسين<br><br>​<span data-fid=\"stk-f792305-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f792305-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f792305-0": {"name": "Q1-2.zip", "v": "data:application/zip;base64,"}, "stk-f792305-1": {"name": "1-2.zip", "v": "data:application/zip;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-102/102646/53", "user": "Hussain-AS", "ts": 1297858287000, "tid": 102646, "pn": 53}}', 1297858287000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p802912-phys102', 'stk-user5836', 'PHYS 102', 'srcU', '{"html": "**ملاحظة: هذي طريقتي في حل الأسئلة وتحتمل أن تكون صحيحة أو خاطئة !<br><br>السؤال الأول:<br><br>يتكون السؤال من جزئين :<br><br>الجزء الأول : اعتبر أن الديتيكتور هو الشاحنة ، والسورس هو الجسم الثابت ،،، ثم احسب التردد ''f<br><br>الجزء الثاني : اعتبر الديتيكتور الجسم الثابت ، والسورس هو الشاحنة ،،، ثم احسب التردد ''f<br><br>--(انتهى السؤال)--<br><br>السؤال الثاني:<br><br>تعويض مباشر في القانون ولا تنسى تحول اليونت.<br><br>السؤال الثالث :<br><br>The source and the detector move away from each other<br><br>-----------------<br><br>في المرفقات سلاديز للحرابي لهذا الدرس ممكن يفيدك وخصوصاً صفحة 6<br><br>​<span data-fid=\"stk-f802912-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f802912-0": {"name": "ch17-c.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/0f186b5e82f037f26acadfd72165041698e428d2fee662184c686658653ec116"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-102/102646/237", "user": "user5836", "ts": 1298924512000, "tid": 102646, "pn": 237}}', 1298924512000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p806437-phys102', 'stk-hussain-ams', 'PHYS 102', 'srcU', '{"html": "السلام عليكم<br><br>هذا برنامج للحل للسؤال الثالث --- طبعا الحل من الردود فوق<br><br>تم الإختبار على سؤال<br><br>في المرفقات<br><br>وهذولي موقعين للتحويل للفهرنهايت في السؤال الثاني<br><br>Kelvin to Fahrenheit conversion: K to °F calculator<br><br>Temperature Unit Converter - Measurement conversion J-Z<br><br>أو إكتب المعادلة كذا في بحث قوقل وهو راح يحولها لك<br><br>4 kelvin in fahrenheitطبعا بدل رقم 4 بما تريده<br><br>ولا تنسونا من الدعاء<br><br>تحياتي<br><br>حسين<br><br>​<span data-fid=\"stk-f806437-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f806437-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f806437-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f806437-0": {"name": "Q3.zip", "v": "data:application/zip;base64,"}, "stk-f806437-1": {"name": "Q33.zip", "v": "data:application/zip;base64,"}, "stk-f806437-2": {"name": "ISM_for_Fundamentals_of_Physics_Extended__8E_Ch-27.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/73cf8536362dd3298832ad861284dec67877f66f3f3477aaaf32341fb52b09c4"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-102-102/102646/301", "user": "Hussain-AMS", "ts": 1299337839000, "tid": 102646, "pn": 301}}', 1299337839000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
