INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p925930-phys102', 'stk-user5771', 'PHYS 102', 'srcP', '{"html": "حمل من المرفقات<br><br>​<span data-fid=\"stk-f925930-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f925930-0": {"name": "Phys102-111-M1-Key-Post.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/fe24a06f52b6c579751cac499dfd051f46ec67f08bfcbaf9c1778e3f33dfe920"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/2-102/114453/3", "user": "user5771", "ts": 1319657942000, "tid": 114453, "pn": 3}}', 1319657942000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ad0rs-phys102', 'stk-ad0rs', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f80097", "n": "Dr. K Gasmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 lec - 121\n\nالتحضير :\nورقة تمر على القاعة>>> كنا 3 سكاشن\nكنت دايما اوقع واطلع بعد تقريبا ربع ساعة\nقبل نهاية السمستر صار يدقق\nطريقة الشرح :\nعادية احيانا تفهم احيانا تسأله يعيد الشرح مرة ثانية\nبس يوصل المعلومة\nالكويزات :\nاولد اقزامز لو ذاكرت تحل\nالمياجر:\nكومون\nالفاينلات :\nكومون\nالقريد النهائي:\nB\nالصوت:\nواضح ومفهوم\n🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1233362-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-gasmi/80097/34", "user": "ad0rs", "ts": 1370779323000, "tid": 80097, "pn": 34}}, {"id": "stk-dr-f68347", "n": "Dr. Fida Al-Adel", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 lab - 122\n\nطريقة الشرح :\nما تفهم منه شي ووقت التجربة ما يساعد\nالكويزات :\nيعطيك كويز التجربة قبل التجربة\nواكثر من مرة كلمناه\nما غير الشي ذا الا قبل نهاية السمستر\nالقريد النهائي:\nD\nالصوت:\nمو واضح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1233364-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fida-al-adel/68347/23", "user": "ad0rs", "ts": 1370779480000, "tid": 68347, "pn": 23}}]}', 1370779323000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3490-phys102', 'stk-user3490', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68349", "n": "Dr. Sardar Ayub", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا أخذت معاه Phys 102\n\nما كان يكتب نوت ولا يشرح على سلايدات ولا كمبيوتر\n\nيعني أكثر الوقت كان يتكلم فقط بدون ما يوضح بكتابة وبشي\n\nوحتى شرحه ما استفدت منه في المادة\n\nفصارت المادة عندي self study أذاكر بس من الكتاب ونوتات المدرسين وأحيانا كنت أحضر عند الكحيلي واستفدت من الكحيلي كثير\n\nعشان كدا مادة مهمة مثل 102 ما أنصح فيه أبدا مع احترامي الشديد له\n\nأنا أنصح اللي ما يستفيد من شرح المدرس في الفيزيا انو يستعمل الكتاب\n\nصحيح الكتاب فيه كلام كثير لكن والله والله لو تركز فيه وتحل المسائل اللي فيه تطلع بفوائد كبيرة\n\nالحمد لله أنا كان اعتمادي بعد توفيق الله على الكتاب وطلعت بـ a\n\nطريقة مذاكرة الكتاب تمسك الكتاب برقراف برقراف وتخطط على الشي المهم فقط حتى اذا جيت تراجع راجع اللي خططت عليه فقط ثم حل تمارين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p350401-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sardar-ayub/68349/10", "user": "user3490", "ts": 1231561452000, "tid": 68349, "pn": 10}}]}', 1231561452000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6202-phys102', 'stk-user6202', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68349", "n": "Dr. Sardar Ayub", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 Lab\nSemester 102\n\nالتحضير : يومي ولا ينصح بالتأخر عنده أبدا(ن) لأنه يبي يبهذلك\nطريقة الشرح : واضحة ويكتب لك الريبورت كامل على السبورة ما يحتاج تحضر ولا شي …\nالكويزات : الكوز يجي سؤالين multiple choice عليه درجة من 20 حقت اللاب وهي عموما خمس كويزات وتجي نظري زي اللي في المياجر بس عادة اسهل … اذا بتذاكر لكويزاته ينصح انك تذاكر الموضوع من الكتاب حق اللكتشر لأن المانيول ما راح يفيدك عنده\nالمياجر: -\nالفاينلات : الفاينل لاب كان عشر أسئلة نظري multiple choice عليها 5 درجات وبصراحة كان ما ادري وش يبي ولا له اي علاقة باللي درسته في اللاب لدرجة ان أعلى واحد في سكاشنه أخذ 8 من 10 … 😞\nيعني باختصار اذا بتذاكر له ذاكر من كتاب اللكتشر لأنه هو اللي بيفيدك أكثر …\nالقريد النهائي: C+\nالصوت: واضح وجهوري ويا كثر ما يهوش 🤠\nإضافات : المدرس هذا ينفع للي مستواه مهوب ذاك الزود في اللابات لأنه في الأخير وزع القريدات بحيث اعلى درجة 16 واقل درجة 11 … ونصيحه لا تغيب ولا تسوي ميك اب عنده عشان تجيك أعلى نسبة من الدف … بالاضافة الى أن لاباته كلها أفرجها نازل مرة …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p860846-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sardar-ayub/68349/25", "user": "user6202", "ts": 1309295137000, "tid": 68349, "pn": 25}}, {"id": "stk-dr-f68359", "n": "Dr. Nouar Amor Tabet", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "phys 102\nsemester 102\n\nالتحضير : في الكتشر قليل تحضيره لكن في الريسيتيشن يحضر دايم … طبعا(ن) ينادي بالأسماء\nطريقة الشرح : منتازة جدا(ن) جدا(ن) ويعجبك ان الدكتور متحمس جدا(ن) وهو يشرح 😆 … لكن مع هذا يبغالك تتابع المادة … اتوقع الشباب اللي يقولون شرحه سيء ما يراجعون والدروس تجي غالبا متراكمة والدكتور مهوب عايد لك شيء شارحه قبل 😐 …\nالكويزات : متوسطة … يعني بالعربي تذاكر تحل ما تذاكر يمكن تحل …\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+ وبجدارة 🌹\nالصوت: عالي وواضح … الصدق اني كنت استمتع بلهجته اذا تكلم 🤠 …\nإضافات : من خلال تجربة أقولك اذا تبي قريد يبيض الوجه في الفيزكس حل الهوموركات بنفسك 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p860856-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nouar-amor-tabet/68359/30", "user": "user6202", "ts": 1309296329000, "tid": 68359, "pn": 30}}]}', 1309295137000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nasser_m-phys102', 'stk-nasser_m', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68352", "n": "Dr. Muhammed Gondal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور محمد شريييح و اخلاقه حلوه\n\nانا اخذت معاه فيزكس 102\nالكوزات : ذاكر اول باول ولا تشيل هم سهاله يعني مو ذيك الصعوبة\n\nاما التحضير يوزع الورقه كل كلاس ولو تخلي احد يحضرك\nمادرى عنك يعني في الشهر يشيك مره\n\nاما بالنسبه لفيزكس 101 مادري عنه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p463812-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammed-gondal/68352/20", "user": "NASSER_M", "ts": 1253895584000, "tid": 68352, "pn": 20}}]}', 1253895584000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-phys102', 'stk-guest', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68377", "n": "Dr. Nabil Maalej", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys102\nT192\nالتحضير : تحضير الكتروني بقوقل شيت اتوقع اذا سجلت نفسك بعد ١٠د تحسب لك غياب.\n\nطريقة الشرح :يشرح بسلايدات كم دكتور ومعدل فيها ، الشرح يركز فيه على الكونسبت بشكل كبير ويخلي الامثله للريسايتيشن. عنده اسئله يعرضها ويحط تصويت على قوقل شيت، الشرح نفسه ماتغير قبل وبعد كورونا.\n\nالكويزات : عادة الكويز سؤالين واحد سهل والثاني متوسط الى صعب، مايصححها يصححها قريدر، غالباً لن يعدل لك او يزودك بارشال كردت.\n\nالمياجر:كومن\n\nالفاينلات :كومن\n\nالقريد النهائي:A\nالصوت: صوته مسموع ولغته كويسه.\n\nإضافات : اكثر دكتور شفته مهتم في شرحه ويجيب ادوات في اللكشر يوضح فيها المفاهيم.\nاخلاقه جيده جداً.\nالريسايتيشن عنده يقسم الكلاس مجموعات ويعطي اسئله ويكون الحل جماعي.\n\nالدكتور محترم وشرحه جيد واكثر شي عجبني عنده البلاكبورد منزل فيه كل اللي تحتاجه وبشكل منظم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525321-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nabil-maalej/68377/19", "user": "Guest", "ts": 1599071929000, "tid": 68377, "pn": 19}}, {"id": "stk-dr-f69025", "n": "Dr. Abdallah Al-Zahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102 - 201**:**\n\nترم كورونا الجزء الثاني\nالشرح : شرحه جيد ك كونسبت ما اعرف ليه الي قبل يذمون بالشرح بس عموما الكونسبت ماراح ينفعك بالاختبارات زي التدريب انصحك تروح عند دفرة زون تحل واذا ماعرفت تشغل المقطع\n\n* ماخصم على الغياب .\n\n* الكوزات اشوفها سهلة نسبيا\nوكان يمديني اجيب ١٤/١٥ بحكم الافرج بس كم كوز غبت عليه بس الحمدلله على كل حال جبت اعلى من الافرج بدرجة يعني اذا انت واحد بتكرف عمرك وتشتغل عليها القريد ان شاء الله مضمون\n\nاضافات : الدكتور اخلاق ومتفهم مادري اذا غير نظامه هذا الترم او ان الطلاب يتدلعون\n+الهلب سشن الي يسويها الدكتور جدا مفيدة حاول ماتسحب عليها وان شاء الله فالنا وفالكم القريدات الطيبة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527357-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdallah-al-zahrani/69025/48", "user": "Guest", "ts": 1609235082000, "tid": 69025, "pn": 48}}, {"id": "stk-dr-f68352", "n": "Dr. Muhammed Gondal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102 - 201\n\nالتحضير:\nالدكتور كان يحط كويز في البلاكبورد وايضا مرات يخلينا نرفع يدنا في تيمزوياخذ التحضير.\nوفي الأخير بعض الطلاب اكتشفوا ان الدكتورمزودهم غيابات ( الغيابات ماكان عليها درجات)\n\nالشرح :\nنظام الدكتور كان يفتح كاميرا اللابتوب ويخليها على السبورة ويجلس يكتف فيها\nطريقته للأمانه جدا سيئة بسبب عدم وضوح السبورة\nلذلك تراك بتعتمد على نفسك وبتاخذ المادة سيلف ستدي\n\nالكويزات :\nسهلة - متوسطة , غالبا نفس افكار الاولد اقزام حقه\nواغلبها كانت فاينل انسر الا كم كويز بس خيارات\nطبعا نهاية الترم كان افرجنا عالي فحسب كل الكويزات وبرضه نقصنا بسبب النورملايزيشن\nوطبعا الكويزات بدون كام ولا شيء\nوبعض الكويزات كان فيها اكثر من محاولة\nوبعض الكويزات كانت بدون وقت ههههههههه\n\nاضافات:\n1- الدكتور محترم جدا جدا واخلاااااااااااق ويحب يرضي الكل , جدا عسل .\n2- الدكتور في كل ترم يجمع اولد اقزام باي تشابتر جدا مفيييييييد انصحك فيه.\n3- الدكتور لا تدور من وراه شرح وحاول تضمن الكويزات لان الافرج بيكون مرتفع.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527838-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammed-gondal/68352/65", "user": "Guest", "ts": 1610484933000, "tid": 68352, "pn": 65}}]}', 1599071929000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fms1-phys102', 'stk-fms1', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68352", "n": "Dr. Muhammed Gondal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102-T202\n\nالتحضر: ينزل ككويز تحضير ببلاك بورد بعد بداية الكلاس ب20 دقيقه تقريبا و يجلس مده. و مرات اذ شاف الكلاس نايم و محد يتفاعل بقول ارفعو يدكم. و اذ فاتك كويز التحضير كلمه نهاية الكلاس و يفتحه لك.\n\nالكويزات: متوسطة الصعوبه و هي رتن فاينل انسر تجي كثير من الاولد و اذ جاوبت لكن جبت العيد بشي بسيط تقدر تكله و ضبطك. مره حليت و حطيت اس 3 بدل 1 و كلمته و ضبلي الدرجة.\n\nالشرح: بداية السمستر كان يفتح كام و يحل بصبورة مع سلايدات. لكن كلمناه و بعدها صار يحل بالسلايدات بالتابلت حقه و صار احسن بكثير.\n\nالدكتور حبوب مره و بس ينكت و هو من الدكاترة القدام جدا بالجامعة انصح فيه اذ كان ضابط مع جدولك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529889-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammed-gondal/68352/66", "user": "FMS1", "ts": 1620380508000, "tid": 68352, "pn": 66}}]}', 1620380508000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3489-phys102', 'stk-user3489', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68353", "n": "Dr. Mohammad Al-Jarallah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فيزيكس 102 … لكتشر…\n\nالتحضير :\nكل كلااااس … ويدقق على التأخير أحيانا …\n\nوأحيانا يسوي حركة عشان يصيد اللي يحضرون لغيرهم …\nوإذا صادك فإن هذا يترتب عليه عقوبات أذكر منها …\n-ياخذ آفرجك حق الكويزات كلها ولا يحذف ولا واحد …\n-يخصم كم هائل من درجات الكلاسوورك ما أذكر كم بالضبط …\n\nطريقة الشرح :\nمعاه نوت يقرا الكلام اللي فيه ويكتبه على السبورة ويستخدم الداتا شو …\nمع احترامي للدكتور كدكتور وأخلاق … كنت أشعر بالطفش في كلاسه … وأنتظر الكلاس يخلص …\n\nالكويزات :\nسهلة …\n\nالمياجر:\nكومن…\n\nالفاينلات :\nكومن…\n\nالقريد النهائي:\nC\nالصوت:\n\nواضح … لكن أحيانا الجملة أكثر من 3 مرات … عشنا يتذكر اللي بعدها 🙂 …\nوإذا ما فهمت يفهمك بالعربي …\n\nإضافات\n-يقدر الطلاب اللي يقعدون قدام ويشاركون…\n-يعطيهم هدايا عبارة عت “كتيبات” …\n-وفي آخر السمستر وزع علينا كتيبات كلنا…\n-يحل مسائل … وليس كما يقول البعض إنه مايحل أبدا… 😐 بس إذا ما كنت فاهم الدرس قبل الريسيتشن ماراح تفهم شي…\n-عنده كلمات يكررها كثيرا 😆 …\nإذا شاف أحد يشرب موية “ترا شرب الماء ممنوع في المحاضرة”…\nإذا شاف أحد حاط اصبعة بفمه… \" ترا أكل الأصابع ممنوع في المحاضرة \" 🤣 …\nإذا شاف أحد نايم “النوم سلطان … والله لا يسلط أحد علينا” …\nبعد أي نقطة “any question? …any body has any question?..ok…ifyou dont have any question then lets continue…”\n- أحد الدكاترة اللي صار له 20 سنة يدرس في الجامعة … يقولي “لما كنت طالب بكالوريوس… كان الجارالله التشيرمن حق الديبارتمنت”…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p418486-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-al-jarallah/68353/11", "user": "user3489", "ts": 1245750118000, "tid": 68353, "pn": 11}}]}', 1245750118000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdibr116-phys102', 'stk-abdibr116', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68353", "n": "Dr. Mohammad Al-Jarallah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "تقييم الطلاب للمدرس تعسفية بشكل ظالم 😐… وفي الحقيقة تجد معظم مشاكلهم من الإهمال\n\nأخذت PHYS102 معه (081) وكان من أفضل الدكاترة أخلاقاً… الشرح ممتاز لكنه سريع إن ضيعت كلمة ضاعت المحاضرة، وكنت أفهم معه لأني أستوقفه عند كل نقطة غير واضحة، وبذلك ستسفيد من العلم الذي لديه. الدكتور متعاون لأبعد الحدود بالخصوص في الساعات المكتبية، فإن كنت من أهل الصفوف الأمامية ومن أهل متابعة الشرح فلا تتردد بالتسجيل معه.\n\nكما قلت الردود مبالغ فيها ، والشرح يحتاج له متابعة شديدة.\n\nتحياتي 😎", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p518663-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-al-jarallah/68353/14", "user": "abdibr116", "ts": 1262891382000, "tid": 68353, "pn": 14}}]}', 1262891382000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-imported_kaka_22-phys102', 'stk-imported_kaka_22', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68500", "n": "Dr. Fuad M Enaya", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Lab phys 102\n\nالتحضير :\nتقريبا بنص الكلاس يبدا ينادي بالسيريل نمبر\nواذا خلصت او قربت تخلص تقدر تمشي ويعطيك فرصة الى ظهر اليوم الثاني عشان تسلم\nالريبوت بوضعه بصندوق عند مكتبه\n\nطريقة الشرح :\nمن 5 - 10 دقايق نقرا الدرس ثم يبدا يشرح , وشرحه حلو وبتفهم ان شاء الله معه\n\nالكويزات :\nكوزين بالسمستر ومتوسطة الصعوبة وتغطي الافكار الرئيسية لكمن مشكلتها ما يعطي وقت كافي\n\nالفاينلات :\nاعطانا اختبار صعب نوعا ما واسئلته كثير والوقت ساعة ولا تكفي بالمرة\n+ الاسئلة اللي تجي اختيارات ما يعطيك درجتها الا اذا شاف الخطوات << يعني الحظ والقس مايمشي\nلازم يشوف الخطوات و الحل النهائي …!\nوافرج اللاب جاء 10 …,\n\nالقريد النهائي: C+\nالصوت: واضح\nإضافات : يدقر (يستنشب) في التصحيح ,\nبس صراحه حبوب وتستمتع بحصته", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p764824-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fuad-m-enaya/68500/26", "user": "imported_KAKA_22", "ts": 1295225391000, "tid": 68500, "pn": 26}}, {"id": "stk-dr-f68353", "n": "Dr. Mohammad Al-Jarallah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "phys 102 << Lec\n\nالتحضير :\nيمرر ورقة وبعد مرور 20 دقيقة من الكلاس يبدا يحوس يدور لورقة التحضير\n+ احيانا ياخذ التحضير مرة ثانية بنهاية الكلاس\n\nطريقة الشرح :\nيستعمل ورق شفاف (ماادري وش يسمونه) + وشرحه للاسف ماينفع …!\n\nالكويزات :\nكثيرة مرة وبدون مبالغة كل اسبووع …! لكن نهاية االسمستر ماقصر قال باحسب لكل واحد\nافضل 5 كويزات 👍\n\nالقريد النهائي: D\n\nالصوت:\nيتكلم بسرعة الله يهديه ولا اقدر احيانا الحق مع\n\nإضافات :\nما انصح به …,", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p764826-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-al-jarallah/68353/17", "user": "imported_KAKA_22", "ts": 1295225859000, "tid": 68353, "pn": 17}}]}', 1295225391000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-satellite_ise-phys102', 'stk-satellite_ise', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68355", "n": "Dr. Guldad Khattak", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "من أفضل دكاترة الفزكس 102 و102 ودائما آفرج طلابه في المياجر والفاينل يكون مرتفع مقارنة بالبقية على الرغم من كوزاته الصعبة وتهزيئه وعصبيته لبعض الطلاب،،", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p380142-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/guldad-khattak/68355/10", "user": "satellite_ISE", "ts": 1236942546000, "tid": 68355, "pn": 10}}]}', 1236942546000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4626-phys102', 'stk-user4626', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68355", "n": "Dr. Guldad Khattak", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "phys102 في سمستر 101\n\nالتحضير : كل يوم و ما في أمل تحضر أحد و إذا تأخرت يطردك بدون تفاهم\nالشرح : من سلايدات الجلال إذا اشتغل البروجكتر و غالبا يكون خربان\nيعلمك كيف تستنج القوانين لكن الصراحة يدخل في تفاصيل مالها داعي\nالكويزات تقريبا الآفرج كان 0.5 من 5 يعني كلنا أصفااااار\nالدكتور تعامله جدا أبوي يعني يعاملك مثل عياله يعني تتهزأ كل شوي و أنواع المسخرة على الطلاب على مدار السمستر و يعلق على اي شئ (الملابس ، الشعر ،…الخ)\nلا أنصح به أبداااااااااااااااااااااااااااااااا فعلا كرهت الجامعة بسببه و بسبب تعامله\nإيجابية تذكر : قبل المياجر و الفاينل يختار اختبار يحله و من تجربة يختار شئ قريب من الأختبار الجاي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p775561-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/guldad-khattak/68355/34", "user": "user4626", "ts": 1296069667000, "tid": 68355, "pn": 34}}]}', 1296069667000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-penc1l-phys102', 'stk-penc1l', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68355", "n": "Dr. Guldad Khattak", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 101\nphys102\n\nالتحضير :\nشديد جداااا والي يصيدهم يحضرون يرسل اساميهم لشيرمن\n\nطريقة الشرح :\nالدكتور شريح يشرح بسليدات الجلال والسبوره واحسن مافيه يحلل لك مسالئل بلهبل بس بسرعه\nوقبل كل ميجر والفاينل يحل لك اولد اغزامس وبعد كل سكشن يحل كم مسئله اولد اغزامس بختصار مسالئل more than enough بس يبيلك تكون متابع معاه اول بأول لا تتوقع انك تفهم الدرس اذا كنت مش ملم بلماده من بداية الترم\n\nالدكتور في البدايه ماكن يشرح زين في اول الأسابيع بس بعدين تغير\n\nالكويزات :\nصلخ بس في الأخير افرج\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nمن افضل دكاترت القسم والموجودين حاليا\n\nالصوت:\n🤠 😆 😆 😆\n\nإضافات :\nالدكتور شايب له 25 سنه درس الجلال نفسه تسفيل في الطلابه ماهمه شي انتبه تخليه يعرفك لأنك لوكنت زين ولا شين راح تاكلها اسئله في كل لكشر\nكثير من الطلابه مايعجبهم بسبب اخلاقه لكن عندي الشرح اولاً اذا مالك نيه انك تكرف في الماده لا تنزل معاه لأنك راح تكرها :sneezing_face:\nفي الأخير ينصح فيه وبشده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p779546-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/guldad-khattak/68355/36", "user": "Penc1l", "ts": 1296473419000, "tid": 68355, "pn": 36}}]}', 1296473419000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-emperor-phys102', 'stk-emperor', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68355", "n": "Dr. Guldad Khattak", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ختك و ما ادراك ما ختك\n\nانا اخذت الفزكس 102 معاه في الترم الماضي\nقبل انزل عنده قريت انه شرييييييييييح و اخلاقه زفت\nقلت انا مافي مشكله بنزل عنده ما تهمني اخلاقه\nلكن للأسف طلعت الاخلاق اهم شي ختك اسوأ مدرس مر علي من ناحية الاخلاقفي دراستي الجامعيه\nيهزئك تهزيء مو طبيعي حتى لو كنت مهتم\nوالله في بداية السمستر كنت اذاكر كل تشابتر اول بأول\nو بسبب معاملة ختك السيئه كرهت الفزكس و طنشته\n\nنصيحتي للطلاب انهم يبعدون عنه لان الاخلاق مهمه كثيييييييييير عشان تتعامل مع الدكتور\nبالنسبه لكويزاته اذا بتذاكر تمام بتحل و ما اخفيكم ان فيها صعوبه\n\nاتمنى اني افدتكم و اللي محتاج معلومه عنه يراسلني ع الخاص", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p981270-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/guldad-khattak/68355/43", "user": "EmpeRoR", "ts": 1328570024000, "tid": 68355, "pn": 43}}]}', 1328570024000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo-da7m-phys102', 'stk-abo-da7m', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68506", "n": "Dr. R Khateeb", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت عنده لاب phys102 ; الفصل 132\n\nالتحضير :\n\nدقيق شوي\n\nأول ما يبدأ الوقت يحضر ويعطي كويز مدته خمس دقايق لو تتأخر 5 دقايق راح عليك الكويز\n\nطريقة الشرح :\n\nيكتب كل القوانين على السبورة بشكل واضح ومرتب جدا بعدين يشرح التجربة\n\nالكويزات :\n\nنص من الكتاب بس عشان يتأكد انك قريت التجربة قبل تجي\n\nالفاينلات :\n\nمتوسط ومفاجئ نوعا ما ( موب زي الاسئلة اللي اعتدت عليه باللاب ) ; بس ميزته عطانا 3 تجارب فقط\n\nالقريد النهائي:\n\nb+ إلى a\n\nالصوت:\n\nواضح\n\nإضافات :\n\n* أكبر مشكلة بهالشخص انه مراجي لحد بعيد ونفسيته سيئة … دايم يجي وكأنه مغصوب\n\n* أحيان يتقبل الاسئلة أثناء اللاب واحيان يرفض يجاوب على أي شي بحجة انه شرحه أول اللاب\n\n* أشوفه ممتاز وواضح بالشرح بس بعض التجارب مدري شلون جايه وتضطر تسأله بنص التجربة\n\n* ما يعطي كل الأسئلة اللي بالكتاب زي بعض الدكاترة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1376808-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-khateeb/68506/19", "user": "abo-da7m", "ts": 1401819613000, "tid": 68506, "pn": 19}}, {"id": "stk-dr-f68355", "n": "Dr. Guldad Khattak", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المقرر phys102 الفصل 132\n\n**التحضير :**دقيق وبشكل يومي … يسمح بالتأخر إلى خمس دقايق وبعده غياب ما عنده ليت\n\nيهزئك اذا تكرر تأخرك او بعض الاحيان لو تأخرت أول مرة !\n\n**طريقة الشرح :**سلايدات الجلال + يكتب ويحل مسائل بالسبورة\n\n**الكويزات :**متوسطة وأفكاره تختبر فهمك\n\n**المياجر:**مشتركة\n\n**الفاينلات :**مشتركة\n\n**القريد النهائي:**C+ إلى b\n\n**الصوت:**واضح جدا\n\nإضافات :\n\n* أسلوب تعامل سيئ ويصعب يمر الفصل ولا صار لك معه موقف وهزأك\n\n* شرح حلو لكن يخربه بهواشه وتهزيئه وعدم تقبله للأسئلة … يخلي الحصة كلله توتر ولا تقدر تفهم\n\n* أول الأيام ممكن تستانس وتضحك على أسلوبه بتهزيء الطلاب لكن اذا استمر الوضع طول الفصل تبدأ تطفش\n\n* أشوف طريقته تقليدية ويبغى الطلاب يكونون زي طلاب الثمانينات !\n\n* ما أنصح فيه أبدا اذا كنت تكره التحطيم والتهزيء اليومي\n\n* البعض يتقبل هواشه لأنه يشوفه زي أبوه اللي حريص عليه، بالنسبة لي أكره الشي ذا وأشوف اني مسؤول عن نفسي ولا احتاج أحد يصارخ علي عشان أشد حيلي\n\n* احتمال تقيمي موب موضوعي لأني متحامل عليه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1376812-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/guldad-khattak/68355/60", "user": "abo-da7m", "ts": 1401820259000, "tid": 68355, "pn": 60}}]}', 1401819613000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_169-phys102', 'stk-_169', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68355", "n": "Dr. Guldad Khattak", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "142 phys 102\nالتحضير : ورقة تمر ع الكلاس (ما انصحك تحضر احد لانه اذا صادك راحت عليك )\nطريقة الشرح : يشرح من نوتت الجلال , شرحه رهيب مايتفوت\nالكويزات :مدري من وين يجيبها بس من متوسطة الى صعبة\nالمياجر:كومن\nالفاينلات : كومن\nالقريد النهائي: ِA\nالصوت: واضح واحينا عالي جدا (مزعج)\nإضافات : الرجال حبوب في الاوفس بس في الكلاس متوحش , لاتقوله يعيد شرح نقطه توه شارحنها ولا تفكر في اي شي في كلاسه لانه إذا صادك وانت مشتت بيحرجك في الكلاس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1423737-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/guldad-khattak/68355/62", "user": "_169", "ts": 1439303034000, "tid": 68355, "pn": 62}}]}', 1439303034000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5430-phys102', 'stk-user5430', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68356", "n": "Dr. Akhtar Naqvi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فيزكس 102 … ترم 093\n\nالتحضير :\nيمرر ورقة ولا يضرب خبر للي يجي والا يروح …\n\nطريقة الشرح :\nممتآز … لكن لمن يشرح على اساس اننا فاهمين الفيزياء من الثانوي … وإنه جاي يراجع ويحل مسائل …\n\nالكويزات :\nماجربت … كان بس لكتشر\n\nالمياجر:\nفيزكس … 😆\n\nالفاينلات :\nفيزكس … 😆\n\nالقريد النهائي:\nb+\n\nالصوت:\nهندي … فلذلك اللغة والخط لك عليهآ … 🙂\n\nإضافات :\n\nالمسائل اللي يقول مهمة … تراها مهمه … 😉", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p687201-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/akhtar-naqvi/68356/30", "user": "user5430", "ts": 1282373727000, "tid": 68356, "pn": 30}}, {"id": "stk-dr-f73560", "n": "Dr. J Al-Sadah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فيزكس 102 ريسيتيشن بس … ترم 093\n\nالتحضير :\n\nيحضر كل كلاس بنفسه …\n\nطريقة الشرح :\n\nما عنده سالفه بإختصآر …\n\nالكويزات :\n\nبعضهآ صعبة وبعضهآ سهله … لكن تميل للصعوبة !\n\nالمياجر:\n\nكومن\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي:\n\nسي …\n\nالصوت:\n\nلهجته رائعه … وأحيانآ أعتقد ان القسم تعاقدوآ معه علشان لهجته موب فهمه في الفيزكس …\n\nإضافات :\n\nطيب … حبيب مرّة … إبتسامته تشرح الصدر … فك معاه سالفة ويمسك خط … 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p687204-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-sadah/73560/13", "user": "user5430", "ts": 1282374178000, "tid": 73560, "pn": 13}}]}', 1282373727000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6130-phys102', 'stk-user6130', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68356", "n": "Dr. Akhtar Naqvi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فيزكس 102 (093)\nالشرح : متوسط و ميزته يحل مسائل بعد النقاط المهمة 👍 بس يعيبه اللغة و إنك ما تقدر تكتب نوت معه\nالتحضير : لو تجي آخر دقيقة تقدر تحضر و يشيل غيابات زي الحلاوة ما بزي بعض الدكاترة الله يهديهم\n\" ما أقصد الكحيلي و ختك \" 😆\nالصوت : ينسمع حتى لو تقعد آ خر القاعة .\nإضافات : إذا قفل الكحيلي و عبد المنعم في 101 فسجل عنده لأن هو الأفضل بعدهم\nأما في الصيف و هو يدرس 102 في الصيف غالباً فلا بالله إذا كان منزل فلا يفوتك\nالقريد النهائي : +B\nو سلامتكم ،،،", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p690225-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/akhtar-naqvi/68356/31", "user": "user6130", "ts": 1282709536000, "tid": 68356, "pn": 31}}, {"id": "stk-dr-f80097", "n": "Dr. K Gasmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ريسانتشن فيزكس 102 \" 093 \"\nالشرح : طبعاً الريسانتشن كلاس حل مسائل بس الدكتور الله يهديه تحس يحل المسائل اللي \" معصي تجيك في المياجر \" و تحسه حافظ أكثر من فاهم باختصار إذا الريسانتشن كذا فسلم على الليكتشر .\nالتحضير : الكلاس صغير فيحضر بالأسماء .\nالكويزات : فالأخير بيعطيك على الأفرج 3 و ينزل اللي عندهم غيابات لأن كل الكلاس مفلل 5 من 5 في الكويزات \" من الغش \"\nإضافات : إذا شفته فاتح في الليكتشر فالله يعينك إذا نزلت عنده حاول تدور واحد أحسن منه و إذا ما قدرت حيل الله أقوى و ياليت الجامعة تحط معايير لاختيار الدكاترة .\nالقريد النهائي : -d\nو سلامتكم ,", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p690231-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-gasmi/80097/18", "user": "user6130", "ts": 1282710022000, "tid": 80097, "pn": 18}}]}', 1282709536000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr-za7ef-phys102', 'stk-mr-za7ef', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68356", "n": "Dr. Akhtar Naqvi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا الحين معاه في لاب phys 102 واشوفه ممتاز ويفهمك صح ولا يتفلسف واجد يعني يعطيك الزبده بس\nبس اذا تاخرت وانت تسوي التجربه يعصب ويجي يقعد على راسك\nاحسن ما فيه انه ما يخليك تكتب ثيوري ولا كنكلوجن يقول هالاشياء ما تهمه وما يحتاج تكتبهم واللاب على العموم يخلص بسرعه معاه\nتقدر تسجل معاه في لاب وتروح حق اي لاب ثاني اهو فيه يعني ما عنده مشكلة اذا بدلت بين اللابات بس اهم شي انك ما تغير واجد\nتقسيمه للدرجات 12% للريبورت + 3% كويزات ( 3 كويزات) + 5% لاب فاينل = 20%\nبس الغريب انه ما بقى الا لابين ولا عطانا ولا كويز فا ما ادري عنه شنو بيسوي الحين\nولاب فاينل ما حدده الى الحين\nانا ما اقدر احكم عليه الا بعد اللاب فاينل …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p747871-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/akhtar-naqvi/68356/34", "user": "Mr-Za7eF", "ts": 1292841487000, "tid": 68356, "pn": 34}}]}', 1292841487000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-equal-phys102', 'stk-equal', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68356", "n": "Dr. Akhtar Naqvi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فيزكس 102 ترم 102\n\nشنب في اللاب! تحضر مع اي سكشن من سكاشنه وفي اي وقت يناسبك … الميك اب عادي عنده … تصحيحه ممتاز … ما يطلب ثيوري وما يدقق في التصحيح … يشرح التجربة بالتفصيل وبشكل ممتاز … باختصار … دكتور رائع وانصح بالتنزيل معه …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p836157-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/akhtar-naqvi/68356/40", "user": "equal", "ts": 1303560339000, "tid": 68356, "pn": 40}}]}', 1303560339000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdelaziz-phys102', 'stk-abdelaziz', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68356", "n": "Dr. Akhtar Naqvi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS 102 - Term 143\n\nالتحضير :\nورقة تمر عالطلاب وتوقع عليها\nلو تجي قبل نهاية الكلاس ب خمس دقايق توقع وتمشي ماعنده مشكلة 😆\n( متسااااااااااااااااااااااااااااااااااااااااااااااااااااااااااااهل جداً في التحضر والغياب )\n\nطريقة الشرح :\nيشرح من السلايدات وشرحه مب سيء\nويكتب على السبورة كثيير … كتابته ملخبطة جداً ومزعجه وصعب تاخذ نوت معاه\n\nالكويزات :\nهو كان مدرس الريسايتيشن\nكويزاته كانت نماذج\nكانت تختلف صعوبتها بين نموذج ونموذج !!؟\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nB\n\nالصوت:\nالاكسنت حقه مضروب شوي 🙂\nبس مسموع للكل\n\nإضافات :\nمتساهل مع الطلاب خاصة في الحضور والغياب لدرجة السباكة << آسف على هالكلمة يا د.نقفي 🤠 🤠\nعادي تجي وتتكي عالجوال مايقول شي\nعادي تجي نهاية الكلاس توقع وتمشي\nأهم شي تحضر وتنتبه معاه بكل تركيزك تراه يقول أشياء مهمة\nمو لازم تكت أهم شي ذهنك يكون معاه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1432219-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/akhtar-naqvi/68356/43", "user": "Abdelaziz", "ts": 1446741531000, "tid": 68356, "pn": 43}}]}', 1446741531000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_nd_m-phys102', 'stk-m_nd_m', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f78123", "n": "Dr. Khalil Harrabi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS 102 Lab - T153\n\nالتحضير : -\n\nطريقة الشرح : سريع جدًا جدًا… تقول قاعد يتسابق\n\nالكويزات : متوسطة - سهلة و بعضها عملية… خصوصًا السيركتس\n\nالمياجر: -\n\nالفاينلات : الفاينل كان دسم… و حدد لنا 4 تجارب (آخر 4 تجارب) + الـUncertainty\n\nالقريد النهائي: C+\n\nالصوت: واضح جدًا… أكسنت جزائري والله أعلم\n\nإضافات :\nأخلاقه… زفت بمرتبة شرف… مادري ليه… اذكر مرة كان كاتب على السبورة ارسموا A vs B قلت له دكتور مكتوب بالمانيوال أنه B vs A و خذلك تهزيء… ليه طيب؟\nما كان محدد مواعيد الكويزات… أحيانًا يقول مافي كويز اللاب الجاي تجي تتفاجأ في كويز !\nالدكتور حاط بمخه أنك المفروض فاهم كل شي يقوله 101% و يستغرب منك إذا ما فهمت… و أيضا شرحه العملي سريع جدًا… يعني اصبر أعطينا فرصة !\n\nللإنصاف… ما يتأخر بتصحيح الريبورتات… والتصحيح ممتاز و أهم شي عنده الـPercent Difference\n\nبالنسبة للميك أب… مع مزاجه المتقلب ماتدري أنت و حظك… لكن في مرة شفت طالب من شعبة ثانية حضر بشعبتنا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1456108-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalil-harrabi/78123/73", "user": "M_nd_m", "ts": 1472455621000, "tid": 78123, "pn": 73}}, {"id": "stk-dr-f68356", "n": "Dr. Akhtar Naqvi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 Lecture - T153\n\nالتحضير : ورقة تمر على الطلاب و ولا مرة شيك على الحضور… ما عنده أي مشكلة تتأخر ان شاء الله تدخل اخر دقيقة He doesnt care… هذه أهم ميزة بالدكتور لأن الواحد أحيانًا يتأخر\n\nطريقة الشرح : على السبورة و لما يخلص يمر على السلايدات لتثبيت المعلومات و يحل اكزامبلز الكتاب… و قبل الميجر بيوم يومين يحل اولد اكزامز… بشكل عام جيد\n\nالكويزات : الريسايتيشن كانت عند دكتور ثاني\n\nالمياجر: -\n\nالفاينلات : -\n\nالقريد النهائي: Very good B\n\nالصوت: واضح… أكسنت هندي والله أعلم\n\nإضافات : الدكتور حبيب… فاهم زين و يفهم أسئلة الطلاب على الطاير و يجيب عليها بشكل واضح و ما يحاول يتهرب من الجواب… صاحب ابتسامة و يقط كلامات بالعربي بين الفينة و الاخرى\n\nمن الآخر… إذا ما لقيت غيره أو محتار بينه و بين واحد سيء نزل عنده بدون أي تردد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1456418-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/akhtar-naqvi/68356/44", "user": "M_nd_m", "ts": 1472766996000, "tid": 68356, "pn": 44}}]}', 1472455621000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2728-phys102', 'stk-user2728', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68358", "n": "Dr. Khalil Ziq", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS 102- Lab\n\nلاب فزكس 102\nالتحضير :\nإلزامي\n\nطريقة الشرح :\nلاب غالبا يشرح الثيوري على السبورة ويعلمنا إيش المطلوب من التجربة\nلكن التجربة ما يعلمنا كيف نسويها ولا يورينا كيف نسويها\nفهالحركة سيئة جدا كرهتني بالمادة وباللاب لأنها خلتني أعتمد على غيري في التجربة وأنا أناظر فيه بس !\nيتكلم عربي بعض الأحيان\n\nالكويزات :\nما فيه\n\nالمياجر:\nمافيه\n\nالفاينلات :\nكان كتابي عن أحد التجارب (وكانت على الطول الموجي وتجربة ثانية ناسيها)\nالإختبار كان مطبوع ومرفق لك ورقة الرسم ومعطيك الداتا كلها في جدول وأنت عليك ترسم المعطيات وتوجد المجهول وتحسب نسبة الخطأ\nوفيها بعض الأسئلة إللي تحتاج جواب كتابي بس سهلة\nبشكل عام الفاينل سهل ومريح وما يحتاج تذاكر له فقط تحفظ المعادلات\n\nالقريد النهائي:\nb\n\nالصوت:\nواضح ويتكلم عربي وتقدر تكلمه عربي ويرد عليك عربي\n\nإضافات :\nالشغل يكون مع مجموعة لكن الريبورت يكون فردي\nوكل واحد له تعبير خاص فيه عشان ما يقول غاشين\nالتصحيح متأخر وما يعطي الريبورتات إلا بعد أكثر من أسبوع\nالقريدات أفرج يعني حقك بتأخذه زي ما هو مقارنة مع غيرك\nما أنصح فيه إذا كنت تبي تفهم وتكرف في اللاب وتعرف ليش تسوي هالشيء ومعلمك كيف تسوي التجربة\nأنصح فيه إذا أنت تبي كل المميزات في مدرس اللاب لكن بدون ميزة الشرح والكرف والتفهم وعمل التجربة من قبل الدكتور !\n🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p972160-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalil-ziq/68358/25", "user": "user2728", "ts": 1327259342000, "tid": 68358, "pn": 25}}]}', 1327259342000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12136-phys102', 'stk-user12136', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68358", "n": "Dr. Khalil Ziq", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "phys102 term 202 online\n\nطريقة الشرح : سيء جدا جدا جدا وشرح يجيب النوم\nالكوزات تعتبر وسط\nالتعامل: حبيب وخلوق ومتواضع ويرحب بأي سؤال\nالقريد النهائي: D\nالصوت: يجيب النوم\nإضافات : ما بتفهم شي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533415-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalil-ziq/68358/39", "user": "user12136", "ts": 1641983932000, "tid": 68358, "pn": 39}}]}', 1641983932000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_ali-phys102', 'stk-abo_ali', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68363", "n": "Dr. Mohamed Faiz", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 112\nفيزكس 102\n\nالتحضير :يوميا ومشدد عليه\nيحضر بعد ما يدخل الكلاس عن طريق برنامج اكسل في الكمبيوتر\n\nطريقة الشرح :\nيشرح عن طريق سلايدات الجلال المعروفه\n\nالكويزات :\nكوز كل شبترين\nاسله شوية صعبه “اسئلة مياجر” واغلبها تشابه الاسئلة اللي يشرحها في الرسايتيشن\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومون\n\nالقريد النهائي:\nB+\n\nالصوت:\nواضح لكن الله يعينك على اللهجه اللي ما ادرس وش تبي , في اول الامر بيكون غريب عليك لكن بتتعود عليه فلا تشيل همها ابد\n\nإضافات :\nالمدرس فاهم وشريح ويمشي على النظام\nاخلاقه زينه ما اذكر ان طلع منه اي تصرف سلبي\nلكن التحضير عنه شيء مقدس والليتات يا كثرها “خاصه لمن يكون كلاسك الساعه 7 الصبح”\n\nسلامتكم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1047383-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-faiz/68363/26", "user": "Abo_Ali", "ts": 1338283733000, "tid": 68363, "pn": 26}}]}', 1338283733000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user1326-phys102', 'stk-user1326', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68374", "n": "Dr. Mohammad Al-Kuhaili", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير :\nالتحضير يكون ورقة تدور على قاعة الفيزيكس وتوقع عند الاي دي … بس يشيك احيانا اخر الكلاس على اللي حاضرين … يعني بالعربي لاتحاول تحضر خويك\n\nطريقة الشرح : شرح ممتاز وانا اشوفه افضل مدرس فيزيكس بالذات phys102 … يكتب ع السبورة وحاول تكتب النوت حقه\n\nالكويزات : متوسطة … واللي بيفهم في الكلاس بيشوف الكويزات سهله\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: الكورس ستاندرد\nالصوت:\nإضافات :", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p342891-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-al-kuhaili/68374/2", "user": "user1326", "ts": 1230038961000, "tid": 68374, "pn": 2}}]}', 1230038961000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2872-phys102', 'stk-user2872', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68374", "n": "Dr. Mohammad Al-Kuhaili", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : ورقة تمر بين الطلاب وبعض الاحيان ينادي على الطلاب آخر الكلاس ويكون عنده قائمة معينة يكررها\nطريقة الشرح : اول ربع ساعة شرح على السلايدز , بعدين يكتب اللي شرحه على السبورة ويحل مسائل … ويعطي هيلب سشن على بعض التشابترز اللي ما يمديه يغطي مسائلها في الكلاس , وفي الريستيشن من يبدأ الكلاس الى ان ينتهي وهو يحل مسائل , باختصار المسائل عنده بالهبل\nالكويزات : متوسطة وعلى حسب أفرج الكلاس , اذا الافرج عالي يشعللها بين الطلاب , لكن انا اشوف انها متوسطة\nالمياجر: كومن لكن أكثر الأسألة يكون مر عليها في الكلاس قبل\nالفاينلات : كومن\nالقريد النهائي: كومن لكن أفرجه يعتبر من الأعلى بين السكاشن\nالصوت: يستخدم مايك\nإضافات : أنا أعتبره الملك في phys102", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p343883-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-al-kuhaili/68374/5", "user": "user2872", "ts": 1230287412000, "tid": 68374, "pn": 5}}]}', 1230287412000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user1906-phys102', 'stk-user1906', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68374", "n": "Dr. Mohammad Al-Kuhaili", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم\n\nالدكتور محمد متمكن في الشرح بشكل كبير ولكنه يفسد ذلك بشكل كبيييييييير جداً بسبب تعامله الجاف المبالغ فيه…\n\nبالإضافة إلى أن الإبتسامة لديه قليلة جداً بالرغم من أنه يمتلك ابتسامة ساحرة…😦\n\nعندما درسني قمت بعدّ ابتساماته(وليس ضحكاته) طوال الفصل الدراسي وساعدني في ذلك اثنين من الشباب…\n\nيعني بحسبة بسيطة: 15 أسبوع=45 محاضرة+ الرسيتيشن\n\nنقول المجموع على الأقل 55 محاضرة ورسيتيشن\n\nكم تتوقعون وصل عدد ابتساماته ؟🙂\n\n40 ابتسامة!!!!!!!!!!!!!\n\nيعني 15 محاضرة بدون ابتسامة!!!!\n\nقليل مرة هاه؟\n\nالحقيقة إن عدد ابتساماته ماكانت 40 ؟؟؟؟\n\nكانت 21 ابتسامة فقط !!!!!\n\nو ضحكة وحدة فقط في أحد حصص الرسيتيشن بعد محاولة ناجحة مني في سرقة تلك الضحكة منه!!!\n\nحتى الشباب بعد الرسيتيشن قالوا: ماشاء الله قدرت تضحكه!!!\n\nالله يذكره بالخير كان يدخل ويشرح مباشرة وبسرعة ثم في الأخير أحياناً يحضر…\n\nوالله أعلم كان يشم ريحة الطلاب الغايبين 😆 …لذا لا تحاول تحضر خويك…\n\nأيضاً…كان يشرح لمدة 50 دقيقة…يعني مافيه مجال يتكلم عن شيء خارج المنهج…وهذا أعتبره خطأ كبير…\n\nأحياناً أحس أن من كان أمامي هو رجل آلي تم وضع أحد سيديات الفيزيكس في داخله !!!\n\nربما السبب في ذلك أنه اعتاد أن يشرح PHYS102 لمدة طويلة وقد تبرمج عقله على ذلك…\n\nقد يقول البعض أن الدكتور يريد أن يشرح كثير من الأمثلة و الوقت لا يكفي…\n\nعذراً أحبائي…هذا غير صحيح…لأني أجزم أن مهمة الأستاذ أعظم من أن يكون شارحاً للمنهج فقط…\n\nأين التفاعل مع من أمامك بأكثر من طريقة؟ أين التفاعل مع مايحدث في الجامعة أو في المجتمع أو في العالم؟\n\nوالله لو تجاوز الدكتور محمد هذه النقطتين(الابتسامة,التفاعل مع الأحداث الغير متعلقة يالمنهج) لكان ملك الفيزيكس 🤴\n\n*****\n\nيتميز الدكتور بأمرين: سرعة رصد درجات الكويزز ماشاء الله عليه…\n\nواستطاعتك أخذ الكويزز المتغيب عنها سماحتكم ولكن التصحيح من نصف الدرجة…\n\nبالرغم من حصولي على درجة عالية في تلك المادة فلو استقبلت من أمري ما استدبرت لما أخذت المادة مع الدكتور محمد…\n\nوعلى تواصل إنساني نلتقي…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p369909-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-al-kuhaili/68374/14", "user": "user1906", "ts": 1235122195000, "tid": 68374, "pn": 14}}]}', 1235122195000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah2015-phys102', 'stk-abdullah2015', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68374", "n": "Dr. Mohammad Al-Kuhaili", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده PHYS 102 ترم 162\n\nالتحضير :\nورقة تمر على الطلاب، وتقريبًا كل يوم خميس يحضر بالأسامي عشان يتأكد إن ماحد حضر زميله، طبعًا أحيانًا يسويها مفاجئة ويحضر بالأسامي يوم الأحد أو الثلاثاء.\nنظامه إذا أحد حضر لك المرة الأولى، تحذير + تخسر فرصتك في الأب قريد، أما إذا أحد حضر لك مرة ثانية، راح يحول موضوعك على شؤون الطلاب.\n\nطريقة الشرح :\nطريقة شرحه أول شيء يقرأ من السلايدات ويعلق عليها، بعدين يكتب نوت بيده على السبورة.\nطريقة شرحه مقبولة وجيدة.\n\nالكويزات :\nعطانا 10 كويزات، أغلبها كان سهل إلى متوسط … وفيه كويزين أو ثلاثة كانوا صعبين جدًا، أتوقع عشان يضبط الأفرج والله أعلم.\n\nالمياجر:\nكومون\n\nالفاينلات :\nكومون\n\nالقريد النهائي:\nB+\n\nالصوت:\nصوته واضح وإنجليزيته ممتازة.\n\nإضافات :\n- من مميزات الدكتور إنه جدًا منظم، يعني من بداية السمستر يعطيك ورقة “جدول” فيها تواريخ الكويزات وماتيريال كل كويز، ويحدث الدرجات والغيابات في البلاك بورد بشكل دوري، يعني بضغطة زر تقدر تعرف اللي لك واللي عليك.\n- الدكتور أيضًا يرفع على البلاك بورد شغلات مفيدة مثل أولد إقزامز محلولة وملخصات لماتيريال ميجر 1 و2 والفاينل، وشغلات أخرى مفيدة بشكل العام.\n- من مميزات الدكتور وتفانيه في العمل إن تلاقي السلايدات اللي يشرح منها محدثة بشكل دوري، أي شيء طارئ أو جديد تشوفه في أحد السلايدات، يظهر من هذا إنه يحضّر لكل محاضرة بشكل جيد.\n- بخصوص نظامه في المحاضرة فعنده عدة قوانين لازم تتبعها، فمثلًا:\n- ما يسمح بالتأخير، يعني تأخير أبو دقيقتين أو ثلاث دقائق يسمح به عادي، بس إذا تعدى ال10 دقائق ما راح يسمح لك تدخل الكلاس، وراح يقول لك:\nYou can leave please\n- الجوالات ما يسمح بها أثناء المحاضرة، وراح تسمع هذي العبارة كثير:\nSwitch off your mobiles please\nطبعًا ما يمانع تستعمل الجوال إذا كان بغرض تصوير السبورة فقط.\n- ما يسمح بالمشروبات في الكلاس.\n- بخصوص شرحه يغلب عليه الجدّية، ما هو من النوع المرح والفلة (إذا كان يهمك). يعني بالغلط نكتة أو قطّة كذا مضحكة في الشهر مرة.\n\nفي الأخير أقدر أقول أنصح به، لكن لازم تعرف إن الفيزكس يعتمد بشكل كبير على شغلك برا الكلاس مب على الدكتور، لأن المادة ثقيلة وتحتاج إلى متابعة بشكل دوري.\n\nبالتوفيق للجميع 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474580-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-al-kuhaili/68374/93", "user": "Abdullah2015", "ts": 1496689129000, "tid": 68374, "pn": 93}}, {"id": "stk-dr-f99858", "n": "Dr. Faris Al-Matouq", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS 102 LAB TERM 162\n\nالتحضير :\nنظامه كل لاب يكون في بدايته كويز، يحضر الطلاب بالكويز ولو تأخرت راح يحضرك لكن الكويز يكون راح عليك.\n\nطريقة الشرح :\nيشرح الكونسبت اللي له علاقة بالتجربة، ثم يقوم بشرح خطوات التجربة عمليًا.\n\nالكويزات :\nالكويزات فيه السهل وفيه المتوسط، والأغلب صعب.\n\nالفاينلات :\nالفاينل لاب كان وسط.\n\nالقريد النهائي:\nB\n\nالصوت:\nواضح.\n\nإضافات :\nدكاترة اللاب نوعين، نوع يخلي الوضع سهالات على الكل وفي الأخير درجات الطلاب تصير كلها حول ال14 بعد الnormalization\nوفيه نوع ثاني اللي يصعب الأمور بحيث المجتهد يفرق عن اللي يلعب، يعني بعد الnormalization درجتك بتصير تقريبًا زي ما هي لكن مع زيادة أو نقصان بالفواصل (أقل من 1.00).\n\nوالدكتور فارس من النوع الثاني، بحيث إنه يصعب ويسهل الأسئلة عشان يضبط الأفرج على 14 والمجتهد ياخذ نصيبه واللي يلعب يأخذ نصيبه\nفي رأيي الدكتور جدًا ممتاز للطلبة اللي شادين حيلهم، وفي الوقت نفسه ما أنصح به للي مو ناوي يشد حيله معاه.\n\nعلى أي حال عادة ديبارتمنت الفيزكس إنهم ما يعلنون أسماء دكاترة اللابات إلا بعد بداية ما يبدأ السمستر … فأنت ما جيت هنا إلا إنك already مسجل عنده يا قارئ الرد\n\nفأقول لك شد حيلك معاه وإن شاء الله راح تشوف اللي يسرك.\n\nبالتوفيق للجميع 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474596-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faris-al-matouq/99858/20", "user": "Abdullah2015", "ts": 1496706339000, "tid": 99858, "pn": 20}}]}', 1496689129000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-majeed5-phys102', 'stk-majeed5', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68374", "n": "Dr. Mohammad Al-Kuhaili", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102- T182\n\nالتحضير: يمرر ورقة\nالشرح: الشرح ممتاز ومرتب ويحل مسائل على السبورة بشكل منظم فيمديك تصورها عشان تراجع منها\n\nالكويزات: الكويزات متوسطة ويمدي تجيب فل لو مذاكر ومتدرب كفاية\nالمياجر: كومن\nالفاينلات: كومن\n\nالقريد النهائي: A\n\nالصوت: ممتاز", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529300-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-al-kuhaili/68374/101", "user": "majeed5", "ts": 1617389448000, "tid": 68374, "pn": 101}}]}', 1617389448000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_mag-phys102', 'stk-mohammed_mag', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68374", "n": "Dr. Mohammad Al-Kuhaili", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102- T203 ONLINE\n\nالتحضير: يحضر تلقائي في مايكروسوفت تيمز , ماينادي بس يحمل ملف الحضور .\n\nالشرح: جدا جميل وواضح وكافي , لكن مع الصيفي اختصرتها سيلف ستدي مع تجميعه روابط هو مرتبها لليوتيوب عنده مثل \" شرح اولد باي تشابتر \" \" شرح كونسبت \" شرح … \"\nبتغرق من الريسورزس الي موفرها لك الكحيلي الله يحفظه\n\nالكويزات: يكرف بالصيفي عطانا كويزين بالاسبوع , واتوقع بالترم العادي كويز لكل اسبوع , منها السهل ومنها الصعب على حسب الافرج يضبط .\n\nالميد تيرم : صعب جدا جدا الأفرج نازل\n\nالفاينلات: سهل جدا\n\n^\nللتوضيح … الميد تيرم كان صعب سوو بعدها الكثير دروب ولما خلو الفاينل سهل ارتفع الافرج بقوه مره\n92 A+\n85 A\n77 B+\n69 B\n60 C+\n52 C\n\nالقريد النهائي: B\n\nالصوت: جدا واضح وصافي .\n\nاضافات:\n\nالدكتور حبيب جدا ومتعاون , انصحك عن تجربه أن اذا انت من نوع تركز بالكلاس مب سيلف ستدي , لا تنزل الا عنده\nإذا انت تبي تريح نفسك سيلف ستدي , نزل عند دكتور ثاني قليل كويزات وحاول تحمل ريسورزس حقت الكحيلي . وبس والله موفقين .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531199-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-al-kuhaili/68374/103", "user": "Mohammed_Mag", "ts": 1628747655000, "tid": 68374, "pn": 103}}]}', 1628747655000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr_exceptional_stude-phys102', 'stk-mr_exceptional_stude', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68374", "n": "Dr. Mohammad Al-Kuhaili", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 - term 212\nما أزيد على نفس الكلام، الدكتور صار أفضل بعد، وكويزاته صارت أفضل. الدفعة كلها معتمدة عليه وبدونه ما كان عرفنا نذاكر للمياجر والفاينل. الله يجزاه خير، وبتكون أفضل فرصة للي يقدر ينزل عنده. نصيحة بسيطة، إذا نزلت عنده فركز وقت اللكشر عشان مو قبل الميجر والفاينل ترجع تشوف لكاشره نفسها باليوتيوب وأنت دارس عنده، حرام.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534394-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-al-kuhaili/68374/105", "user": "Mr_Exceptional_Stude", "ts": 1653314449000, "tid": 68374, "pn": 105}}]}', 1653314449000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ambitious_91-phys102', 'stk-ambitious_91', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68377", "n": "Dr. Nabil Maalej", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "يالله ذا الدكتووور شريييح ومتعاون وخلوق, اخذت معاه فيزياء 102 لكشر فقط دون لاب ايام الفرشمن,\n\nالتحضير: عادي يحضر ومتسامح أحيان , بس لا تغيب وتسحب عليه زي الورعان.\nالشرح: توب دكتور يفهم و يوصل المعلومه ويكفي انه دكتور ويكفي انه فاهم ويفهم كويس.\nاللي يقول مو شريح ما عنده سالفه ابدددد…\n\nالله يستر عليه بقيلي كم درجه على الأب قريد وغياباتي تعدت ال 5 صارت 7 , رحت وكلمته عليها والحمد الله ما قصررررر, وطلعت من عنده a + 🙂\n\nوالله في دكاتره آخرين لو يبقالك درجه واحده فقط على الأب قريد ما يعطيك هي ولا يمسح لك غياب واحد بس عشان لا تاخذ الأب قريد.\n\nلكن هذا الله يوفقه فعلا يستحق كلمة دكتور ومعلم بكل شرف.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1378410-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nabil-maalej/68377/12", "user": "ambitious_91", "ts": 1402239520000, "tid": 68377, "pn": 12}}]}', 1402239520000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-medoalkebsi-phys102', 'stk-medoalkebsi', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68377", "n": "Dr. Nabil Maalej", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فزكس 102\nالتحضير : ينادي بالاسماء , تقريبا بشكل يومي اوقات ينسى.\nطريقة الشرح :عنده سلايدات جلال + كنوار , دامجهم مع بعض ومعدل فيهم , يشرح منهم.\nالكويزات :سهله من اسئله الهومورك.\nالمياجر:كومون\nالفاينلات :كومون\nالقريد النهائي:a+ , ويستاهل اكثر .\nالصوت:واضح\nإضافات :\n\nالادمي فااااااااهم صحح الكورس شرحه جدآ مممتاز, ببدايه الصيف كنت مركز معه وافهم من 90-95% من اللكتشر . ارجع الغرفه ما اتعب كثير غير احل اسئله , بعدين يوم بديت ماعاد اركز صرت اخذ وقت اطول بالمذاكره.\n\nانصح في في اللكتشر كثيييييييييييييييير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1389580-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nabil-maalej/68377/13", "user": "Medoalkebsi", "ts": 1407938278000, "tid": 68377, "pn": 13}}]}', 1407938278000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-man.moh-phys102', 'stk-man.moh', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68377", "n": "Dr. Nabil Maalej", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS 102 - 172\n\nالتحضير : بدايه السمستر كان متساهل معه , بس شاف الطلاب مصخوها صار يحط منبه بجواله اول خمس دقايق وبعدها يسحب الورقة التحضير.\nوبعد كم اسبوع زهق وصار مايهتم للتحضير.\n\nطريقة الشرح : بس يقلب ويقرا السلايدات , يجيب النوم بشكل مب طبيعي , ولا يحل مسائل الا بالرستيشن , ولا يكتب بالسبورة الا ما ندر , لكن بالريستيشن مبدع وكلمه مبدع قليلة بحقه. نظامه يقسم السكشن الى قروبات ويعرض سؤال ويخلي الطلاب يحلونه والي يحل اول يعطيهم نقاط , وبعدها يجي ويشرح الاسئلة الي انحلت.\n\nالكويزات : ببداية السمستر كانت جدا جدا سهله, بس صار الافرج جدا مرتفع وقعد يجلد بالكوزات نهايه السمستر.\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: B+\n\nالصوت: يجيب النوم\n\nإضافات : الدكتور اخلاق ماله حدود , ويرحب فيك وباي سؤال بالاوفيس. ويعمل هلب سيشن قبل المياجر والفاينل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492592-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nabil-maalej/68377/15", "user": "Man.Moh", "ts": 1526560982000, "tid": 68377, "pn": 15}}]}', 1526560982000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4513-phys102', 'stk-user4513', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68378", "n": "Dr. Abdelkrim Mekki", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "في البداية اتفق مع الجميع إنه من أفضل دكاترة القسم من ناحية الشرح\n\nلكن مع إحترامي له يحسسك إنه القريد اللي تطلع به بنهاية الكورس من جهده الشخصي وليس من جهدك\n\nيعتقد إنه هو صاحب اليد الطولى في هالشي\n\nلمن طلع القريد حقي في فزكس102 هالسمستر سألني عنه قلت له a+ قالي وبكل ثقة والله هالدرجة ما تحصلها مع واحد غيري\n\nلكن من سوء حظه إني حتى في فزكس 101 طلعت بــ a+\n\nاحس يوم قلت له هالشي طاح وجه\n\nولا انسى اقول إنه يحب يهزئ كثييييير تقريباً وإن ما خاب ظني هالسمستر قالي 3 مرات أو اربع ( روح اشتغل في سوق الخضار )\n\nوفي الاخير طلعت بــ a+ خليت سوق الخضار له", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p365947-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdelkrim-mekki/68378/17", "user": "user4513", "ts": 1234307145000, "tid": 68378, "pn": 17}}]}', 1234307145000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10578-phys102', 'stk-user10578', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68378", "n": "Dr. Abdelkrim Mekki", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فيزيكس 102 - 162\n* شديد بالتحضير و بقوة ، ما يسمح لاحد يتأخر واذا تاخرت بتسمع كلام مو حلو منه ، لكن تقريباً باخر شهر بالترم صار يتغاضى عن اللي يتأخرون 5 ، 6 دقائق\n* اظنه بنهاية الترم حذف غياب عن كل طالب\n* الدكتور الوقت مهم جداً عنده وما يبي تضيع أي ثانية بالكلاس\n* الشرح متعوب عليه ، ممكن اكثر مدرس مر علي يتعب بالشرح علشان الطالب\n* الشرح يكون عبر سلايدات الجلال و اذا انتهينا من الشابتر يحل مسائل صعبة من الكتاب\n* الكويزات افضل شيء بالمدرس ، الكويزات تقدر تقول سهلة جداً مقارنة بالمسائل اللي نحلها بالكلاس ، افرج سكشنا اذكر كان 6.7 و نقص كل واحد 0.7 .\n* الصوت وااااضح وضوح الشمس ( شوي عربي شوي انجليزي )\n* ممكن يسمح بالميك اب بالرستايشن لكن قبلها بتسمع محاضرة منه\n* الجوال حرام و ممنوع استخدامه بالكلاس منعاً باتاً\n* يسمح باخذ صور للسبورة بل يحث على تصوير السبورة و ارسالها لقروب الواتساب الخاص بالسكشن\n* الدكتور طيب و كريم لكن مشكلته بلسانه شوي\n* أهم نصحية هي انك تنضبط معاه و ما تتأخر او تمسك الجوال فاذا اخذ فكرة سيئة عنك بتستمر لنهاية الترم\n* في النهاية من افضل المدرسين اللي مروا علي الجامعة و يستحق كل خير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473894-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdelkrim-mekki/68378/61", "user": "user10578", "ts": 1495876810000, "tid": 68378, "pn": 61}}]}', 1495876810000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hamza_alnasser-phys102', 'stk-hamza_alnasser', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68382", "n": "Dr. Zain Yamany", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 Term 152\n\nالتحضير : ورقة توقيع تمر ع الطلاب\nطريقة الشرح : يشرح المفهوم وبعدين يكتب القوانين ع السبورة ويشرحها. بس طريقة غير منظمة في الشرح. يعني ساعات يخطر أشياء ويرجع لها بعدين.\nالكويزات : -\nالمياجر: -\nالفاينلات : -\nالقريد النهائي: B\nالصوت: Clear\nإضافات : يحتاج تحضر قبل تروح الكلاس لأنك ما راح تفهم وش قاعد يقول, لابد تكون عندك خلفة عن الموضوع من قبل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1446382-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/zain-yamany/68382/10", "user": "Hamza_Alnasser", "ts": 1460375318000, "tid": 68382, "pn": 10}}]}', 1460375318000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a.ee-phys102', 'stk-a.ee', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68382", "n": "Dr. Zain Yamany", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102 - T152\n\nالتحضير : يومي وحريص في أخذ التحضير والتأخير ، كان يتضايق من الطلاب اللي يتأخروا عنده\nطريقة الشرح : يكتب القانون وعادة يكتب طريقة اشتقاقه بعدين يبدأ يشرح معناه في الواقع\nالكويزات : ما كان له علاقة فيها … دكتور ثاني كان يعطينا الريسايتيشن\nالمياجر: -\nالفاينلات : -\nالقريد النهائي: A\nالصوت: واضح ولغته جداً ممتازة ماشاء الله تبارك الله\nإضافات : -كانت حصته بالنسبة لي ممتعة جداً وتحتاج إلى شوية خيال عشان تشبك معاه في الشرح\n-كنت مبسوط جداً على إن الدكتور كان يتعدى في شرحه المنهج وهذا الشيء كان يضايق كثير من الطلاب ، لكن بالنسبة لي كنت مستمتع وكنت لما أرجع أحل المسائل مرات ، أتفاجئ إنه هذا النوع من المسائل بس اللي مقرر علينا واللي أقدر أعتبره “special case” من شرح الدكتور\n-الدكتور ما كان يأخذ من وقت الحصة لحل المسائل ، لكن كان يحل من سؤال لثلاثة قبل الكلاس مع إن كلاسه كان الساعة 7\n-كان الدكتور يصوت مع الطلاب تقريباً بشكل أسبوعي إنه يعمل لهم هلب سيشن ، وكثير من المرات ما يكون العدد كبير فيتكنسل !\n-الدكتور كان يذكر الطلاب دايماً بالأوفيس أور لكن قليل اللي كانوا يروحوا له وأنا منهم لأنها كانت تعارض كلاسي ، لكن للأمانة المرات اللي رتبت مع الدكتور موعد كنت أطلع بفائدة جداً كبييرة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1457214-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/zain-yamany/68382/14", "user": "A.EE", "ts": 1473292136000, "tid": 68382, "pn": 14}}]}', 1473292136000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10330-phys102', 'stk-user10330', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68382", "n": "Dr. Zain Yamany", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102 - T161\n\nالتحضير: يوميا + شديد في التحضير ويكره احد يتأخر عنده .\nطريقة الشرح : غالبا شرحه شفوي وما يكتب في السبورة الا كيف جاء القانون أو رسومات توضيحية\n**الكويزات :**متوسطه.\n**المياجر:**كومن\n**الفاينلات :**كومن\nالقريد النهائي: C\nالصوت: واضح\nإضافات : بعد كل كويز يقول لنا الي عنده اسفسار عن الدرجة يجي لي الاوفيس ودائما الي يجونه يعطيهم بونص\nلكن قليل الي يجونه بحكم تعارض اوقات الاوفيس مع الكلاسات.\nنصيحة اخيرة :اذا مستواك متوسط او اقل في الفيزكس لاتنزل عنده لان شرحه جدا معقد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1465828-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/zain-yamany/68382/15", "user": "user10330", "ts": 1483602306000, "tid": 68382, "pn": 15}}]}', 1483602306000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10924-phys102', 'stk-user10924', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68382", "n": "Dr. Zain Yamany", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102 Term161\n\nحقيقة الدكتور من القلة المبدعة في كثير مما يتعلق بالحصة، وكذلك من المتفنين في الفيزياء ومن له اطلاع في الفيزياء قبل المادة سيجد هذا جليًا.\n\nالتحضير : يهتم بالتحضير جدًا، ومن إبداعاته لما كنا في 63 كان موزعنا بأرقامنا على الكراسي فكان يصور القاعة أول الحصة وبالصورة يحضر. ومما يلحق بالتحضير وأراه من محاسن الدكتور أنه لا يسمح باللباس غير اللائق في الحصة فقد أخرج أحد الطلاب من الحصة يومًا لأنه رأى فخذه.\n\nطريقة الشرح : أما الشرح فحدث ولا حرج الدكتور ينتقي ألفاظه العلمية كثيرًا من الأحيان -لا أعرف هي سليقة أم يتعناها- بحيث لا يمكن تجد لها منزع خطأ وهذا من أكبر الأدلة على حسن فهمه. أكثر شرحه ارتجالي على السبورة ويستعين غالبًا بعروض للتوضيح. ومن إبداعاته أنه كان يستعمل Mathematica ليحاكي بعض الظواهر الفيزيائية مثل الموجات ويعرضها علينا. كان الدكتور بداية الفصل يخص Recitation بحل المسائل لكن آخر الفصل بدأ يحل في المحاضرة بعد.\n\nالكويزات : كانت منوعة مرة تجي أسئلة مباشرة ومرة يكون فيها فكرة ذكية ومره تكون أسئلة غير معهوده مثال على الأخيرة مرة جاب اختبار كان في سؤال واحد وهو “اذكر خمسة أشياء تعلمتها من الحصة الماضية”\n\nالمياجر: Common\n\nالفاينلات : Common\n\nالقريد النهائي: A+\n\nالصوت: واضح، ولغته متقنه (Native speaker).\n\nإضافة :\nمع أن الدكتور من المبرزين في هذا العلم إلا إني أجد في التعليقات من يسيء إليه، وأنا أرجع هذا لأمرين:\nأحدهما) أن الدكتور يهمه فهم الطالب أكثر من غيره فالطلاب اللي بس يبون يعدون المادة ولا همهم إلا كيف يختبرون يتورطون معه فينتقدونه.\nالآخر) مواقف شخصية صارت لهم مع الدكتور لذلك ينفعلون عاطفيًا ويذكرونه بسوء.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1472126-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/zain-yamany/68382/21", "user": "user10924", "ts": 1493305600000, "tid": 68382, "pn": 21}}]}', 1493305600000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_student1-phys102', 'stk-_student1', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68382", "n": "Dr. Zain Yamany", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الصراحة إني ما نزلت المادة (phys 102) عند الدكتور ، و لكني كنت أحضر محاضراته و ال recitation في 161.\n\nمن أكثر ما كان يعجبني في الحصة تركيز الدكتور على ال concept ، و هذا يدل على:\n\n1- حب الدكتور للفيزياء ، و رغبته في تحبيب الطلاب اليها. فالفيزياء ليست مجرد قوانين تستخدم في إيجاد بعض الكميات ، بل هي أعمق من ذلك.\n2- اهتمام الدكتور بفهم الطلاب ، و التزامه بأداءه أمانته. فمن السهل على الدكتور أن يحل الكثير من المسائل و يعلم الطلاب الـ(tricks) اللي ممكن تجي في الاختبارات ، ولكن فقط من يهتم فعلا بطلابه يبذل مثل هذا المجهود. حتى لمن مرض الدكتور و تعب حلقه ما قلل من المجهود اللي يبذله في الشرح.\n\nصحيح أن الدكتور قد يكون أشد من غيره في بعض الأحيان ، و لكن كثير من الطلاب ينسون أن عليهم حقوقا مثل ما أن لهم حقوق.\nو من حقوق الدكتور تركيز الطلاب معه . و لما يسأل الدكتور أحد الطلاب ، فهو لا يسأله لاحراجه ، و إنما لاستعادة تركيز الطالب و التاكد من فهمه.\n\nالكورس مو موجود عشان يعديه الطالب بدون فائدة او عشان يخسف المعدل ، و يجب على جميع الطلاب ان يفهمو ذلك. و لا يجدر بالطلاب اللي ما يبون يدرسون و اللي يتوقعون ان الدكتور بيمضي الحصة حل مسائل عشان ما يتعبون اذا رجعو غرفهم أن يلقو باللوم على الدكتور.\n\nالحصص اللي حضرتها مع الدكتور كانت من أجمل الحصص التي حضرتها في الجامعة . ما كنت اتوقع اني ممكن استفيد من المحاضرة مثل الكتاب - أو حتى أكثر! (بالنسبة لطالب يعتمد على ال self study).\n\n#أعتذر على عدم تناسق الكتابة ، مرة بالفصحى و مرة بالعامية 😆", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1472571-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/zain-yamany/68382/22", "user": "_Student1", "ts": 1494008842000, "tid": 68382, "pn": 22}}]}', 1494008842000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8587-phys102', 'stk-user8587', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68478", "n": "Dr. Thamer Al-Aithan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا اخذت معه الفيزكس 102 … أجمل مافي الدكتور انه فاهم الطلاب …\nولو شاف الكلاس نام شوي … وقف الشرح لمدة دقيقه او دقيقتين يقول نكته\nاو قصه قصيره يغير فيها الجو بعدين يكمل … من ناحية الشرح انا مابي ابالغ واقول\nانه خرافي و مدري ايش … تقريبا مثله مثل باقي المدرسين . بس اهم شي انه يوصل\nالفكره لك و تستوعبها و هذا المهم …\n\nطبعا انسى تطلع قبل الوقت المحدد او مثلا يعطيك يوم اوف او يسامحك على التأخير\nاو الغياب … انسان جدي جدا في هالنواحي …\n\nلو انت انسان ماتغيب و حريص على الحضور … ماراح تتعب معه\n\nبالنسبه للكويزات … اغلبها تجي من الاولد اقزام … لكنها موب صعبه\nيعني معقوله ومافيها تريكات واجد …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1144385-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/thamer-al-aithan/68478/51", "user": "user8587", "ts": 1355843549000, "tid": 68478, "pn": 51}}]}', 1355843549000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-black_cave-phys102', 'stk-black_cave', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68480", "n": "Dr. Abdulaziz Al-Jalal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ريسيتيشن فيزيكس 102 __ ترم 111\n\nيبدأ يحل مسائل من الاولد اكزامز مرتبها عنده بسلايدات و موجودة عنده بالموقع\nالكويزات كل اسبوع فيه كويز عليه خمس درجات و عادة ما تكون من نفس المسائل الموجودة في السلايد الخاص بالشابتر\nبامكانك فنح الكتاب فقط اثناء الكويز\nيشرح بعض المفاهيم و المبادئ قبل الحل كمراجعة سريعة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p973167-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulaziz-al-jalal/68480/24", "user": "BlAcK_CAVE", "ts": 1327416145000, "tid": 68480, "pn": 24}}]}', 1327416145000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cs_scientist-phys102', 'stk-cs_scientist', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68480", "n": "Dr. Abdulaziz Al-Jalal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102-142\n\nالتحضير : بالبداية كان متساهل و يسلك بالتحضير، بس يوم شاف الطلاب فلوها الله يهديهم صار يحضر بالبداية و اللي يجي بعدها ليت\nطريقة الشرح : يشرح من سلايداته، شرحه حلو للكونسبت، نظامه كان أول 15 دقيقة تقريبًا يراجع الدرس القديم، و بعدها يشرح الدرس الجديد\nالكويزات : سهلة، كان يجيب من أسئلة الريسيتيشن اللي موجودة في موقع الفيزيكس بس يغير فيها شوي، غالبا بس يغير الأرقام\nالمياجر: كومون\nالفاينلات :كومون\nالقريد النهائي: A\nالصوت: واضح و يشرح بالإنقليزي و العربي، ممتاز في ايصال المعلومة\nإضافات :\nالدكتور أخلاقه حلوة و حبيب و يتساعد معنا قد ما يقدر، و عادة يلقط اللي مسرحين بالكلاس و يسألهم و يخليهم يجاوبون\nبس ما بيحرجهم طبعًا، غالبا بيساعدك تجاوب، يرجع تركيزك و يعلمك شيء جديد\nبالنسبة لي عيبه الوحيد إنه ما كان يحل أسئلة بالكلاس، كان بس يشرح\nكنت قبل المياجر أحضر كلاسات الدكتور عبدالكريم مكّي لأنه يحل أسئلة قديمة بالهبل\n\nأنصحكم بالدكتور عبدالعزيز (هذا إذا لحقتم سكاشنه 😆)، شرحه حلو بس يبيلك تعتمد على نفسك بحل الأسئلة، و تعال له بساعات المكتب، ما بيقصر\nو الكويزات على إنه يجيب أسئلة تشبه أسئلة الريسيتيشن إلا إنه الآفرج ما كان مرة عالي، أذكر بالنورمالايزيشن نقصنا 0.4 بس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438551-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulaziz-al-jalal/68480/31", "user": "CS_Scientist", "ts": 1452476945000, "tid": 68480, "pn": 31}}]}', 1452476945000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-walo0od-phys102', 'stk-walo0od', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68480", "n": "Dr. Abdulaziz Al-Jalal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 - T171\n\nالتحضير:\nيحضرك بالكرسي اللي حدده لك بداية الترم (يتغير مع كل ميجر) على ملف باوربوينت.\nيعطي late كثير، إذا بدأ يحضر ومر على كرسيك ومنت موجود فتاخذ late على طول.\nيُفترض أنه يحسب كل 2 lates بغياب لكن الظاهر أنه يحذفها عنك في نهاية الترم.\nطريقة الشرح:\nيحب يكون الكل مركز معاه وما يتركك لا تستخدم الجوال ولا تنام ولا تذاكر لمادة ثانية ولا تسوي أي شيء وطريقته إذا شافك مو مركز يقوم يسألك سؤال بس يساعدك.\nأسلوبه محترم جداً ويقولك ركز معي عشان تستفيد أنت. وللأمانة استفدت من تركيزي معاه كثير.\nالكويزات:\n4 كويزات فقط. 2 قبل الميجر الأول وواحد قبل الميجر الثاني وواحد قبل الفاينل.\nأسئلته اختيارات ويجيب أسئلة زي الأولد اقزام تماماً.\nفي كل كويز يعطيك أربع أوراق: ورقة الأسئلة، ورقة التظليل، ورقة تحل عليها، والفورملا شييت.\nأفرج شعبتنا في كل الكويزات كان تقريباً 3.7 من 10 وأترك لك حرية الحُكم 😆. بس طبعاً هذا يفيدك في الـnormalization.\nالمياجر:\nمشتركة\nالفاينلات :\nمشتركة\nالقريد النهائي:\nA+\nالصوت:\nواضح جداً.\nإضافات :\n- تعامل الدكتور جبّار، ولأنه من القديمين فهو يعامل الطلاب زي أولاده تماماً.\n- يسمح لك بالميك اب في الريسيتيشن بس يعطيك late.\n\nطبعاً أنصح فيه وبقوة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485964-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulaziz-al-jalal/68480/34", "user": "Walo0od", "ts": 1515685693000, "tid": 68480, "pn": 34}}]}', 1515685693000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sake-phys102', 'stk-sake', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68480", "n": "Dr. Abdulaziz Al-Jalal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS 102 - 192\n\nالتحضير : يخصص لكل طالب مقعد خاص فيه ، باخر المحاضرة يحضر بناء عليها فاذا شاف مقعدك فاضي ف انت غايب ، يغير مقاعد الطلاب بعد كل ميجر ، عنده ميكب وهو انك تحضر عند دكتور ثاني لكن لازم تكلمه اول شي ثم تروح تحضر وتجيب ورقة رسمية من الدكتور الثاني وتوديها له ، اذا شافك تستخدم جوالك يطردك من القاعة وعلى طول غايب\n\nطريقة الشرح : عن طريق سلايداته الممتازة ، يشرح من سلايدات جديدة مكتوبة بخط يده ، ولكنها مشابهة للقديمة ، شرحه ككونسيبت جدا اسطوري يوصل لك المعلومة صح! ولكن من ناحية حل الامثلة شوي تعبان لانه يقراها ومايستخدم السبورة الا نادرا بالحل ، يستخدم السبورة عشان يكتب قوانين بس. اذا شافك سرحان يسألك عن نقطة واذا ماجاوبت يعيد شرحها لك ، يهمه فهم الطلاب للدرس.\n\nالكويزات : تبدأ من الاسبوع الثالث ، عبارة عن سؤالين اختيارات ، لكل طالب كويز خاص فيه مختلف عن كل الطلاب الاخرين < اللي لاحظته ، صعوبتها مقاربة لصعوبة الاسئلة اللي يحلها بالريسايتيشن وافكارها مقاربة جدا بعد لذلك حلك لاسئلة الريسايتيشن بيخليك تضمن تجيب كامل ،، نظامه بتصحيح الكويز كالاتي : سؤالين كل واحد عليه 10 ، اذا جاوبت صح وظللت صح بتاخذ 10 بالسؤال ، اذا لا بتاخذ 3 حتى لو ماحليت شي ، تصحيحه فقط يعتمد عالاجابة النهائية.\n\nالصوت : واضح جدا لانه يستخدم مايكروفون\n\nاضافات : الدكتور له سياسة غريبة وعجيبة قد تكون مزعجة وقد تكون عادية ، نظامه بالريسايتيشن هو مع كل اسبوع يخصص 6 طلاب لحل 6 اسئلة مختلفة ، كل طالب يقوم عالسبورة يحل سؤاله مع الشرح ، الدكتور بيكون جالس ورا وكل شوي يعلق على طريقة كتابتك بالسبورة او تعويضك واستخدامك للقوانين ، او احيانا يعلق عن ذا لما تخلص حل ، كان شي مزعج لانه يضيع 10-15 دقيقة على سؤال واحد\n\nفي حال لا سمح الله صار سمستر 201 اونلاين:\nطريقة التحضير هو تكتب الاي دي حقك بالشات بداية المحاضرة ، ضروري تكون مستمع له طول الوقت لانه مع كل كونسبت جديد بيسأل طالب وبيقعد يشرح معاه ، لانه مايحب يشرح لحاله يحس انه يتكلم مع جدران ، اذا مارديت غالبا على طول غايب او احيانا يعطيك فرصة ثانية بحيث يسألك بعدين\nالريسايتيشن صار هو يشرحها ومع كل سؤال ينادي طالب يساعده بحل المسألة ، حتى لو مافاهم شي بتمشي امورك ومابيسوي لك شي ، اللهم بس يبي احد يتفاعل وياه بالحل\nاما الشرح : تقريبا حبتين صار افضل من العادي ، لانه يستخدم القلم ويكتب قدامك ويرسم ويأشر مما يسهل عليك الفهم\n\nبالنهاية حبيت اذكر انه اخلاق الدكتور من اروع واجمل ما مر علي ، يحرجك باخلاقه جدا جدا جميلة وتعامله ولا اروع الله يوفقه دنيا واخره\nرغم كل شي ، ماندمت اني سجلت معه ، اذا انجبرت تسجل معه فلاتتردد ،،", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521846-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulaziz-al-jalal/68480/35", "user": "SAKE", "ts": 1588881436000, "tid": 68480, "pn": 35}}]}', 1588881436000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11896-phys102', 'stk-user11896', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68480", "n": "Dr. Abdulaziz Al-Jalal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys102-T202 (عن بعد)\nالتحضير : اللي يخش المحاضرة في الزووم في أول 5 دقائق يتحضر تلقائي واللي يخش بعدها ولكن في أول 20 دقيقة يصير متأخر (كل 3 تأخيرات بغياب) واللي يخش بعد 20 دقيقة يصير غايب\nطريقة الشرح : يشرح لنا من سلايدات خاصة فيه وشرحه يعني يحتاج أنك تكون محضر الدرس من قبل عشان تفهم كل شيء يقوله. والدكتور يتقبل الأسئلة ويجاوب عليها.\nالكويزات : 6 كويزات وحذف لنا أسوأ واحد وكل كويز يكون 3 أسئلة ومتوسط الدرجات كان نازل 9/20 فرفعنا النورملايزيشين (طبعا كانت الكويزات غريبة، كان الكويز عبارة عن ملف وورد يرسله لنا بالإيميل وهذا الملف في الأسئلة وفيه فراغ تحت كل سؤال عشان تكتب فيه الجواب وبعدها تحفظ الملف وترسله للدكتور بالإيميل)\nالمياجر: موحدة\nالفاينلات : موحدة\nالقريد النهائي: B\nالصوت: واضح\nإضافات : الدكتور من أجمل الدكاترة اللي مروا علي أخلاقا الله يحفظه ويوفقه. بس رغم ذلك أشوف أنه فيه دكاترة آخرين أفضل من ناحية الشرح. طريقة الدكتور في الشرح في الدراسة عن بعد هي أنه يختار واحد من الطلاب لكل جزئية من الدرس عشان يصير شرحه كأنه مناقشة بينه وبين الطالب (ما يحتاج أنك تكون مرة فاهم الجزئية لو اختارك للمناقشة لأن لو ما تعرف بيساعدك)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529855-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulaziz-al-jalal/68480/36", "user": "user11896", "ts": 1620257551000, "tid": 68480, "pn": 36}}]}', 1620257551000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-me_student91-phys102', 'stk-me_student91', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68480", "n": "Dr. Abdulaziz Al-Jalal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102-Term 241-Lec\nالتحضير : آخر الكلاس ياخذ صورة للحضور بمقاعد معينة يرسلها إيميل، إذا تأخرت عشر دقايق يحطك غايب\nطريقة الشرح : من سلايدات هو مسويها وهي الأفضل في الكورس هذا برأيي ويكتب على السبورة ويجاوب على أسئلة الطلاب.\nالكويزات : …\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: A+\nالصوت: واضح\nإضافات : الدكتور من أفضل وأنبل الدكاترة اللي درسوني، متعاون لأبعد درجة حتى في التحضير، وقت الميجرز كان يخلي الطلاب يجيبون أسئلة ويحلها.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1539428-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulaziz-al-jalal/68480/37", "user": "ME_STUDENT91", "ts": 1745058351892, "tid": 68480, "pn": 37}}]}', 1745058351892, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-da7mi91-phys102', 'stk-da7mi91', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68489", "n": "Dr. Mohammed Musazey", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "صيف 103 فيزيكس 102\n\nالتحضير :ورقه تعدي يمديك تحضر اخوياك بعض الاوقات ينادي بالاسماء ويسوي انا اللي اقفط\nطريقة الشرح : عادية ومملة وفي معلومة مههههمة … ثلاث ارباع الحصة تروح لاشتقاق يعني يشتق هذا القانون من ذاك وهكذا دواليك والحصة راحت ولا فهمنا شي\nالكويزات : بحسب الريسيتاشن\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: C نصيحتي لا تنزل عنده ولا بيكون كورس سيلف ستدي زي ما سويت\nالصوت: عالي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p889699-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-musazey/68489/37", "user": "da7mi91", "ts": 1313972929000, "tid": 68489, "pn": 37}}]}', 1313972929000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-maximus-phys102', 'stk-maximus', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68496", "n": "Dr. Ali Mohammad Al-Shukri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أقسم بالله العظيم أني سأقول الحق و لا شيء إلا الحق\n\nكانت الـ3 ساعات حقت لاب الفزكيس 102 واحده من اسوا اوقات عمري\n\nيا ناس يا عالم فيه شخص بالهدنيا يشرح 3 ساعات متواصله بدون توقف نهائيا في اول لاب اللي هو Data Analysis and Presentation\n\nانا جاي اول لاب ومتحمس اشوف هالشخص اللي كلن يتكلم عنه لكن انصدمت باللي شفته\nالطلاب كلهم طفشااااااااانين\n\nكل لاب يشرح تقريبا ساعة ونص الى ساعتين وخلال هاذي الوقت مستحيل تستفيد او تفهم التجربه لان ثلاث ارباع كلامه خاااااااارج الموضوع\n\nتقريبا ومن دون مبلاغه اكثر من ثلاث ارباع اللابات يخلص الوقت والقروب لسا ما خلص التجربه\n\nوفوق كل ذا الربورت اذا سلمته متاخر يصححه من نص الدرجة\n\nهذا غير ان التصحيح هو اغرب تصحيح شفته بحياتي\nيعني لازم عندك خطا\nيمين يسار فيه خطا يعني فيه\n\nاحد المرات اخذ ربورت خووي ونقلته وعدلت كل اخطاه\nوالله العضيم جتني درجة اقل من درجة خويي\nولما شفت الروبوت لقيت خاصم على اشياء ولا خصمها على خويي\nيعني لا تحاول تبدع بالربورت معه لان المصير محتوم\n\nطبعا يوم وصلن نصف السمستر انا شخصيا عجزت اصبر على الوضع هذا وكتبت ورقه وحطيتها تحت الباب وهذا هو مضمون الورقه :\n\nالسلام عليكم ورحمة الله وبركاته\n\nإلى الدكتور علي الشكري\n\nنحن طلاب لاب مادة فيزياء 102 مستاءين من ضياع وقت اللاب في أمور ليس لها علاقه في التجربه ومنها حل الكويز وايضا التطرق إلى أمور خارجة عن المنهج وتأجيل وقت بداية التجربة مما يؤدي إلى ضيق وقت تطبيق التجربه وكتابة التقرير\n\nنأمل من شخصكم الكريم مراعاة ذلك ووضعه في الحسبان واعطانا وقت لكتابة التقرير خلال وقت اللاب الرسمي\n\nشكرا لكم وأدامكم الله في خدمة العلم والطلاب\n\nأبنائك طلاب لاب الفيزياء\n\nجا في اللاب اللي بعده وقال بالحرف ما راح اتغير و و و ولا تغير فيه شي\n\nاليوم طلع افرج السكشن 11.5\nطبعا لازم يعدله ويصير 14\n\nلكن اللي رافع ضغطي ان اغلب مدرسين اللابات يكون افرجهم الاساسي قريب من 14\nمثلا نقفي افرجه 13\n\nوغيره كثيره\n\nنصيحة لكل الطلاب لا تتهور وتنزل معه لاب\n\nكل كلامي هذا عن اللاب اما اللتشر ما عندي اي فكرة وللمعلومية هو راح يدرس فيزكس101 بـ091", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p414518-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-mohammad-al-shukri/68496/8", "user": "Maximus", "ts": 1245078264000, "tid": 68496, "pn": 8}}]}', 1245078264000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-something-phys102', 'stk-something', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68496", "n": "Dr. Ali Mohammad Al-Shukri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "يا اخوان انا نزلتم معه لاب فيزكس 102 في السمستر 082 و كنت مع الاخ ماكسيمس\nلاااااااااااااااااااااااااااااااااااااااااااا تنزلو لاااااااااااااااااااااااااااااااااااااااااااااااااااااااااااااااااااااااااب معه\n\nأتوقع انو في اللكتشر جيد لأنه مليان معلومات مشالله عليه ، لكن اللاب ملل ملل ملللللللللل ملل ملل … الخ\n\nالدكتور طيب جدا ويخاف على مصحلة الطالب\n\nبالتوفيق 🌹\n\nملاحظة : ما اتوقع انه قد نزل لكتشر فيز 101 او 102 ، عشان كذا ما راح نقدر نفيدكم في النوت والشرح\n\nتحياتي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p458245-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-mohammad-al-shukri/68496/15", "user": "something", "ts": 1252674159000, "tid": 68496, "pn": 15}}]}', 1252674159000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4988-phys102', 'stk-user4988', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68496", "n": "Dr. Ali Mohammad Al-Shukri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "شباااب اللاب معاه يمشي الحاال ولا دماار شامل\n\nضروري ردوا\n\nإنذاااااااااااااااااااااااااااااااااااار *_*\nأنتبه لا تنزل عنده لاب لو أيش نصيحة لوجه الله تعالى !!!!!!!!!!!!!\nإن كنت تكره نفسك و تبغى تطفش و تتحطم نفسياً … نزل عنده !!!\nكلامه في وادي … و الدرس و الريبورت في وادي ثاني *_*\nأما ساعات اللاب اللي المفروض تكون 3 ساعات … بقدرة قادر صارت كأنها 5 ساعات !!!\n95% من وقت اللاب ما راح تستفيد منه شيء أبداً حتى لو كنت دافور !!\nيعني لو نمت أو أنتبهت معاه أو لعبت بالبلاك بيري حقك … راح تخرج بنفس المحصلة !!!\nالريبورت تسويها في الغرفة و تسلمها له في يوم محدد في مكتبه ، و إذا تأخرت راح يصحح لك من نص درجة !!\nتصحيحه دمااااااااااار نووي و شامل … و قد قالها لنا في بداية السميستر : I’ll be tough\n\nطبعاً الكلام هذا في سميستر 091 …و الكلام هذا عن شرحه في اللاب … أما في الأخلاق فهو طيب بس ما راح ينفعك أخلاقه لو أخذ قريد واطي !!!!\nو اعتقد إن كلام الأخ ماكسيمس كان كافي جداً لشرح المعاناة !!!!\nو الذي نصه كالتالي :\n\nأقسم بالله العظيم أني سأقول الحق و لا شيء إلا الحق\n\nكانت الـ3 ساعات حقت لاب الفزكيس 102 واحده من اسوا اوقات عمري\n\nيا ناس يا عالم فيه شخص بالهدنيا يشرح 3 ساعات متواصله بدون توقف نهائيا في اول لاب اللي هو Data Analysis and Presentation\n\nانا جاي اول لاب ومتحمس اشوف هالشخص اللي كلن يتكلم عنه لكن انصدمت باللي شفته\nالطلاب كلهم طفشااااااااانين\n\nكل لاب يشرح تقريبا ساعة ونص الى ساعتين وخلال هاذي الوقت مستحيل تستفيد او تفهم التجربه لان ثلاث ارباع كلامه خاااااااارج الموضوع\n\nتقريبا ومن دون مبلاغه اكثر من ثلاث ارباع اللابات يخلص الوقت والقروب لسا ما خلص التجربه\n\nوفوق كل ذا الربورت اذا سلمته متاخر يصححه من نص الدرجة\n\nهذا غير ان التصحيح هو اغرب تصحيح شفته بحياتي\nيعني لازم عندك خطا\nيمين يسار فيه خطا يعني فيه\n\nاحد المرات اخذ ربورت خووي ونقلته وعدلت كل اخطاه\nوالله العضيم جتني درجة اقل من درجة خويي\nولما شفت الروبوت لقيت خاصم على اشياء ولا خصمها على خويي\nيعني لا تحاول تبدع بالربورت معه لان المصير محتوم\n\nطبعا يوم وصلن نصف السمستر انا شخصيا عجزت اصبر على الوضع هذا وكتبت ورقه وحطيتها تحت الباب وهذا هو مضمون الورقه :\n\nالسلام عليكم ورحمة الله وبركاته\n\nإلى الدكتور علي الشكري\n\nنحن طلاب لاب مادة فيزياء 102 مستاءين من ضياع وقت اللاب في أمور ليس لها علاقه في التجربه ومنها حل الكويز وايضا التطرق إلى أمور خارجة عن المنهج وتأجيل وقت بداية التجربة مما يؤدي إلى ضيق وقت تطبيق التجربه وكتابة التقرير\n\nنأمل من شخصكم الكريم مراعاة ذلك ووضعه في الحسبان واعطانا وقت لكتابة التقرير خلال وقت اللاب الرسمي\n\nشكرا لكم وأدامكم الله في خدمة العلم والطلاب\n\nأبنائك طلاب لاب الفيزياء\n\nجا في اللاب اللي بعده وقال بالحرف ما راح اتغير و و و ولا تغير فيه شي\n\nاليوم طلع افرج السكشن 11.5\nطبعا لازم يعدله ويصير 14\n\nلكن اللي رافع ضغطي ان اغلب مدرسين اللابات يكون افرجهم الاساسي قريب من 14\nمثلا نقفي افرجه 13\n\nوغيره كثيره\n\nنصيحة لكل الطلاب لا تتهور وتنزل معه لاب\n\nكل كلامي هذا عن اللاب اما اللتشر ما عندي اي فكرة وللمعلومية هو راح يدرس فيزكس101 بـ091\n\nضدق في كل كلمة قالها ، و بالمناسبة الوضع كما هو في 101 ، يعني ما فيه فرق بين 101 و 102 !!!!!\n\nلي رجعة إن شاء الله عشان أشرح وضعه في الليكتشر و اللاب !!!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p514124-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-mohammad-al-shukri/68496/22", "user": "user4988", "ts": 1262431180000, "tid": 68496, "pn": 22}}, {"id": "stk-dr-f68504", "n": "Dr. Mohamed S Kariapper", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فيزكس 102\n093\nريستيشن فقط\n\nذلحين اللي يقولون عنه طيب و كويس , من أي ناحية قيموه ؟؟؟؟\n\nفي الريستيشن … يمين الله تحسه داااااااااااايخ … أحياناً أحسه شوي و بيبكي 😐\nمو عن مرض … إلا أحس كأنه جابوه غصب عشان يَدَرِس في هذا السمستر\n\nيقرقر من هنا و يقرقر هناك … و مرة يجيب الجواب ثم يمسحه و يجيب لك جواب ثاني ثم ثالث ثم رابع , يعني بتدوخ حتماً معاه …\nأنسى إنك بتستفيد منه في الريستيشن … أعتمد على الله ثم على نفسك في حفظ القوانين و فهم المسائل …\n\nأما عن الكويزات … فهذا كوم ثاني …\nصحيح إنه أول 4 كويزات كانت سهلة و بعد كذا صعبها عشان الأفريج … بس المشكلة مو هنا …\nعنده حركة خايسة بالحيل … يقول لك : يو هاف تن مينتز تو فينيش ذا كويز !!\nتبدأ بسم الله في الحل … إلا و بعد دقيقتين بس …\nتلقاه يسحب في الأوراق و يضحك لنا بضحكة غبية ما أدري وش تبي …\nأظن الحبيب ما يفرق بين two و ten … و أخرتها أصفار كثر التراب في الكويزات …\nسوى معانا ذي الحركة الوسخة مرتين أو ثلاث … قلة أدب صحيح\n\nماأنصحكم تنزلوا معاه … لا في لكتشر و لا في لاب و لا في ريستيشن حفاظاً على ما تبقى من درجاتكم …\n\nو الله الهادي إلى سواء السبيل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p685166-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-s-kariapper/68504/18", "user": "user4988", "ts": 1282071537000, "tid": 68504, "pn": 18}}, {"id": "stk-dr-f73560", "n": "Dr. J Al-Sadah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فيزكس 102 لاب\n093\n\nشكل المدرس هذا ما يدرس طلاب الجبل إلا في الصيفي … بدليل إن نتائج اللاب حقنا معلقة في باب مكتبته من الصيفية إلى الآن 😆 ، لأنه يدرس كورس الفيزكس حق الأوريا و هي لحالها شغلة !!\n\nالمهم …\n\nالتحضير :ينادي بالأسماء\nطريقة الشرح : لك عليه صراحة ً … اللي قهرني فيه إنه أحياناً بعدما يشرح اللاب … يقول أي سؤال حنا حاضرين … و لما نبدأ التجربة و نعلق في جزء من التجربة … نحصله قد اختفى من المعمل و ما يرجع إلا في آخر نص ساعة !!\nالكويزات : ما أعطانا كويز في اللاب\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: أنا أعطيه C\nالصوت:واضح\nإضافات :\nالله لا يوريكم … الفاينال لاب حقه غريب … ريتين و عملي … الريتين فيه أسئلة مو واضحة و السبب هو لغة المدرس الغريبة … تحتاج تقرأ السؤال مرات عشان تقهم إيش المطلوب … أما في العملي … فلما تمسك الورقة ما تعرف إيش هي الخانات اللي أحلها أنا كطالب و إيش هي خانات حق المدرس … بإختصار الفاينل لاب حقه حوسة !!!\nأتذكر إنه أحسن واحد في سكشني جاب في الريتين 25 من 30 …\n\nختاماً ما عندي التعليق المناسب عنه … صحيح إنه أخلاق لكن في الدرجات راح تحقد عليه !!!!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p806577-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-sadah/73560/14", "user": "user4988", "ts": 1299345170000, "tid": 73560, "pn": 14}}]}', 1262431180000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chemist-phys102', 'stk-chemist', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68506", "n": "Dr. R Khateeb", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 Lab Term 093\n\nالتحضير:\nكل يوم ولا يدقق على التأخير\n\nالشرح:\nكان يشرح بطريقة جميلة ويبسط لك التجربه ويسهلها عليك وكان يتجنب بعض الفلسفة الموجودة في المانيوال بختصار شرحه روعه ومرتب بس في تجربة الكهرب ما الكهرب كانت التجربة صعبة ولا فهمنا عليه\n\nالكويزات:\nعلى حسب ما أذكر انها كانت في كل لاب وكانت سهله جدا\n\nالفاينال:\nكان ريتن ومتوسط وماقصر جزاه الله خير علمنا بطريقة الأسئلة\n\nاضافات:\n1) خلوق ومتعاون ولا عنده مشكلة تساله اي سؤال\n2) لابه خفيف وفله مااذكر كنا نطول فيه\n3) بطل في التصحيح اغلب التجارب 9 او 8 من 10 وذا انت مره داج 6 من 10\n\nالقريد النهائي:\nA", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1098035-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-khateeb/68506/18", "user": "Chemist", "ts": 1348506290000, "tid": 68506, "pn": 18}}, {"id": "stk-dr-f68496", "n": "Dr. Ali Mohammad Al-Shukri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 REC Term 093\n\nالتحضير:\nكل يوم\n\nالشرح:\nصراحة مافهمت شئ من المسائل اللي يحلها والمسائله اللي تأخذ 3 دقايق يحلها في 10 دقايق\nوبعض مرات يقلب حصة الريسايتيشن الى لكتشر يعني الزبدة عدا الفصل كله مافهنا الا عدة مسائل فقط وكانت بسيطة\n\nالكويزات:\nكانت متوسطة وغير معقدة\n\nاضافات:\nالدكتور حبيب مرة ومتعاون يعاملك كانك ولده ووده يفهمك بأي طريقة بس كان يفتقد لتوصيل المعلومه\n\nالقريد النهائي:\nC", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1098042-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-mohammad-al-shukri/68496/41", "user": "Chemist", "ts": 1348507023000, "tid": 68496, "pn": 41}}]}', 1348506290000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-eng.3booodii-phys102', 'stk-eng.3booodii', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68502", "n": "Dr. A Ghannam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "لاب فيزكس 101\n\nالتحضير : التحضير يتم عن طريق استلام الريبورت وينادي بالأسماء بعض الأحيان …\nطريقة الشرح : بداية اللاب ناخذ كويز عن اللاب إلي قبله وبعدها يبدأ يشرح كل شي عن اللاب وبكل بساطة\nالكويزات : ممم متوسطة إلى صعبة\nالمياجر: مافيش\nالفاينلات : بالنسبة للفاينال … هو خيرنا بين عدة خطط … نحنا أخترنا الخطة إلي اللريبورتات عليها 10 و الكويزات عليها 7 والفاينال عليه 3 درجات … الفاينال كان سؤال واحد فقط وشفهي وما ياخذ معاك نص دقيقة\nالقريد النهائي: إبداع a+\nالصوت: واضح\nإضافات : أنا أستغرب من الشباب إلي تتكلم عن الدكتور بطريقة سيئة … والله الأساذ أيمن محترم وأخلاقه عالية وما ينقصه شي بالشرح …\nغير كذا هو إنسان أمين ويحب يفيد الطلاب بأي طريقة ودايما بعد كل لاب أجلس أنا وبعض الشباب معه\nوبالنسبة للتشديد فـ تصحيح الريبورت والله ما ينقصك على شي إلا لو كان خطأ وما ينقص إلا لجل تتعلم وبالفعل أستفدنا كثير من هذي النقطة\n\nنسيت ما أذكر إن الكويزات تكون أوبن ريبورت :d\n\nهذا ما لدي وإن شالله لاب فيزكس 102 عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p526274-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-ghannam/68502/17", "user": "eng.3boOodii", "ts": 1263977394000, "tid": 68502, "pn": 17}}]}', 1263977394000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-en.maistr000-phys102', 'stk-en.maistr000', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68502", "n": "Dr. A Ghannam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "[quote=“eng.3booodii”]\n\nلاب فيزكس 101\n\nالتحضير : التحضير يتم عن طريق استلام الريبورت وينادي بالأسماء بعض الأحيان …\nطريقة الشرح : بداية اللاب ناخذ كويز عن اللاب إلي قبله وبعدها يبدأ يشرح كل شي عن اللاب وبكل بساطة\nالكويزات : ممم متوسطة إلى صعبة\nالمياجر: مافيش\nالفاينلات : بالنسبة للفاينال … هو خيرنا بين عدة خطط … نحنا أخترنا الخطة إلي اللريبورتات عليها 10 و الكويزات عليها 7 والفاينال عليه 3 درجات … الفاينال كان سؤال واحد فقط وشفهي وما ياخذ معاك نص دقيقة\nالقريد النهائي: إبداع a+\nالصوت: واضح\nإضافات : أنا أستغرب من الشباب إلي تتكلم عن الدكتور بطريقة سيئة … والله الأساذ أيمن محترم وأخلاقه عالية وما ينقصه شي بالشرح …\nغير كذا هو إنسان أمين ويحب يفيد الطلاب بأي طريقة ودايما بعد كل لاب أجلس أنا وبعض الشباب معه\nوبالنسبة للتشديد فـ تصحيح الريبورت والله ما ينقصك على شي إلا لو كان خطأ وما ينقص إلا لجل تتعلم وبالفعل أستفدنا كثير من هذي النقطة\n\nهذا ما لدي وإن شالله لاب فيزكس 102 عنده/QUO\n\nنفس الرأي تماما", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p527199-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-ghannam/68502/19", "user": "en.maistr000", "ts": 1264164355000, "tid": 68502, "pn": 19}}]}', 1264164355000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_as1-phys102', 'stk-_as1', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68506", "n": "Dr. R Khateeb", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "خطيب الرحمن / R KHATEEB\n\nالمادة ورقم الترم: PHYS102 (Lab) & T202 (In-person)\n\nبنود التقييم /\n\nالتحضير : بعد ما تاخذ الـ \" Pre-quiz \" يبدأ يحضر بالأسماء واحد واحد لو جيت بعد التحضير راح يجيك أتوقع بجيك منه \" absent \" لأن غالبا مشت فوق 10+ دقايق بالنسبة للـ \" Make-up \" يقبل فيه بس بيسألك عن السبب\n\nطريقة الشرح : والله يا خويي الشرح كان جمييل وبسيط وماشي معك تكـه تكـه ومعطيك كل شي تحتاج بالترتيب مع اهم القوانين للتجربة ومختصر عليك الكلام الكثير اللي في الـ \" Writer \" والصراحة ياخذ وقت كثير لأن يمشي بالبطيء وبالتفصيل الممل فـ غالبا مراح تطلع بدري ولكن التجارب ما كانت سهلة بالذات الأخيره فـ التطبيق العملي اللي يسويه قدامك عالسريع ويكون مرة وحدة بس و GG … لا أمزح يقول : اي شي توقف عنده نادني وارجع اشرح لك + في أول يوم بيذكر لك وش الأشياء اللي لازم تضمنها فالريبورت حقك صدقني لو تمشي على كلامه راح تكون بين \" 9-9.5+ / 10 \" ومن الأمثلة ( لازم تذكر اسم التجربة اول شيء ) + ( بعدها تحط الـ \" Objective \" المتطلبات ) + ( وتحتهم تكتب القوانين الأساسية الـ \" Theory \" ) … وتكمل بالترتيب والتسينق اللي بيعطيك أياه ولاتنسى الـ \" Unit \" … وطلب منا نشتغل على مجموعات كل أثنين مع بعض\n\nالكويزات : سهلة بس تحتاج تستعد لها صح … كانت أغلبها من الـ \" Writer \" اللي بالموقع لديبارتمنت وجزء بسيط مره معلومات عامة عن الموضوع تحصله بالـ \" Lecture \" … طبيعتها كانت 8-10 أسئلة ويعطيك حدود 4-5 دقايق وأغلبها خيار متعدد ويمكن 2-3 أسئلة كانت كتابة وتكون بداية اللاب عن الموضوع اللي بتاخذه اليوم ، لكن لاتشيل هم حاول تركز على 90% أفكار دايم يكررها بكوزاته واللي هي :\n* الـ Objective احفظها مافيها كلام دايم تجي + شكل القوانين وتكملتها + دايما كان بعد يجيب الـ \" Slop \" وش يعبر عنه + وكان دايم يسأل بعد ماعرفنا هالمعلومات وش نقدر نطلع + العلاقات بين الأشياء ( شيء vs شيء ) + … والنصيحة الأعظم في أول كوز حاول تستكشف طريقة كتابته للأسئلة لأن مايغيرها … ليش أول كوز لأنه راح يحذف لك أسوء كوز من أصل 6\n\nالمياجر : None\nالفاينلات : None\n\nالقريد النهائي : A+\n\nالصوت : مراح تواجهه أي مشاكل أشوفه متزن وواضح والأكسنت هندي وتقريبا بعض الكلمات راح يسوي لها دليت لكن كلامه بطيء ومفصّل فـ معليك\n\nإضافات : أشوفه طيّب وحبيب ونظام شرحه ممتاز يخليه خيار أول + فالأخير حذف لنا أسوء ريبورتين … وكان دايم يورينا أخطاءنا فالكوزات بين كل لابين مع الريبورت … كان تجربة جميلة للأمانة اللاب الحضوري الأختياري مع د. خطيب ❤️ …\nكـ تجربتي قدرت أطلع بـ 18/20 مع الـ \" Normalization \" وأستفدت من التطبيق العملي للتجارب وبالذات طريقة عمل وتحليل الـ \" Circuit \"", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530357-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-khateeb/68506/20", "user": "_As1", "ts": 1622838251000, "tid": 68506, "pn": 20}}]}', 1622838251000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman513-phys102', 'stk-abdulrahman513', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68507", "n": "Dr. M Mekki", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا نزلت عنده لاب phys 102 ترم 123\n\nالمدرس يخلي اللاب جدا مريح يكتب كل شيء على السبورة و انت اللي عليك بس التعويض في المسائل , وتخيلو يا شباب في التجربة هو اللي يوصل الأسلاك و كل شيء و في النهاية يعطيك الأرقام و عليك بالتعويض … اذا نزلت عنده أضمن لك الراحة في اللاب\n\nو التحضير لو تجي متأخر نص ساعة يحضرك بس لا يفوتك الكويز اللي دائما يكون اول 5 دقايق من اللاب\n\nاللي ما أعجبني فيه صعوبة نسبيا في الكويزات ما يجيب لك مسألة و بالقانون تعوض , يجيب اسئلة شرح او يقولك ارسم\n\nبالنسبة للفاينال فأنا اعتبر هالدكوتور “غادر” يجيب أسئلة ما أدري من وين و صعبة صعبة صعبة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1250070-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-mekki/68507/32", "user": "abdulrahman513", "ts": 1375121407000, "tid": 68507, "pn": 32}}]}', 1375121407000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-krooom-phys102', 'stk-krooom', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f81756", "n": "Dr. Saleem Rao", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "phys 102 term 153 lec\n\nلتحضير : ما يهتم مرة بالتحضير ما عطى احد حرمان DN ويمكن 6 من اصل 50 (سكشنين) انحرموا من الابقريد\nطريقة الشرح : يشرح لك من السلايدات شرحه عادي جدا، مع انه يسوي كل اللي عليه وزياده.\nالكويزات :\nعطانا 9 كوزات كل كويز سؤالين تقريبا وصعوبتهم صعوبة المياجر (وهذا شي كويس)\nودقيق جدا في التصحيح ولو تروح له الاوفيس اور عشان تراجع الكويز يقولك وين اخطات بس ابدا ما يزودك.\nوطبعا الافرج النهائي كان 4.7\nالمياجر:\nكومون (الاول الافرج 13 الثاني 10 (كان فعلا دمار) )\nالفاينلات : كومون الفاينل اتوقع 14 واقل الافرج\nالقريد النهائي: A\nالصوت: واضح ومقبول طبعا آكسنت باكستاني، ولكني معجبني الآكسنت حقه مرة\nإضافات :\nالدكتور مررررررة طيب وشريح ويحب اللي يسأل ويشرح لك ويقبل النقاش في الدرجات ولا يعابط أبد، أخلاق 10\\10 ولو تروح له الاوفس اور ما يقصر معك عشان يشرح لك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1453482-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saleem-rao/81756/54", "user": "Krooom", "ts": 1468202559000, "tid": 81756, "pn": 54}}, {"id": "stk-dr-f68507", "n": "Dr. M Mekki", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Lab - 153 - phys 102\nالتحضير :بعد ساعه من اللاب وما يشدد مرة\n\nطريقة الشرح : يشرح ع السبورة ويفصل لك كل شيء بالتجربة واهدافها ويعطيك معلومات جدا مفيده عشان تفهم الفيزياء وتطبيقات في الحياة\nمتقبل للأسئلة بشكل جميل جداً ويمكن يقعد ساعه يشرح لك\n\nالكويزات : هو في اللابات الكل فوق ال8 وعشان كذا في الكوزات يصعبها (صعوبتها في انه السؤال غير متوقع مثلا ما الادوات التي سنستخدمها وزي كذا)\n\nالمياجر: لا يوجد\n\nالفاينلات : كان صعب جداا وطويل شويتين\n\nالقريد النهائي: A\n\nالصوت: ممتاز وواضح\n\nإضافات : الدكتور خلوق وشرح ممتاز ومن الاساتذة اللي شرحهم ممتع ويمكن احيانا تضحك وهو يشرح كأنه يشرح لاطفال يحاول يبسط الشي بزياده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1457138-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-mekki/68507/36", "user": "Krooom", "ts": 1473247878000, "tid": 68507, "pn": 36}}]}', 1468202559000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmed1-phys102', 'stk-ahmed1', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68507", "n": "Dr. M Mekki", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102- Term 203 (Online)\n\nالتحضير : ينادي بالاسماء في نهاية اللاب و اذا انك ما سمعته يحضرك ما عنده مشكلة\n\nطريقة الشرح :\nيبدا في الثيوري اول شي ويشرح من اللكشر وبعدين يربطه في اللاب ويشرح اغلب الاشياء في اللاب بس عيبه انه يطول في الشرح يعني عادي ياخذ ساعتين بس شرح ! وهالشي الصراحة جدا كريه\n\nالكويزات :\nالكويزات كانت في البداية فاينل انسر بس تصميمه لها كان جدا سيئ ودرجات الطلاب كذلك ): وبعدها حولها الى اختيارات وكانت وسط الى سهلة بس تحتاج احيانا تكون محضر للشباتر\n\nالقريد النهائي: B\n\nالصوت: واضح\n\nالتصحيح : ما تدري على اي اساس يصحح احيانا تحسه يعطيك درجة وخلاص مادري اذا عشانه صيف كذا او لا، عموما تصحيحه جيد يعتبر يعطي 9 و 10 من 10\n\nالتعامل: جدا محترم واخلاق ويحاول يجاوب على اسئلة الطلاب بقد ما يقدر\n\nإضافات: ما أنصح تنزل عنده اذا كان فيه واحد افضل خصوصا انه يطول اللاب حتى لو انه سهل 👎", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531208-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-mekki/68507/38", "user": "Ahmed1", "ts": 1628787330000, "tid": 68507, "pn": 38}}]}', 1628787330000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6323-phys102', 'stk-user6323', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68511", "n": "Dr. A Salem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "مدرّس روعه بصراحه\nيوصل المعلومه بسهوله ومتمكن صراحه\nكوزات:متوسّطه وتركز على الكونسبت\nالتحضير :كل كلاس\n\nوانا كان يدرّسني ريسيتيشن في ترم 72 فزكس 102 واليكتشر كانت مع نقفي\nوكنت اروح عند نقفي واسحبها نوووووووووم بس عشان التحضير\nواحضر مع الاستاذ فتحي ويلخّص الشابتر وافهم معاه الشابتر كلّه في نص ساعه\nويعطي عليه كوز الاسبوع الي بعده\n\nوفي النهايه طلعت من الكورس بـ +Bولله الحمد\n\nانصح بالتنزيل عنده 👍\nوان شاء الله ينزّل سكاشن لكتشر وتنبسطون معاه\n\nوالسلام\nاحس اني طولتها 🤓", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p488314-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-salem/68511/18", "user": "user6323", "ts": 1257534628000, "tid": 68511, "pn": 18}}]}', 1257534628000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_hamad_22-phys102', 'stk-abu_hamad_22', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68511", "n": "Dr. A Salem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم\n\nphys 102 -- Lecture -- Term 133\n\nالتحضير : أول آسبوع شديد بقضية التحضير ثم يخف علينا ثم يعطي كل واحد السيريال نمبر و يتم التحضير عن طريقها\n\nطريقة الشرح : جداً رائعة … تسهيل الكونسبت بقدر المُستطاع ثم تعزيزه بمسائل الآولد آقزام\n\nالكويزات : هو على حسب التشابتر … بس غالباً بمذاكرة متوسطة لا تقل عن 7 أو 8 من 10 بس حاول تشدد بالكويزات لآنه إحتمال يعطيكم 12 كويز و ما يحذف ولا واحد\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي:+++++++++++A\n\nالصوت: جداً واضح و لغته الانجليزية و العربية كلتاهما جبّارتين … سبحان اللذي رزقه بهذا اللسان الفصيح و الصوت المسموع\n\nإضافات : هذا الدكتور آخلاقه سبقت علمه … عندما تجد سكشن له … لا تتردد بالتسجيل معه … آنا آجزم انك بتصحى كل يوم متحمس للكلاس … دائماً بداية كل درس يعطيك نبذة تاريخية ثم آستعماله بالحياة … يخليك من جد تعيش آجواء و كآنك مهندس و قاعد تشتغل بالمصنع … بإختصار نابغة …\n\n* و فيه ميزة … يسوي قروب بالواتس لجميع طلاب السكشن … يجعلها كـ آوفيس آورز 24 ساعة\n\nآي آستفسار آو شي من هذا القبيل ضعه بالقروب و بالكثير ساعة و شي و يأتيك الحل و بالتفصيل\n\nالحمدلله اللذي درست على آيدي هذا العالم الجليل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1395095-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-salem/68511/47", "user": "Abu_Hamad_22", "ts": 1409436731000, "tid": 68511, "pn": 47}}]}', 1409436731000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.a1-phys102', 'stk-mr.a1', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68511", "n": "Dr. A Salem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د. أحمد فتحي سالم\n\nالدكتـور \\ أحمد فتحي سالــم\nhttp://www.freeimagehosting.net/uploads/8f6cd7a5be.jpg\n\nمحاضر\n\nhttp://faculty.kfupm.edu.sa/phys/afsalem/\n\nTerm 152 PHYS 102\n\nبنود التقييم :\n\nالتحضير :\nبداية المحاضرة ، يمرر ورقة التحضير على الطلاب. ما يدقق على التأخير بشكل كبير إلا لو مصختها\nبعض الأحيان يدقق على التواقيع ، وسبق وصاد كم واحد وكان بيسوي لهم مشكلة بس كلموه واعتذروا\nطريقة الشرح :\nرائعة. يبدأ شرح الشابتر بإعطاء نبذة عنه ، بالإضافة إلى بعض تطبيقاته في الحياة ، ثم يفتح الكتاب على الكمبيوتر ، ويكتب نوت مرتب ويعطيك زبدة الكتاب كله\nيشتق بعض القوانين ، يحل التشيك بوينت من الكتاب ، بالإضافة إلى أمثلة المسائل من الكتاب أو مسائل من أولد إقزام الكحيلي\nالكويزات :\n11 كويز ، من سهلة إلى متوسطة. غالبا تجي نسخ لصق من أولد إقزام الكحيلي وعبيد ، مرات قليلة جاب لنا من الكتاب\nالمياجر:\nكومون\nالفاينلات :\nكومون\nالقريد النهائي:\nA+ مع مرتبة الشرف الأولى\nالصوت:\nواضح جدا ، أكسنت واضح وسليم جدا ، مختلف عن أغلب الدكاترة المصريين\nإضافات:\nخلوق جدا ، يحب يساعد الطلاب على بذل أقصى طاقاتهم في الكورس\nيسوي قروب واتساب ، على شكل 24/7 أوفيس أورز\nيسوي هيلب سيشن كل اسبوع ( أحيانا يلغيه اذا ماله حاجة ) ، بالإضافة إلى أكثر من هيلب سيشن في اسبوع الميجر\nصاحب مفاجآت وأشياء جميلة ( اللي بياخذ معه بيعرف [emoji16] )\nباختصار، ملك الديبارتمنت ، وراح تخسر الكثير إذا ما أخذت كورس معه\n\nمعلومة:\nهو اللي يشرح الـ Video Online Course حق PHYS 101\nوحاليا يشتغل على PHYS 102 ، وقال إنه - بإذن الله - راح يكون متاح السنة الجاية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1448154-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-salem/68511/51", "user": "Mr.A1", "ts": 1462471921000, "tid": 68511, "pn": 51}}]}', 1462471921000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-to_be_engineer-phys102', 'stk-to_be_engineer', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f179109", "n": "Dr. Tariq Al-Abdullah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 - 173 - Recitation class only\n\nالتحضير : ما يحضر بالريسايتيشن … بس كل كلاسين كويز فلازم تحضره.\nطريقة الشرح : الريسايتيشن ما فيه شرح بس حل اسئلة على الاشياء اللي اخذناها مع دكتور اللكتشر … يختار اسئله حلوه ويحل بشكل واضح ومفهوم وبعض الاحيان يعطينا اختصارات حلوه … اشوفه ممتاز.\nالكويزات : متوسطة بس لازم تكون فاهم الكونسبت زين لأنه يجيب اسئلة فيها افكار متنوعه.\nالمياجر: كومن.\nالفاينلات :كومن.\nالقريد النهائي: A\nالصوت: واضح.\nإضافات : بعض الاحيان نضيع شوي والسبب مو الدكتور لكن الوقت ضيق بالصيفي فتاخذ الكونسبت في اللكتشر واليوم الثاني تحل اسئلة في الريساتيشن … يعني اذا ما قدرت تذاكر اول بأول بتعاني شوي…بس في الترم العادي ماراح تكون مشكلة .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1497475-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tariq-al-abdullah/179109/4", "user": "To_Be_Engineer", "ts": 1533929986000, "tid": 179109, "pn": 4}}, {"id": "stk-dr-f68511", "n": "Dr. A Salem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 -173\n\nالتحضير : ورقة تقعد تدور اول عشر دقائق توقع عليها … ما انصح تحضّر احد لأنه يتأكد بعض الأحيان … اذا لاحظ أنك تتأخر أكثر من عشر دقائق بشكل متكرر ممكن يعطيك كلمتين حلوة.\n\nطريقة الشرح : رهيبة جدا … يكتب على الصبورة التعاريف واهم الافكار والقوانين وبعدها يحل أمثلة بشكل مرتب جدا وتفهم كل شي بكل سلاسة \" أنصح أنك تكتب نوت معه لأنه مفيد جدا وفيه الزبدة \" في اخر الليكتشر يقول جملته المعتادة (: \" خلونا نطمن على مستقبلنا \" ويفتح اولد اقزام الكحيلي ويحل كم سؤال لين توصل الفكرة تمام … بعض الاحيان يعطينا التطبيق العملي لبعض الافكار في الحياة الواقعية وهذا يرسخ الفكرة اكثر …بكل إختصار ما راح تلقى شرح أحسن من كذا بين كل دكاترة الجامعة.\nملاحظة: الشرح كان مزيج بين العربي والانجليزي .\n\nالكويزات : كان دكتور الريسايتيشن مسؤول عنها.\n\nالمياجر:كومن.\n\nالفاينلات :كومن.\n\nالقريد النهائي: A+++++ يؤول الى مالانهاية.\n\nالصوت:أكسنت نظيف ما شاء الله عكس كثير من دكاترة الجامعة.\n\nإضافات :\nبداية السمستر طلب ندخله القروب عشان اذا عندنا سؤال أو استفسار سواء اكاديمي او غيره يكون موجود + لابأس بقليل من الاستهبال والطقطقة داخل القروب 🙂 ، ضبط لنا هيلب سيشن بشكل شبه اسبوعي، نهاية السمستر كرم الطلاب اللي أخذو درجات زينة في المياجر وجاب حلاوة جواهر لكل الشباب.\n\nالدكتور أحمد ماشاء الله عليه كامل والكامل الله لا تكاد تجد فيه عيب … من لم يجد فرصه أن ينزل عنده فقد الكثير.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503075-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-salem/68511/54", "user": "To_Be_Engineer", "ts": 1543514921000, "tid": 68511, "pn": 54}}]}', 1533929986000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bader_alqahtani-phys102', 'stk-bader_alqahtani', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68511", "n": "Dr. A Salem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys102 -182 -rec\nالتحضير :كان يحضر بالكوز و يمشي المتاخرين يعني ٥ دقايق حولها لكن زود يتضايق\n\nالشرح :كان يلخص لنا التشابتر و يحل اولد اقزام و يحب ان الطلاب يشاركون\n\nالتعامل :انسان خلوق و محترم و مستعد يساعد الطالب ب اي طريقة ❤️❤️❤️❤️\n\nالكوزات:سهلة الى متوسطة\nصراحة انه افضل دكتور قد مر علي 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513500-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-salem/68511/55", "user": "Bader_Alqahtani", "ts": 1565206679000, "tid": 68511, "pn": 55}}]}', 1565206679000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-someone33-phys102', 'stk-someone33', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68511", "n": "Dr. A Salem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "A F. SALEM\nPHYS 102 - Term212\n\nبنود التقييم :\nالتحضير : ورقة ويمررها على الطلاب لكن انتبه توقع عن خويك لان مرة سوا تحقيق على هذي السالفة وطلع الطلاب الي وقعوا عن اخوياهم\n\nطريقة الشرح : شرحه اسطوري ويبسط الافكار\n\nالكويزات : كويزاتنا كانت عند دكتور الريسيتيشن\n\nالصوت: الصوت واضح\n\nإضافات : خلوق وطيب ومحترم وحبيب\n\nالتقييم النهائي : A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535031-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-salem/68511/58", "user": "SomeOne33", "ts": 1660606668000, "tid": 68511, "pn": 58}}]}', 1660606668000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-loop24-phys102', 'stk-loop24', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f68511", "n": "Dr. A Salem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "A F. SALEM\nPHYS 102 - Term212\n\nبنود التقييم :\nالتحضير : ورقة ويمررها على الطلاب لكن يدقق على الي يوقع لخويه زي ما قال فوق\n\nطريقة الشرح : شرحه جيد ويبسط الافكار على ماقالوا لكن ما أشوفه أسطوري فيه دكاترة شرحهم أفضل،، لكن يبقى الدكتور شرحه كويس\n\nالكويزات :ريسيتيشن\n\nالصوت: الصوت واضح\n\nإضافات : الدكتور حبيب وأخلاقه مايختلف عليها اثنين\n\nالتقييم النهائي : B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535875-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-salem/68511/59", "user": "loop24", "ts": 1668071917000, "tid": 68511, "pn": 59}}]}', 1668071917000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rs3-phys102', 'stk-rs3', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f69025", "n": "Dr. Abdallah Al-Zahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS 102\nكلاس المحاضرة كان الساعة ٤:١٠ ف السكاشن كلها كانت قليلة كلنا على بعضا ١٩ طالب الريسايتيشن جمعنا كلنا بكلاس واحد\nواول اسبوع قعد يشوف اوقات كلاساتنا عشان ينسق ويغير وقته من ٤:١٠ الى بريك الغداء بس للأسف كان فيه تعارض كثير بس اللي حصل انه غير يومين الاربعاء والخميس وخلاهم ببريك الغداء والاحد والثلوث ٤:١٠ شي احسن من ولا شي\nالرجال جدًا متعاون ويتفهم ويإجل الكويزات ويلغيها اذا شافنا مضغوطين كويزاته سهلة يقولنا حلوا ال suggested problems اللي على موقع الفزكس ويجيب الكويز سؤال منها نسخ لصق بس يغير الارقام ويعطينا كويز كل اسبوع بأول عشر دقايق بالريسايتيشن. مره كان بيعطينا كوزين وراح بيجيب الكويز ورجع ومعه علبتين كرسبي كريم قاله هذا كويزكم ههههههه يعني هو المهم عنده انك طول الوقت تذاكر عشان كذا يعطينا كل اسبوع وسهلين\nالدكتور جدًا شديد بالتحضير يحضر اول المحاضرة واذا ما تتاخر كثير وكلمته اخر الكلاس يمشيلك\nالرجال شرحه ماشي حاله ٦ من ١٠ اعطيه بعض الاحيان المفاهيم ما يقضي فيها وقت كافي يشرحها على اساس فاهمينها الدكتور تخصصه بالفيزياء الجاذبية وله بعلم الفلك والثقوب السوداء لما يشطح فيهم صراحة تكون شطحات رهيبة ومثيرة للاهتمام يصلح للي يحب علم الفلك.\nهو صحيح شديد جدا بالمحاضرة يعني واحد اثنين طلع جواله وكان يبي يطلعهم من الكلاس بس عصب وقال لا تعيدها وبحطك غايب يعني جوال انسى تطلعه ومايحب قعدة رجل على رجل. الدكتور متعاون بالاوفيس اور ويحاول يخليك تفكر في المسألة وتحاول انت ويعطيك تلميحات بدال ما يحلها لك.\nالدكتور اذا لقيت احد احسن منه نزل بس اذا اضريت لا تخاف مو سيئ للدرجة اللي يعبرون فيه الباقين\nيستاهل B\nاي سؤال ثاني اسئلوا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474375-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdallah-al-zahrani/69025/43", "user": "Rs3", "ts": 1496412224000, "tid": 69025, "pn": 43}}]}', 1496412224000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammedb-phys102', 'stk-mohammedb', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f69025", "n": "Dr. Abdallah Al-Zahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102-172\n\nالتحضير : شدييييد جدا في التحضير بعد 5 دقايق ما يدخلك الكلاس !!!!! وكل غياب ينقص عليه 0.5 (من الكلاس وورك ) من أول غياب وكل تأخيرين بغياب .\nفي بداية السيمستر يوزع الطلاب على كراسي محددة لأنه يحضر بالأرقام والتحضير كان ياخد تقريبا 7 دقايق كل كلاس لأنه يحضر 80 طلاب َ!!!!!!\n\nطريقة الشرح : يشرح عن طريق سلايداته وأغلب شرحه يكون ع الكونسبت . الدكتور شرحه سييئ الى أبعد درجة سواء في شرح الكونسبت أو حل الأسئلة .\nالدكتور ما يحل أسئلة غير في الريسايتيشن والدكتور ما يتعب نفسه ويحل بالخطوات بالعكس الاسئلة تكون جاهزة في السلايدات وتحتها الحل مباشرة.\n\nالكويزات : اختبرنا تقريبا 10كويزات , يجيب الأسئلة من Suggested problems اللي موجودة في موقع الفيزياء وكان بس يغير الأرقام !!\nلذلك الكويزات ما تستفيد منها اي شيئ , بمجرد حفظ طريقة الحل راح تجيب فل في الكويز .\n\nالمياجر : كومن\nالفاينل : كومن\n\nالقريد النهائي : F\n\nالصوت : واطي ويجيب النوم حتى مع استخدام المايك !!\n\nإضافات : الدكتور صراحة يهتم بالطالب ويرحب بالطلاب في الاوفس اور وتقريبا كل اسبوعين كان فيه هلب سيشن يسويه لطلابه يحل في اسئلة من الكحيلي .\nلكن أنا كانت تضيع مني يوميا 50 دقيقة بدون أي فائدة . والدكتور أيضا ما يسمح بالخروج لدورات المياه ويطرد اللي يستعمل جواله وقت الشرح .\nلذلك ما أنصح أبدا بالدكتور وحااااول انك تهرب منه وما تسجل عنده .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493625-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdallah-al-zahrani/69025/44", "user": "MohammedB", "ts": 1528040480000, "tid": 69025, "pn": 44}}]}', 1528040480000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal_qh-phys102', 'stk-faisal_qh', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f69025", "n": "Dr. Abdallah Al-Zahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور عبدالله الزهراني …\nphys102- Term 201 - online\n\nالشرح : شرحه من سلايدات عنده والشرح نوعا ما جيد وفيه اشياء كان يشرحها ويقول ركزوا عليها وفعلياً جت سواء في الكويزات او المياجر ، طبعاً الشرح في الفيزياء مايقدرون الدكاترة يغطون كل شيء فلازم الواحد يرجع ويذاكر بنفسه ويبحث عن الطريقة المناسبة .\n\nالكويزات : سهلة الى متوسطة ، وكان يسوي حركة كويسة ، مثلا يعطيك ثلاث اسئلة واذا حليت اثنين تاخذ فل .\n\nالمياجر : كومن.\nالفاينل : كومن.\n\nبالنسبة للدكتور التحضير عنده كان على فورم يرسله اخر المحاضرة تدخل وتحضر نفسك بسلاسة وسهولة ، المدرس مدري ليش فيه قبل عليه شوية ذم ولكن مع الاون لاين كان التعامل جداً رائع والامور سهاااااااللللات ولاننسى ان اخلاقه وتعامله كانت كويسه\n\nاذا تبي كلاس وورك كويس وشرح حليو روح معه. والباقي عليك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1528793-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdallah-al-zahrani/69025/49", "user": "Faisal_qh", "ts": 1614452446000, "tid": 69025, "pn": 49}}]}', 1614452446000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ria-phys102', 'stk-ria', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f69025", "n": "Dr. Abdallah Al-Zahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(حضوري)LEC-Phys 102-211\n\nالتحضير :يحضر عن طريق لينك نهاية الكلاس كان بعض الطلاب يحضروا عن طريق اللينك ويسحبوا علي الكلاس لمدة 7 اسابيع بعدين قام غير الطريقة وصار كل يوم لينك (مع ذالك لسه تقدر تغيب وتخلي احد يرسلك اللينك وتحضر) تحتاج نت وكاميرا عشان تقدر تحضر من دونهم احسب نفسك غايب (تقدر ترسله اميل وتقله انه جوالك كان طافي او… الخ وبيحضرك)\nطريقة الشرح : يشرح من سلايداته والسلايدات نصها كلام ومهب زينه يعني بتغيب كثير عشان تذاكر من نفسك لانه الكلاس منت مستفيد منه شيء\n\nالكويزات : الكويزات من بدر الدوسري (معيد) افرج السكشن كان 3 من 10 الكويزات كانت صعبه\n\nالمياجر: فيه ميد مب ميجر (كومن)\n\nالفاينلات : كومن\n\nالقريد النهائي: C+ (حتى يمكن اكون ظلمته بالتقيم )\n\nالصوت: واضح بس الانجليزي حقه يمشي الحال\n\nإضافات:\n(قبل اي اضافات عن الدكتور هذا الكورس سيلف ستدي فا الدكتور مب مره مهم بس دكتور يمشي الحال زين) الدكتور عبدلله الزهراني مريح من ناحية التحضير ومتعاون بس فيه سلبية اللي هي ممكن تكون حاضر اغلب كلاساتك وعندك 5 غيابات لا تتفاجاء اذا لقيته 10 لانه اللينك مخرف بعض الاحيان فا كم من مره رحت اكلمه عشان هذا الشيء والحمدلله شالها لي فا الدكتور + الدكتور ما شاء الله اخلاق ومره متعاون ويبغى الطالب يفهم حتى يرفع اسألة old exam خمس اسئلة وتكون زبدة التشابتر واكثر اسئلة ممكن تجي بنفس الصيغه حلها وان شاء الله لك الفل + كلاساته عباره عن 30 دقيقة شرح و 20 دقيقة الثانية يشتكي من الطلاب اللي يستخدموا جولاتهم او من اللي يتاخروا (التاخير اكثر من 10 دقائق يقلك احضر مع كلاس ثاني) او من اللي يروحوا دورة المياه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1532836-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdallah-al-zahrani/69025/50", "user": "RIA", "ts": 1637765586000, "tid": 69025, "pn": 50}}]}', 1637765586000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abubakermt-phys102', 'stk-abubakermt', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f69025", "n": "Dr. Abdallah Al-Zahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102 Term222\n\nالتحضير: طريقته غريبة و مزعجة مرة، بداية الترم كان يشيك اسم اسم لكن بعد كم اسبوع وزعنا و عطى كل واحد مقعد و رقم لازم يلتزم فيه الى نهاية الترم و يحضركم عن طريق انه يشوف من الرقم الغايب، بعد ما يخلص ينادي على اسماء الغايبين للتأكد بس. الدكتور جدا شديد بالتحضير و اذا جيت متأخر خمس دقايق بالضبط الافضل انسى انك تدخل.\n\nطريقة الشرح: يشرح من سلايداته و شرحه جيد للأمانة، لكن بعض القوانين ما يوريك طريقة اشتقاقها و يقولك شفها من نفسك بالكتاب.\n\nالكويزات: كان دكتور غيره ما كان هو.\n\nالصوت: هادي مرة و انجليزيته مش ولا بد. هدوءه و توقفاته تجيب النوم مررررة فنصيحة لا تسجل عنده الا و انت ضامن انك مصحصح.\n\nالقريد النهائي: C\n\nإضافات: الدكتور مرات كثير يشطح و يبدأ يسولف عن اشياء خارج المنهج. حذاري حذاري يقفطك وانت ماسك جوالك او بيدك شيء ماله علاقة بالفيزياء", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536690-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdallah-al-zahrani/69025/51", "user": "AbubakerMT", "ts": 1684167542000, "tid": 69025, "pn": 51}}]}', 1684167542000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m.m.s-phys102', 'stk-m.m.s', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f73560", "n": "Dr. J Al-Sadah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فزكس 102\nترم 162\n\nالتحضير : اول شهرين نهاية الكلاس ومتساهل , والنص الثاني بسبة المصخره الي تصير وتسليكه الزايد على حسب المزاج وانواع ام الاستقعاد , يعني الشهرين الاخيرين بالترم يبدا يوم يحضر اول دقيقة ويوم يحضر عقب خمس ويوم يحضر بنص المحاضرة ويوم يحضر بالنهاية !\n\nطريقة الشرح : سلايدات الجلال وهو ضايع والطلاب ضايعين واذا كتب على السبورة حوسه يبدا يكتب يمين فوق بعدين يروح يسار تحت بعدين يرجع بالنص وكذا , واشين شي اذا بدا يكتب بالطبشور الازرق ! تنحول عيونك وانت تحاول تناظر .\n\nالكويزات : اغبى كويزات ممكن تشوفها بهالجامعه ! يعني عادي تذاكر لكويز شابتر واحد اربع ايام وتدخل عليه معطيك كويز مال ام امه دخل بألي ذاكرته ابد , واحد من الكوزات جايب لنا اذكر الوحدات وحاط لنا جدول ! ودايم فيه سؤال نظري عليه اربع درجات ولا حولها مدري وش يبي هالسؤال الشاطح . وغير كذا يحدد موعد ويغيره مليون مره لانه طيب ويسلك للطلاب فاذا انت منظم بيحوسك معه . بس كويزاته بالكلاس بالمدرج لان كل العالم ضايعيين فتساليك الوضع , يعني عطانا اربعه مدري خمسه كويزات ما فيه كويز زي الناس الا واحد اتوقع علما اني مذاكر لهم كلهم , وواحد منهم الافرج 4 من 12 !\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: F\n\nالصوت: واضح\n\nإضافات : اول شهرين كان حليييييل ويسلك بكل شي , جوال , دراسة , تأخير , بس مع استهبال الطلاب صارت الشهرين الاخيرات انواع الاستقعاد , حتى لو تدرس بآخر المدرج ممكن يجي ويسألك عشان يقاله يحرجك , ودايم يقول \"اف يو ار كومنق تو ستادي كالكولوس هير قو اوت سايد ذا كلاس ناو\"علما انه بدا ينشب للدراسه بالكلاس قبل الجوال\n\nاشوف انه ابعد عنه قدر الامكان , اذا انحديت عليه نزل معه لان اول شهرين الين ثلاثه الرجال حليل ويسلك , بس بتقلب الماده 100% سيلف ستدي .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474739-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-sadah/73560/27", "user": "M.M.S", "ts": 1496896045000, "tid": 73560, "pn": 27}}]}', 1496896045000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-semo97-phys102', 'stk-semo97', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f73560", "n": "Dr. J Al-Sadah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102-Term162\n\nالتحضير : على المزاج مرة في البداية ومرة في النهاية ومرة في النص\nطريقة الشرح : يتنقل من حاجة الى حاجة واحنا ضايعين ، سلايدات الجلال ، السبورة ، الديمو\nالكويزات : الشابتر في وادي والأسئلة في وادي ،وياحبه للاسئلة الشاطحة\nالمياجر والفاينلات : كومن\nالقريد النهائي : C\nالصوت : واضح\nإضافات : الدكتور في اخر الترم قام يستقعد للطلاب الي نايم والي على الجوال والي يطلع والي يذاكر مادة ثانية والي متاخر\nفي الريسايتشن الشرح أفضل من اللكتشر\n\nاخيرا الي يبي سيلف ستدي ينزل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1475002-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-sadah/73560/28", "user": "Semo97", "ts": 1497273671000, "tid": 73560, "pn": 28}}]}', 1497273671000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saam-phys102', 'stk-saam', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f73560", "n": "Dr. J Al-Sadah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 Term 172\nمثل ماقالوا الشباب أخلاق جيدة وشرح سيء جدًا\n\nالتحضير : كان مرن في التحضير بعدين فجأة صار أكثر مدرس صارم! لدرجة أنه يحضر في أول دقيقة أو دقيقتين يعني على مزاجه.\nطريقة الشرح :بتحس بتشتت فضيع. + ينشغل كثير بشرح الاشتقاقات ومايشرح أمثلة إلا في الريسايتيشن.\nالكويزات :جيدة، مافيها تعقيد لكن أسئلة كثير وتغطي الأفكار الموجودة في السكشن، أعجبتني كويزاته.\nالمياجر:كومون\nالفاينلات :كومون\nالقريد النهائي: D\nالصوت:واطي لازم تقرب منه.\nإضافات :\nللأمانة أحس أني كنت بطلع بقريد أو قريدين أفضل لو نزلت عند دكتور شريح، البعض بيقول بعتمد على نفسي self study\nلكن المشكلة أن كتاب الفيزكس كارثي وسيء لأبعد حد! لو كان مثل كتاب الماث فما عندي أي مشكلة أعتمد على نفسي في المذاكرة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493014-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-sadah/73560/29", "user": "saam", "ts": 1527300803000, "tid": 73560, "pn": 29}}]}', 1527300803000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12081-phys102', 'stk-user12081', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f73560", "n": "Dr. J Al-Sadah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "J AL-SADAH\nPHYS102 - T202\nبنود التقييم :\n\nالتحضير:\nيرسل نهاية كل كلاس فورم , تعبيه وتمشي , كان عدد الطلاب اللي يعبون الفورم 65 وعدد اللي بالميتنق 30. الدكتور عارف لكنه يمشي الوضع.\nطريقة الشرح:\nالدكتور داهية للامانة وواضح انه متمكن من المادة العلمية (للي ما يدري الدكتور متخرج من البترول دبل ميجر ماث وفيزكس). لكن للاسف يتعب في ايصال المادة للطالب ومهاراته في الشرح مب عاليه جداً. الدكتور يسترسل وااااجد ويشرح امور ما بتحتاجها.\nالكويزات:\nمستواها متوسط , غالباً افرج الكويزات يجي قريب من الـ 7/10.\nالمياجر:\nكومون\nالفاينلات:\nكومون\nالقريد النهائي:\nA\nاضافات:\nالدكتور عسل لابعد مدى , اذا انت من الطلاب اللي ما يهمهم الدكتور في مثل هالمواد ويمشي اموره self study هذا الدكتور بيناسبك جددداً. لكن اذا انت حريص على الشرح لا انصح به. عالعموم مثل هالمواد الجامعة الله يكرمها ما قصرت من ناحية الاونلاين كورس. اي عجز يحصل بسبب الدكتور في اللكتشر تقدر تعوضه لاحقاً والشروحات متوفره. الباقي اجتهادك , الله ييسر للجميع.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530068-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-sadah/73560/30", "user": "user12081", "ts": 1621770006000, "tid": 73560, "pn": 30}}]}', 1621770006000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-iiahmadx-phys102', 'stk-iiahmadx', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f73560", "n": "Dr. J Al-Sadah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور/ جهاد السداح\nT212 - PHYS102\n\nالتحضير\n:\nبداية السمستر يعطي كل طالب سيريال نمبر ويحضر من خلاله نهاية الكلاس, ولكن تجي له ايام يحضر بداية الكلاس او نصه بشكل مفاجئ… التأخير يتسامح فيه لو كلمته ولكن في حال كان عد المتأخرين كثار يقوم يحضر مباشرةً عناداً فيهم.\n\nطريقة الشرح\n:\nالدكتور طرق شرحه مو ثابته من وجهة نظري, لا زال في مرحلة انتقاء الطريقة الانسب… يوم يشرح عالسبوره ويوم عالسلايد ويوم بالكلام فقط وانت وحظك عاد, اشوف شرحه سيء ولا يوصل المعلومه بشكل واضح, بالإضافة الى ان كلاسه مُمل! اتوقع ما بادر وشرح بشكل تفاعلي الا مرتين فقط طيلة السمستر.\n\nالكويزات\n:\nمتوسطة وبعض الاحيان يجيب نفس السلايدات, ولكن بعض الاحيان يخليها صعبه لابعد درجة وهذا طبعا يعتمد على افرج الكلاس… التصحيح كان فيه قريدر وكان مضبطنا للأمانة, تجيب 210 يخليها لك 610… بالنسبه لنهاية الترم, كنا نورمالايزيشن ويوم حسب الزيادة والنقصان, عامل ال3 سكاشن ك سكشن واحد.\n\nالمياجر\n:\nCommon\n\nالفاينلات\n:\nCommon\n\nالصوت\n: ضعيف شوي لازم تجلس بالمقاعد الامامية في حال بغيت تسمع زين, “الكلام ذا عالقاعات الكبيره”, ولكن بعض الاحيان يستعمل المايك.\nالقريد النهائي: C+\n\nإضافات :\nالدكتور يجيه ايام يصير طيب, ولكن في معظم الاوقات يكون خبيث بشكل لا يُعقل! كان يبدا الكلاس قبل الوقت بدقيقه ويخلص بعد الوقت ب5-8 دقايق!, واذا فيه كويز يقوم يعطيك اياه قبل نهاية الكلاس ب 5د والكويز عباره عن 3 اسئلة كلها معادلات حسابية وتاخذ بالقليل 10د, لذلك لو انت عندك بعده كلاس بعيد نصيحه ابعد عنه… ثانياً, تأجيل الكويزات مو بقاموسه, مره سألناه ليه ما تخلي الكويز باليوم الفلاني, بكل وقاحه رد علينا بالشكل التالي: “انت الطالب وانا الدكتور, انت الي عليك تذاكر وقت ما احدد وقت الكويز لا اكثر ولا اقل… بالأول والأخير تراك طالب ولا لك كلمة بهالموضوع”. لا تنزل عنده الا اذا أُجبِرت", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535180-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-sadah/73560/31", "user": "IIAhmaDx", "ts": 1661448537000, "tid": 73560, "pn": 31}}]}', 1661448537000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12137-phys102', 'stk-user12137', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f73560", "n": "Dr. J Al-Sadah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102 - T221\nالتحضير:\nيعطيك رقمك تحفظه ويحضر بداية الكلاس او نهايته ونادرا في نصه كل شوي يغير وقت التحضير وما يمشي التأخير على طول يعطيك ليت وابسنت فمتشدد هو من هالناحية\nطريقة الشرح:\nالدكتور تحسه من النوع الفاهم بس ما يقدر يفهمك ,الدافور الي ما يعرف يشرح كذا هو, انصحك تاخذه سيلف ستدي بوتحاول تركز بشرحه لان بعض الاحيان يرويك برامج او يعطي امثلة ممتازة بين الفينة والاخرى يفهمك الموضوع بشكل افضل. وتالي بعدما تشوف الشرح حق الاونلاين كورس او ايا يكن بتقول بنفسك “اووه هذا الي يقصده الدكتور” فركز احسن وشرحه للمسائل بالريسايتيشن جيد\nالكويزات:\nمستواها متوسط , غالباً افرج الكويزات يجي قريب من الـ 7/10.\nالقريد النهائي:\nC+\nاضافات:\nالدكتور طيب نوعا ما واخلاقه زينة وينكت احيانا, ويجبر الناس تشارك يعني فجاة كذا يختار جماعة يخليهم يجاوبوا عللا سؤال او يخلي الكلاس كله يشارك فهو يحب يخلي الطلاب يشاركوا ويكره الجوال ايضا بالمناسبة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536217-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-sadah/73560/32", "user": "user12137", "ts": 1674223188000, "tid": 73560, "pn": 32}}]}', 1674223188000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5771-phys102', 'stk-user5771', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f77388", "n": "Dr. S Marzoug", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت عنده فزكس 102 سمستر 111\nوالله العظيم انه شريح ويحل مسائل كثير\nأخذت 101 عند قوندال\nوأنا أشوف مرزوق أفضل\nيحضر دايم ومايمديك تحضر خويانك لانه يشيك في آخر اللكشر\n\nوالله العظيم الطلاب ظالمينه في التقييم\nوالشي الثاني آخر السمستر كل الطلاب الي عندهم أكثر من 5 غيابات رد غياباتهم الى 5 عشان الاب قريد\nانا غياباتي كانت 11 وحطها 5\nيحفظ أسماء اغلب الطلاب\nحفظ اسمي وغثني كل شوي يحشرلي بس فللللله خخخخخ", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p970296-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-marzoug/77388/27", "user": "user5771", "ts": 1326873248000, "tid": 77388, "pn": 27}}]}', 1326873248000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-osaid-phys102', 'stk-osaid', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f77388", "n": "Dr. S Marzoug", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "phys102 - T121\n\nسعيد المرزوق\n\nأفضل وصف للدكتور هو الأب العاطفي على أولاده … لا يغركم صوته و صراخه في الكلاس 😆 هههههههههه\nقلبه على الطلاب و يحاول يفيدهم بأي طريقة … على بعد ميجر تو كان فيه أكثر من واحد يستحق الـ DN\nبس ما أعطاهم أو على حسب علمي إثنين منهم , لأني شفتهم في الفآينل يختبروا معنا\nشرحه جميل بغض النظر عن صوته المرتفع , يحاول يبسط الكونسبت و يركز على حل المسائل لفهم الطالب\nويحل أولد إكزام كثير جداً جداً علشان يفهم الطلاب و يعودهم على طريقة التفكير حل المسائل في المياجر\nأسئلته سهلة جدا في الكويزات لدرجة توصل سخيفة في بعض الكويزات , و يعتمد على فهم الطالب في الدرجة الأولى\n\nعن نفسي أعطيه A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1157494-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-marzoug/77388/32", "user": "Osaid", "ts": 1357523005000, "tid": 77388, "pn": 32}}]}', 1357523005000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_y12-phys102', 'stk-_y12', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f77388", "n": "Dr. S Marzoug", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 /term 132\n\nالتحضير :\nورقة تمر على الطلاب بداية الكلاس لكن لاتحضر خويك لان الدكتور يحفظ أسماء الطلاب ويعرف من الغايب … الدكتور ما يدقق على التاخير\n\nطريقة الشرح :\nيشرح الكونسبت بشكل مختصر ثم يحل مسائل بقية الكلاس .\n\nالكويزات : سؤال واحد سهل جدا\n\nالمياجر:كومون\n\nالفاينلات :كومون\n\nالقريد النهائي: A+\n\nالصوت: اكثر من واضح … الدكتور يشرح وهو متحمس و تشوفه يصارخ ويناقز في الكلاس\n\nإضافات :\n-الدكتور الطيب و حريص على مصلحة الطالب\n-أنصح به بشده خاصة اذا كنت من النوع اللي يمل في الكلاس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1373264-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-marzoug/77388/40", "user": "_Y12", "ts": 1401282618000, "tid": 77388, "pn": 40}}]}', 1401282618000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ippoo-phys102', 'stk-ippoo', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f77388", "n": "Dr. S Marzoug", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 ترم 142\n\nالتحضير : ورقة يمررها بين الطلاب وتكتب اسمك بالعربي , ما عندو مشكلة مع التاخير بس يصرخ عليك وما يسجل شي\n\nالشرح : يشرح الكونسبت في البداية نوعا ما بطريقة جيدة بعدها يعطيك امثلة الى ما تطفش\n\nالواجبات : لا يوجد\n\nالكويزات : اسئلة من الاولد اقزام احيانا تكون سهلة واحيانا صعبة\n\nتقييم : B+\n\nالمرس يصرخ كثثثثثير ومزعج بطرية مزعجة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1426620-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-marzoug/77388/43", "user": "ippoo", "ts": 1441019158000, "tid": 77388, "pn": 43}}]}', 1441019158000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_alwaleed1-phys102', 'stk-abo_alwaleed1', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f77388", "n": "Dr. S Marzoug", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS 102 - 172\n\nالتحضير : كل محاضرة مثل أغلب دكاترة الفيزياء ، ورقة تمر على الطلاب ، المتأخرين يصرخ عليهم بس ما يسجل عليهم شيء .\n\nطريقة الشرح : يشرح الكونسبت ، لكن لاحظت عليه إنه يحاول يخلص بسرعة عشان يحل مسائل كثير ، شرحه زين لكن مرات ما يعطيه حقه عشان يحل مسائل ، ويحل على كل تشابتر مسائل كثيرررة ، كان يحل لنا أسئلة الكحيلي ويرسلها لنا على الواتس ، طبعًا زيادة على اللي يحله بالكلاس من سلايداته .\n\nالكويزات : اختبرنا 8 كويزات ، متوسطة الصعوبة مائلة للسهولة ، ويجيب أسئلتها من الشرح اللي يركز عليه كثير .\n\nالتقييم العام للدكتور : A …\nالصوت: إزعاج بمعنى الكلمة ، يعني انسى تنام .\nإضافات :\nالدكتور ممتاز خصوصًا اللي يكتب وراه ، كنت بالمياجر أذاكر من الدفتر بس ، والمسائل من الكحيلي والموقع ، وكانت تكفي …\nيُفضل تكون محضر الدرس قبل كلاس حل الأسئلة عشان تكون فاهم وجاهز …\n\nأنصح فيه ، وبشدة …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492220-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-marzoug/77388/52", "user": "abo_alwaleed1", "ts": 1526159666000, "tid": 77388, "pn": 52}}]}', 1526159666000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-azooz75-phys102', 'stk-azooz75', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f77388", "n": "Dr. S Marzoug", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys102 - 192\nالتحضير : ورقه تمر ع الطلاب وتكتب اسمك فيها . لا تتاخر لانه يكره التاخير\nالاختبارات : الترم ذا جانا دكتور ريساتيشن وصار هو اللي ماسكها ( بس من بعد الحصص الاون لاين عطانا كل لكشر كويز عشان الطلاب يحضرون )\nالشرح : جدا ممتاز , يكتب كثييير , م راح تلاقي صعوبه فهم ان شاء الله معه , يحل اسئلة كثييير وولاسف يبتل يشرح ولا يحب احد يسال اذا سالته قال بسرعه ببسرعه الوقت !\nالدكتور جدا طيب وحبيب ولكن المشكله اللي واجهتني في كلاسساته انه مرات يرفع صوته عشان يخلي الطلاب يركزون معه …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521564-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-marzoug/77388/58", "user": "Azooz75", "ts": 1587667136000, "tid": 77388, "pn": 58}}]}', 1587667136000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-userdahm-phys102', 'stk-userdahm', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f78122", "n": "Dr. M Haider", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "phys102 - term 132\n\nالتحضير :\nيمرر ورقة على الطلاب لو ما تحضر الى اخر الكلاس وتحضر نفسك وتمشي ما قال شي يعني ما يدقق على التاخير ابداا\n\nطريقة الشرح :\nاشوف انها ممتازة كل بداية كلاس يعيد المفاهيم الي عطاك اياه من بداية التشابتر الي انتم تدرسونه حاليا\nبعدين يشرح المفهوم الجديد بعدين يحل كم مسالة عليها\n\nالكويزات :\nسهلة اذا انت تحل suggested problems\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\n+B\n\nالصوت:\nموب قوي بس حليل و الاكسنت بالنسبة لبني جلدته خرافي\n\nإضافات :\nحبيب وهادي ما يهاوش ابد\nهو الي ماسك الريسايتشن\nبالنسبة لتصحيح الكويزات يتاخر مرة\nوالكلاس وورك ما عطانا اياه الا قبل الفاينل بيوم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1374947-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-haider/78122/43", "user": "userdahm", "ts": 1401539162000, "tid": 78122, "pn": 43}}]}', 1401539162000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-stu2009-phys102', 'stk-stu2009', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f78123", "n": "Dr. Khalil Harrabi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "للأمانه\nالحق ينقال\nمع انه هذا السمستر أكثر الطلاب انخسفوا في الميجر الأول وأنا من ضمنهم والله يستر من الثاني…\nالدكتور من أفضل دكاترة الفيزكس وأحيانا تحسه يحرق نفسه عشان يفهم الطلاب…طبعا يشرح لسلايدات وسريع وشرحه حماسي…اذا كنت من نوعية اللي بتفلها معاه نصيحه لا تنزل معاه أما لو بس تتبع معاه في لكلاس بتحس انك محضر ومذاكر بعد.\nالكويزات:كويزاته سهله بس تصحيحه خسف…يعني مره حليت كويز كامل صح بس نسيت ما قسمت رقم على اربعه عطاني صفر\nالمياجر:كومن\nأعطيه:a+ بالمقارنه مع باقي دكاترة الفيزكس\nعيوبه:\nانه سريع شوي بس بالنسبه لي هذا مو عيب بالعكس يخليك تصحصح…وأخلاقه لك عليها…\nفي الأخير للكشر ينصح به جدا\nعنده سمستر 111 فيزيكس 102", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p937838-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalil-harrabi/78123/32", "user": "stu2009", "ts": 1322350113000, "tid": 78123, "pn": 32}}]}', 1322350113000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmad18-phys102', 'stk-ahmad18', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f78123", "n": "Dr. Khalil Harrabi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 111 فزكس 102 …\n\nبداية بسيطة : قبل لا اسجل عنده قرأت عنه في المنتدى هنا قلت (( الله يستر منك ياحرابي )) لكن بالنسبة لي ومن وجهة نظري لا تعتمد على كلام الشباب في مدرس …\n\nخذ وجهة نظرك انت وماعليك في البقية …\n\nبالنسبة لي ( هرابي ) 100 % ودكتور بمعنى الكلمة 🙂\n\nبنود التقييم :\n\nالتحضير : تحضير بنهاية الكلاس وبنادي بالسيريل نمبر ولازم تحفظه 🙂\n\nطريقة الشرح : ممتعة جدا , يحرق نفسه عشان الكل يفهم , من السلايدات ويفهمك الكونسبت عن طريق امثلة كثيرة في السبورة …\n\nالكويزات : أتعب وانا اقول سهلة … خخخخخ سهللللللللللللللللة جددددددددددددددددددددددددددددددددددا , بس في شرط عشان تكون سهلة : اول شي ركز معاه في الدرس , ثاني شي راجع مراجعة خفيفة , ثالث شي ذاكر اسئلة الريساتيشن حقته , رابع شي ركز معاه في الريساتيشن لانه واحد من الاسئلة اللي يحلها لازم تكون في الكويز … ف ركككككككككككككككككز مع هرابي …\n\nالمياجر: كومن , ويزعل كثير اذا ما جابو الشباب درجات زينة …\n\nالفاينلات : كومن ,\n\nالقريد النهائي: بالنسبة لي +a وبكل جدارة …\n\nالصوت: مسموع لاخر الكلاس … ماشاء الله\n\nإضافات : اذا تاخرت اكثر من 10 دقايق … يرفع يده كأنه يسلم عليك وبكل أدب يقلك ( next time my friend, see you next time )) وانا اشوف انه من حقه , وعلى فكرة ما يعصب الا في اللازم …\n\nوبعض الشباب يقولون تصحيحه جدا شديد في الكويزات …\n\nردي عليهم ( يا أخي هو انسان ولازم يغلط , انا كويز من الكويزات حليت 3 ارباعه صح وعطاني صفر , رحت له عطاني 15 من 20 لانه يقول خطك ماكان واضح وما فهمت اللي كاتبه )\n\nبالنهاية هو بشر يغلط ,\n\n(( يعطيك الف عافية يا هرابي )) 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p950349-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalil-harrabi/78123/35", "user": "Ahmad18", "ts": 1324358793000, "tid": 78123, "pn": 35}}]}', 1324358793000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal70-phys102', 'stk-faisal70', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f78123", "n": "Dr. Khalil Harrabi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102\\-171التحضير :\nيحضر في نهاية كل ليكشر و متشدد في التحضير اي واحد يجي بعد 5 دقايق من المحاضرة مايدخله و لكن في نهاية الترم اللي يجي متأخر عادي يدخل .\nيعطي DN في اكثر من طالب غياباتهم فوق 12.\nطريقة الشرح :\nيفتح سلايدات و يشرح اللي مكتوب و على السبورة يكتب اشتقاق القوانين و يحل مسائل بس عيبه يتكلم بسرعة و يكتب بسرعة و اذا جا يكتب على السبورة يكتب مرة يمين و مرة يسار فتضيع معه فتحتاج تكون مركز بشدة معه. شرحه مقبول . كان يعرض فيديوهات تطبيق للي ناخذه و كانت ممتازة\nالكويزات :\nالكويزات كانت مع الدكتور شيباني\nالمياجر:\nكومون.\nالفاينلات :\nالقريد النهائي:\nاعطيه C+\nالصوت:\nواضح بس يتكلم بسرعة\nإضافات :\nيعتبر ممتاز للي تركيزهم و استيعابهم ممتاز ماعدا ذلك بتشوفه مب ذاك الزود", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1486169-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalil-harrabi/78123/75", "user": "Faisal70", "ts": 1516104657000, "tid": 78123, "pn": 75}}]}', 1516104657000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m7med_21-phys102', 'stk-m7med_21', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f78123", "n": "Dr. Khalil Harrabi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102-172\nالتحضير :\nيحضر في نهاية كل ليكشر و متشدد في التحضير اي واحد يجي بعد 5 دقايق من المحاضرة مايدخله و لكن في نهاية الترم اللي يجي متأخر عادي يدخل .\nيعطي DN في اكثر من طالب غياباتهم فوق 12.\nما يشيل غيابات لو ايش .\nانتبه من هالشيء\nطريقة الشرح :\nعنده سلايدات جيدة جدا\nيشرح على السريع\nتركيزه الكبير على المسائل يحل مسائل لحتى تزهق .\nينفع للطلاب المتوسطين وفوق\nالكويزات :\nامتوسطة لكن مشكلته تصحيح ظالم جدا !\nالمياجر:\nكومون.\nالفاينلات :\nالقريد النهائي:\nاB+\nالصوت:\nواضح بس يتكلم بسرعة\nإضافات :\nمجمل دكتور ممتاز حطه من خياراتك الاولى اذا ما لقيت مكي او واثق او الكحيلي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492426-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalil-harrabi/78123/76", "user": "M7med_21", "ts": 1526397703000, "tid": 78123, "pn": 76}}]}', 1526397703000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-badran11-phys102', 'stk-badran11', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f78123", "n": "Dr. Khalil Harrabi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "phys 102 - 172\nالتحضير : نهاية كل كلاس بالسيريال نمبر ومتشدد مره بشكل مقرف\nطريقة الشرح : يفتح السلايدات حقته ( انا ما عجبتني احسها عشوائيه كنت افتح سلايدات الجلال ) ويقرا منها وايام تحسه فاهم بس ما يقدر يوصل المعلومه وايام تحسه حافظ مش فاهم 🙂\nالكويزات : اول كويزين سهلين بعدها راح كم طالب وقالوا سهلات وعصب شوي قال بجيب اختبار صعب عشان اوريكم المهم الكويزات ازدات صعوبه شوي لكن بالمجمل متوسطه ويجيبها نسخ لصق من اسئلة الريساتيشن او من سلايداته\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:B+\nالصوت: متوسط انقليزيته حلوه يتكلم بلكنه فرنسيه\nإضافات : غير متفاعل دايم مستعجل ويحسب الطلاب لعابين ويهاوش ( ايام ينكت ويضحك لكن بشق الانفس ) اذا بلشت وسجلت معه لا تخاف لانه مو مره سيء لكن مو وااااااو", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1495082-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalil-harrabi/78123/77", "user": "badran11", "ts": 1530744053000, "tid": 78123, "pn": 77}}]}', 1530744053000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3767-phys102', 'stk-user3767', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f78124", "n": "Dr. S Kunwar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "آممممم كنوار… خذت معه Phys102 وهذا اللي عندي بالتفصيل:\n\nالتحضير: يومياً ويعطي كل واحد رقم ويقوله بنهاية الكلاس. تجيه مرات ما يكفي الوقت وما يحضر. والتأخير لك 10 دقايق.\nطريقة الشرح: احسن شي فيه الشرح… بالنسبة لي شرحة ممتاز جداً والكويس فيه انه دايم يحل أولد اكزامز… يعني لو تركز معه بتدخل الاختبار وتقريباً كل المسائل مرت عليك…\nعنده سلايدات مظبطها وحاط في كل تشابتر اولد اكزامز… لا ومقسم الاولد اكزامز بعد على كل سكشن من التشابتر.\nسلايداته يستخدمها بالشرح. واجزم ان اذا احد ركز معه وحل كل التمارين اللي بسلايداته+الرسيتيشن ما راح يقل قريده عن B+\nالكويزات: موب صعبة وغالباً يكون حال مثلها باللكتشر.\nالمياجر:كومن.\nالفاينلات :كومن.\nالقريد النهائي: b\nالصوت: ممتاز وواضح والاكسنت حقته ما عليها لكن تجي منه زلّات هنود.\n\nإضافات :\nالمدرس ممتاز وتحس انه يهتم بمصلحة الطالب… يعني اللي ناويها دفرة وفهم ينزل عنده ولا يفكر… لأن طريقة شرحه حلوة واللي يبي يفهم ما راح يطلع من الكلاس الا وهو فاهم… فيه عيب يمكن ما يعجب الجميع انه قلق بالكلاس… يعني ما يحب ان احد يرن جواله أو يسولف… يحب ان الجميع يكونون معه مركزين. لكن بشكل عام المدرس متعاون ويحاول يساعدك باللي يقدر عليه… لكنه ما يقدر يتعدى قوانين الجامعة لأنه يخاف. يعني مستحيل يعطيك بونس أو يشيل عنك غيابات.\nعموماً المجتهد ما تهمه هالاشياء…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p760120-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-kunwar/78124/24", "user": "user3767", "ts": 1294531775000, "tid": 78124, "pn": 24}}]}', 1294531775000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8720-phys102', 'stk-user8720', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f78124", "n": "Dr. S Kunwar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "دكتور كنوار …\n\nأشتاق لكل محاضره له … مُدرس جدًا عظيم ورائع\n\nيقدر الطلاب المجتهد ودائما ماينصح الطلاب بأن يذاكروا الكتاب ويحلوا مسائل الكتاب لكن للأسف محد يسمع نصايحه\n\nعلى الرغم أن فزكس 102 درسني اياه احمد منصور ، لكن حبيت كورس 101 بسبب كنوار !\n\nاذا الطالب تابع معاه زين … والله انه يشوف المسائل بالمياجر مارة عليه كلها بكلاسات كنوار\n\nاستفدت من المهارات اللي تعلمتها منه في حل المسائل وتكوين المعادلات والرسم في كورسات ثانية كثير 🙂\n\nشكرًا كنوار !", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1106431-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-kunwar/78124/35", "user": "user8720", "ts": 1349900163000, "tid": 78124, "pn": 35}}]}', 1349900163000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-i_b_r_a-phys102', 'stk-i_b_r_a', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f99858", "n": "Dr. Faris Al-Matouq", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "T132 – Phys 102 LAB\nبنود التقييم :\n\nالتحضير :\n- عن طريق الكويز او الريبورت\n- ما يدقق على التأخير\nطريقة الشرح :\n- يشرح الكونسبت على السبورة\n- يشرح التجربه عملياً\nالكويزات: على حسب الافرج اذا الافرج عالي صعبها\nالفاينل: جاب لنا فاينل طويل جدا\nالتصحيح: ممتاز\nالقريد النهائي: A+\nالصوت: واضح\nإضافات :\n- إنسان في قمة الأخلاق والاحترام\n- اذا سألته يجاوبك … متعاون جداً\n- درسني لاب فيزكس 101 & 102 ولو حصل واخذت كورس فزكس ثالث اتمنى اصير عندهـ", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1368744-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faris-al-matouq/99858/18", "user": "I_B_R_A", "ts": 1400706479000, "tid": 99858, "pn": 18}}, {"id": "stk-dr-f78124", "n": "Dr. S Kunwar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "T132 – PHYS 102 Lecture\nبنود التقييم :\n\nالتحضير :\n- عن طريق ملف اكسل في نهاية المحاضرة\n- ما يحب اللي يتأخرون\n- يأخر الطلاب بعض الاحيان بسبب التحضير\n- بعض الاحيان ما يحضر\nطريقة الشرح :\n- يشرح من سلايدات هو مسويها\n- السلايدات ممتازه وفيها اولد اكزام كثير\nالكويزات :\n- متوسطه الى صعبه جداً …\n- ما اختبرنا رتين الا مرتين، و الباقي كلها اون لاين\n- الاسئله مشابهه للي في السلايدات\nالمياجر: كومن\nالفاينل: كومن\nالقريد النهائي: A\nالصوت: واضح\nإضافات: لازم تشتغل معاه اذا تبي قريد طيب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1368755-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-kunwar/78124/46", "user": "I_B_R_A", "ts": 1400707700000, "tid": 78124, "pn": 46}}]}', 1400706479000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chelsea_17-phys102', 'stk-chelsea_17', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f78124", "n": "Dr. S Kunwar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فيزيكس 102 - ترم 132\n\nالتحضير :\nنهاية كل كلاس بملف اكسل تحفظ رقمك من بداية السمستر.\n\nطريقة الشرح :\nغالبا يستخدم سلايداته ويركز عالكونسبت كثيييير ( أهم شي بفيزيكس 102 الكونسبت عكس فيزيكس 101 أشوف كان يبيلها تدريب أكثر ) وشرحه ممتاااااز بالنسبة لفيزيكس 102\n\nالكويزات :\nأسبوعيا كويز اونلاين ومستواه غالبا يكون صعب وأحيان كويزين بالأسبوع اذا أعطاكم كويز بالصف , تراها غثيييثه كويزاته وتاخذ وقت والمشكلة يقول أنا أعتمد على أمانتكم انكم ما تغشون طيب لو أنا كنت شخص أمين وغيري لأ كذا بتضرر لأن الكلاسوورك أفرج .\n\nالمياجر:\nكومون\n\nالفاينلات :\nكومون\n\nالصوت:\nواضح جدا وما يجيب النوم لكن أحيانا ينطق الكلمات خطأ ( أنا بداية السمستر من اسمه على بالي هندي لكنه اندنوسي ).\n\nإضافات :\n\nالدكتور أسوأ شيئ عنده انك تجي متأخر بداية السمستر كان يمشي شوي ونادر يخصم , نهاية السمستر سار يطرد المتأخرين , الدكتور افرج سكاشنه كان نااااااار بالمياجر والفاينل دايم اعلى 3 سكاشن سكاشنه وبالنهاية 18 طالب جابوا عنده a+ وافرج سكاشنه بالفاينل كانت 20 وفواصل وبالمياجر كان الافرج حول الـ a , ما رسب عنده الا طالب واحد بمجموع 40.9 لأن عنده 12 غياب …\n\nختاما الدكتور ممتاز لهذي الماده لكن لازم تركز معه والتمارين يحل غالبا عالسريع بس يوضح لك الفكره لكن مثل ما قلت أشوف سلبيته الكويزات ولا كان عطيته a+\n\nالترم هذا كان ترم استثنائي جدا لدكتور كنوار من ناحية درجات طلابه وهو يستاهل يتعب بالكلاس وهو يشرح\n…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1372365-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-kunwar/78124/47", "user": "Chelsea_17", "ts": 1401146786000, "tid": 78124, "pn": 47}}]}', 1401146786000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10843-phys102', 'stk-user10843', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f78124", "n": "Dr. S Kunwar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS 102, Term 173\n\nالتحضير: كان يحدد لكل واحد كرسي يجلس ويحضرك على جلوسك بالكرسي، يمديك تجلس باي مكان ثم بنهاية الكلاس ترجع للكرسي حقك.\n\nالشرح: يفتح سلايداته ويقرا منها ثم يبدا يشرح ويستخدم السبورة فقط لكتابة القوانين، مايوضح الدرس بالرسومات مثلا.\nشرحه ملخبط وفوضوي، يشرح حاجة شوية ينط لحاجة ثانية ثم يرجع للنقطة الاولى وهكذا لين تضيع وماعاد تركز معه. كنت اروح احيانا وانا محضر الدرس اللي بيشرحه وشايف الفديوهات حقت البلاكبورد ومع ذلك ما افهم شيء من شرحه. ما يحل مسائل بشكل كافي احيانا وكل شرحه كونسبت وليت هنا شرح 🙂 حتى الريسايتيشن كان يقلبها احيانا شرح للدروس ويسحب على الاسئلة.\n\nالكويزات: ١٤ كويز ( كويز لكل درس )، وكل كويز ١٠ اسألة ومدته ٧٠ دقيقة ومستوى الاسئلة صعب جدا 🙂 وبالنهاية حذف ٢.\nنظامه سيء جدا وضيع اوقاتنا بدل مايختبرنا بالكلاس وخلاص. طبعا احيانا نخلص الدرس واليوم اللي بعده على طول الكويز.\n\nتعامله جيد مع الطلاب ويحب يرمي كم ذبة بنص الشرح، ماعدا احيانا كان يفصل و يقول للي يمسك جواله انا ممكن اهينك “I will insult you” ، ويهدد بالطرد من الكلاس وفعلا مرة طرد طالب، لانه ارسله يغسل وجهه وتأخر 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1497860-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-kunwar/78124/51", "user": "user10843", "ts": 1534423089000, "tid": 78124, "pn": 51}}]}', 1534423089000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rapls-phys102', 'stk-rapls', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f78124", "n": "Dr. S Kunwar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys102-182-Lecture\nالتحضير : يحضر نهاية الكلاس بالSerial number بالاكسل ، احيانًا يدخلون الطلاب في نص الكلاس يقولون كنا بدورة المياه ويدخلهم ، يندمج في الشرح ،ما يلاحظ اللي يطلع ويدخل\nطريقة الشرح : يشرح من سلايداته تعبان عليها وحلوة ، يشرح على شكل أفكار ويقولك هذا الدرس فيه هذه الأفكار وبتجي الأسئلة على هذا النحو وكذا\nالكويزات : أونلاين كويزز و ٢ ريتن كويزز ، الأونلاين صعبة وكونسبت ، لكن في الأخير الأفرج بيضبط الوضع\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح\nإضافات : بالنسبة لي أشوفه دكتور ممتاز في اللكشر وشرحه حلو وممتع وإنجليزيته كويسة ومتساعد في المكتب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509162-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-kunwar/78124/54", "user": "Rapls", "ts": 1556561353000, "tid": 78124, "pn": 54}}]}', 1556561353000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-salh_1-phys102', 'stk-salh_1', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f78124", "n": "Dr. S Kunwar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 - 201\n(ONLINE)\n\nالتحضير: كويز قصير فالبلاكبورد نهاية كل كلاس 🙂\nاحيانا يحمل ال attendance list من التيمز بس قليل\n\nالشرح : يعرض سلايدات هو مسويها ويشرح عليها( ما كنت معتمد عليها ولا كنت اركز كثير في شرحه صراحة\n\nالكويزات : كويز وواجب كل اسبوع تقريبا ومستواها اعلى من اختبارات القسم، اغلبها اولد اقزام ولكن بعض الاسئلة يكتبها بنفسه وتكون صعبه جدا غالبا\n\nالقريد النهائي : B\n\nاضافات: الدكتور ضغطنا بشكل كبيييير جدا في الاونلاين وغالب اختباراته بعد الويكيند فما تقدر تعيش الويكيند، ولكن ضغطه سهل اختبارات القسم جدا وصار ما يحتاج تذاكر لها كثير من كثر ما ذاكرت لكويزات الدكتور وواجباته، كثير كانوا يسبونه ولكن اذا انت تبي واحد يضغطك ويصير سهل انك تجيب قريد عالي جدا سجل معه\n* الشرح كنت معتمد على الاونلاين كورس تماما، ومع ضغط اختبارات كنوار طلعت بقريد عالي جدا جدا اللهم لك الحمد 😁", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527705-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-kunwar/78124/56", "user": "Salh_1", "ts": 1610155685000, "tid": 78124, "pn": 56}}]}', 1610155685000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4195-phys102', 'stk-user4195', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f81756", "n": "Dr. Saleem Rao", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102\nالتحضير - أحيانا عن طريق ورقة تمر\nالشرح\nفي الليكتشر - سلايدات يستعرض خلالها المفاهيم , طبعاً نوعاً ما مملة شوي لان شدة الصوت ما تتغير مع كل\n\nمعلومة ولكنه انسان فاهم ويوصل لك المعلومة بسهولة إذا ركزت معه = في الليكتشر أعطيه b\n\nفي الرستاشن - أول ما يدخل يستعرض القوانين حقت الشابتر ويوضح لك إياها بعدين يحل الأسئلة\n\nفي الرستاشن راح تفهم معظم الأشيا حتى لو كنت مو فاهم الشابتر كله قبل ما تحظر وإذا عطاك الكويز راح تحله\n\nسلام سلام بس من شرحه أعطيه فيها +a\nالصوت مهوب ممتاز ولكن مع الوقت راح تتعود عليه مثلي\nالكويزات سهلة نوعاً ما\nوتراه إستاذ متعاون لو رحت له الاوفيس\nأنصح به وبقوة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p756614-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saleem-rao/81756/28", "user": "user4195", "ts": 1293979209000, "tid": 81756, "pn": 28}}]}', 1293979209000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8581-phys102', 'stk-user8581', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f81756", "n": "Dr. Saleem Rao", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "phys 102 lab & lec\nTerm 133\nالتحضير :\nفي اول كلاس يقولك نظام في الابسنت والليت وهو بعد الـ 10 دقايق ابسنت لكن الصراحة ماطبق هالشي ما ادري يمكن لأنه كان صيفي , فيعني ماكان شديد في التحضير ولا كان يحضر الا نهاية الكلاس .\n\nطريقة الشرح :\nاشوفه شريح لكن لازم تكون محضر نوعا ما لأن احيانا يتشعب او يعطيك سؤال شوي صعب فتحس ان الدرس صعب لكن لما ترجع وتذاكر تكتشف العكس فنصيحة حاول تحضر الدرس من سلايداته الي اشوفها ممتازة خصوصا ان فيها الزبدة من الكتاب + عدد كبير من الاسئلة . طريقة شرحه هي على السلايدات بحيث يشرح الكونسبت ويضل تقريبا ربع ساعة او اكثر في الشرح وبعدها يحل الاسئلة الي في السلايدات ويشرح فكرة الاسئلة ويتقبل اي سؤال بالعكس عنده عادي يعيد ويجاوبك 100 مرة لين تفهم ويتسغل كل دقيقة في الكلاس في الشرح وحل المسائل الي في السايدات لأن اغلبها اولداقزامات فنصيحة حاول تحضر الدرس + تجي الكلاس وانت مركز معاه لأن تركيزك معاه راح يفيديك كثير ومايبقى عليك الا حل المسائل والتدريب اما الكونسبت تكون فاهمه صح .\n\nالكويزات :\nيعطيك 13 كويز تقريبا ويحذف الاسوء طبعا العدد يعتمد على الافرج لكن الغالب 3 كويزات .\nكويزاته يجيبها من السلايدات خصوصا الي تكون في النهاية لأن اغلبها اولداقزامات واحيانا يجيب كويزات من الاولداقزامات ومب موجودة في السلايدات .\n\nالقريد النهائي : خله خيارك الثالث بعد الكحيلي و عبدالكريم مكي b+\nالصوت:\nواضح لكن لهجته احيانا تكون مب واضحة لكن مع اول اسبوع تتعود عليه .\nإضافات :\n- في الليكشر ممتاز لكن اللاب ما انصح فيه لأن كويزات اللاب شوي صعبة + يشرح لك بشكل بسيط في اللاب وغالبا يضطر انه يساعد الطلاب في التجارب لأنهم ما فهموا شرحه للتجربة وتصحيحه دقيق والفاينل لاب صعب ويكون قسمين : الأول صعب مسائل نفس الكويزات وبعضها عن الكونسبت\nوالقسم الثاني شوي سهل يعطيك بيانات + معادلة ويقولك اكتب المعادلة الي تخلي القراف خط مستقيم + لازم ترسم وشوي اسئلة عن القراف والمعادلة الي معطيك اياها . الصراحة هو متعاون حيل في اللاب لكن ماعجبتني طريقته .\n\n- هو ماشاء الله عليه فاهم ومطلع ودائما يربط لك الأفكار والدروس في المنهج بالواقع ويعطيك امثلة وهالشي ممتاز لكن احيانا يتشعب ويعطيك افكار او معلومات كثيرة وبسبب هالشي احيانا تحس روحك ضيعت ومب فاهم الدرس بالرغم ان الدرس سهل .\n\n- مايهتم بالجوال او الي ينامون ومايقول شي لكن يعجبه الطلاب المتفاعلين معاه ويمكن يضيع الكلاس بس عشان يجاوب على اسئلة الطلاب + قبل كل ميجر والفاينل يسوي هيلبسشن وقت الكلاس ويقول اذا ماعندكم شي انا مستعد اكمل حل مسائل معاكم و اولداقزامات. + احيانا يتحمس وياخذ اكثر من الوقت.\n+\nهذي سلايداته كاملة من 16-30\nhttps://www.mediafire.com/?okd9oqjd919d9b4", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1390280-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saleem-rao/81756/48", "user": "user8581", "ts": 1408226470000, "tid": 81756, "pn": 48}}]}', 1408226470000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-1zezo1-phys102', 'stk-1zezo1', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f81756", "n": "Dr. Saleem Rao", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : : يوميا\nطريقة الشرح : أخذت معاه phys 102 term 133 شرحه كويس والسلايدات تبعه جيدة\nالكويزات : سهلة من السلايدات أو ورقة الهوموورك… حل الأسئلة كلها اللي في السلايدات وأضمن لك فل مارك\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: +b\nالصوت: وسط بس ممكن تنام معاه والأكسنت أحسن من باقي المدرسين الباكستانيين مع إحترامي للكل\nإضافات : المدرس طيب ومتفاهم وموجود في مكتبه في الساعات المكتبية وما يرد أي أحد يجيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1392074-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saleem-rao/81756/51", "user": "1zezo1", "ts": 1408708483000, "tid": 81756, "pn": 51}}]}', 1408708483000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hammmod-phys102', 'stk-hammmod', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f81756", "n": "Dr. Saleem Rao", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "phys 102 term 143 only LAB\n\nلتحضير : ما يحضر، يحضر بالريبورت فقط\nطريقة الشرح : يجي متأخر خمس دقايق أو عشر، ويبدأ على طول في الشرح يشرح لك لاب اليوم بشكل سريع ومبسط، كثير من اللابات كنا سابقين الليكتشر فكان يحتاج يشرح لنا الكونسبت الأساسي بعدين يشرح لنا اللاب. ولو الوضع صعب أو آلات جديدة يشرح لكل قروب على الجهاز مباشرة، وأغلب الوقت كنا مقسمين قروبات بشكل عشوائي كل 3 أو 2 سوا. شرحه بطل ورائع جدا، دكتور مثالي للاب.\nالكويزات :\nمرتين عطانا بري لاب والباقي كلها كويز نهاية اللاب، الكويز مرة يعتمد عالكونسبت ويجيب تريكات.\n\nالريبورت:\nكان يدقق على بعض الأشياء على حسب المزاج، مرة وحدة خذت 10\\10 في اللاب والباقي أصير حال زين بس ينقصني.\nالمياجر:\nالفاينلات : عطانا فاينل لاب دسم كله ورقي مكون من 10 صفحات. أغلب الشعب كان معيد وأنا منهم.\nفي النهاية آفرج سكشنا كان 15.1\nالقريد النهائي: A في اللاب مدري عنه في الليكتشر\nالصوت: واضح ومقبول طبعا آكسنت هندي مدري باكستاني، ولكني معجبني الآكسنت حقه مرة\nإضافات :\nالدكتور مررررررة طيب وشريح ويحب اللي يسأل ويشرح لك ويقبل النقاش في الدرجات ولا يعابط أبد، أخلاق 10\\10", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1423758-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saleem-rao/81756/53", "user": "hAmMmOd", "ts": 1439319058000, "tid": 81756, "pn": 53}}]}', 1439319058000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10429-phys102', 'stk-user10429', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f81756", "n": "Dr. Saleem Rao", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "phys102 - 161\nتحضير : ورقة تمرر ومايسجل تأخير ولا يعطي DN , إذا تأخر عدد كثير من الطلاب وخصوصاً في الريسيتيشن ممكن مايدخلهم ويروح عليهم الكويز , مايبي يشرح لخمس طلاب والباقي يحضرون نهاية الكلاس يختبرون ويمشون .\n\nطريقة الشرح : يشرح من السلايدات بالنسبة لي ممتازجداً ومسوي اللي عليه لكن المادة عن ثلاث مواد كل ميجر محتاج يصير في مادة لحاله لا الكتاب يغطي الدروس ولا السلايدات .\n\nالكويزات :\nكل اسبوع تقريباً كويز في الريسايتيشن في النهاية يصير الافرج نازل لأن الكويزات من اولد اكزامز ومايمديك تلحق ويمكن يزيد على مجموع الكويزات ثلاث درجات .\n\nالقريد النهائي: A +\nالصوت: واضح , صرت اعتقد ان البلا في الاكسنت فقط في الهنود وممتاز عند الباكستانيين .\nإضافات :\nالدكتور متساعد وطيب وأخلاق … كان باقي لي 0.2 حتى أحصل على upgrade بس مازادني لكن أعتقد حالياً كل دكاترة الفزكس هذا نظامهم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1468296-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saleem-rao/81756/55", "user": "user10429", "ts": 1487089977000, "tid": 81756, "pn": 55}}]}', 1487089977000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_shaer6-phys102', 'stk-m_shaer6', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f81756", "n": "Dr. Saleem Rao", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nPHYS102 - 163\n\nالتحضير :\nبعض الكلاسات يحضر … ما يحاسب ع التأخير …\nيمرر ورقة والطلاب يوقعوا …\nبشكل عام متساهل جددداً فالتحضير …\n\nطريقة الشرح :\nيستخدم سلايداته في الشرح … فيها اسئلة كويسه …\nو يحاول يستخدم امثله كويسه حق يقرب لك الفكره …\nشرحه بطل …\n\nالكويزات :\nاغلبها اسئلة من اولد اكزامز … تحتاج مذاكره كويسه …\nو اذا شاف انك فاهم فكرة السؤال بس عندك اغلاط بسيطه يعطيك درجه كويسه …\n\nالمياجر :\nكومن …\n\nالفاينلات :\nكومن …\n\nالقريد النهائي :\nA\n\nالصوت :\nواضح ومفهوم … ماعليه ملاحظات … بس يتكلم شوووي سريع ساعات 😛 …\n\nإضافات :\nاشوفه ممتاز جداً صراحه … وسلايداته مفيده مرررره … انصح فيه …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479360-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saleem-rao/81756/56", "user": "m_shaer6", "ts": 1503744156000, "tid": 81756, "pn": 56}}]}', 1503744156000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman.h-phys102', 'stk-abdulrahman.h', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f94342", "n": "Dr. Ahmad Mansour", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS 102 - lecture - term 102\n\nالتحضير : ورقة تمر عالقاعة ، ويحاسب على التأخير …\nطريقة الشرح : على السبورة ، يتكلم ويكتب بشكل منظم ،\nالكويزات : بالريسايتشن ، متوسطة ومعقولة جداً لمن يحضر للكويز …\nالصوت: ممتاز ولغته بيرفكت …\n\nإضافات :\nرهييييب رهييييب هالدكتور ،\nشرح ممتاز توب صراحة ومتمكن من المادة ،\nحريص عالطلاب … نوته ممتااااز ،\nأخلاق عسل …\nأعطيه A+ بجداارة …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p939508-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-mansour/94342/29", "user": "Abdulrahman.H", "ts": 1322585506000, "tid": 94342, "pn": 29}}]}', 1322585506000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10218-phys102', 'stk-user10218', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f152605", "n": "Dr. Watheq Albasheer", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "phys102 T-143\n\nالتحضير :\n’\nورقه تدور و تقدر تحضر في اي وقت\n\nطريقة الشرح :\n\nيشرح عالسبور + سلايدات\n\nشرح عادي الى سيئ\n\nالمياجر\nالفاينلات\n\nكومن\n\nالقريد النهائي:\n\nc\n\nالصوت:\n\nواضح\nإضافات :\n\n* يتكلم عربي وقليل انجلش\n\n*يضيع يضيع يضيع وقت الكلاس على مقدمه طويله جدا + قصص\n\n*وفي طلاب بيقول قصص او بيسئل الف سؤال على شي برا المنهج في وقت الكلاس والدكتور يعطيه مجال بالتالي وقت ضايع ضايع\n\n*حل الأسئلة قليل جدا وإن حل تكون قرأة ما يكتب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437931-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/watheq-albasheer/152605/5", "user": "user10218", "ts": 1451851036000, "tid": 152605, "pn": 5}}]}', 1451851036000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-leon-mohammed-phys102', 'stk-leon-mohammed', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f152609", "n": "Dr. N Dwaikat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "phys102 term 183\nالتحضير : اسوء دكتور في التحضير، يحضر نهاية الكلاس توقع يمه في الطاولة المشكلة مو هنا المشكلة إن الدكتور مايحضر الا إذا خلص الشرح الي مخطط له في اليوم. يوميا يأخذ من وقتنا حدود 6-9 دقايق وقت غير الوقت الي مسجل في الجدول وغير الوقت الي يجعلنا نصف طابور نحضر عنده\nطريقة الشرح : يقرأ من السلايدات ويستعمل السبورة … شرحه جدا جد جدا جدا جدا جدا سيئ ،مايعرف يوصل المعلومة أبدا\n\nالكويزات : متوسطة ولايعطي درجات على كتابة القانون أو الخطوات.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: ++++F\nالصوت:غير واضح لاعربي ولا إنجليزي\nإضافات :\nانا ابتليت ابه ولا اول ماسجلت للصيف كنت عند دكتور ممتاز والجامعة غيرتي له\nوايضا الدكتور غير متساعد ابداا في الميجر الاول مابدعت درجة سيئة بسبب وعكة صحية مرت علي والميجر الثاني جبت درجة شبه مقبوله لانه قريب الافرج\nمجموع افرج كوزاتي 4.3 من 10\nوعطاني في الكلاس ورك 1.5 من 10 !!! مما جعلني انصدم وجعل لي النجاح في الفيزياء مع الفاينل بصعوبة أكثر لكن الحمدالله نجحت وافتكيت من اغث كورس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513402-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/n-dwaikat/152609/17", "user": "Leon-Mohammed", "ts": 1565050924000, "tid": 152609, "pn": 17}}]}', 1565050924000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11848-phys102', 'stk-user11848', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f152609", "n": "Dr. N Dwaikat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم : Term 182 - Phys 102\n\nالتحضير : ورقة يمررها\nطريقة الشرح : من سلايداته\nالكويزات : متوسطة وتعتمد على الكونسبت\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: B\nالصوت: واضح\nإضافات : الدكتور حبيب بس مشكلته يضيع مرات لكن ميزته ان كلاس وورك الطلاب منخفض ف يرفع الكل دايما ومايدقق على التأخير , الدكتور يفهمك الكونسبت زين بس الحل يضيع فيه , لكن يبقى اختيار جيد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526002-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/n-dwaikat/152609/18", "user": "user11848", "ts": 1601631409000, "tid": 152609, "pn": 18}}]}', 1601631409000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moh_ammed-phys102', 'stk-moh_ammed', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f152609", "n": "Dr. N Dwaikat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "LAB-PHYS 102 (term 203-Online)\n\nالتحضير: ياخذه بشكل تلقائي بدون ماينادي على الأسماء.\n\nالتعامل: تعامله كويس بس إذا أحد الطلاب أخطأ (مثلا إن الطالب يغش أو شيء زي كذا) يعصب شوي.\n\nالشرح: مو واضح.\n\nالكويزات: في البداية كان يعطينا رتن بس بعدين خلاها خيارات، ومستواها للأمانة أشوفه صعب. في نهاية الترم عطانا كويز إضافي للتحسين.\n\nإضافات: - لاتغش، أولا لأن الغش حرام، وثانيا لأن الدكتور يقفط وممكن يسوي لك مشكلة.\n- الدكتور -الله يهديه - أحيانا يقلب الحصة نصايح وفضفضة وياخذ من وقت اللاب واجد.\n- الدكتور مايمدد وقت التسليم، وإذا مدده يمدده حاجة بسيطة ( تقريبا نص ساعة أو حولها فقط) مو زي بعض الدكاترة يزودون كثير.\n- أحيانا الدكتور تحسه دقيق بالتصحيح فحاول تحل كل شيء بشكل سليم، بس الريبورت الأخير عطى كل الطلاب الدرجة الكاملة.\n\nما أنصح بالدكتور، ولكن إذا انحديت عليه ممكن يكون أفضل من بقية السيئين.\nالقريد النهائي: D+ or C", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531376-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/n-dwaikat/152609/19", "user": "Moh_ammed", "ts": 1629534434000, "tid": 152609, "pn": 19}}, {"id": "stk-dr-f179109", "n": "Dr. Tariq Al-Abdullah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS 102 (term 203-Online)\n\nالتحضير: ياخذه من التيمز بشكل تلقائي.\n\nالتعامل: الدكتور محترم وطيب ماشاء الله عليه.\n\nالشرح: ماراح أتكلم عنه لأني ماكنت أركز للأسف.\n\nالكويزات: رتن، بعضها يكون سهل والبعض الآخر متوسط.\n\nالتصحيح: الدكتور كريم بالتصحيح ومايقصر.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531377-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tariq-al-abdullah/179109/16", "user": "Moh_ammed", "ts": 1629535051000, "tid": 179109, "pn": 16}}]}', 1629534434000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sanad_hussein-phys102', 'stk-sanad_hussein', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f152611", "n": "Dr. Golibjon Beerdiyorov", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "phys102 term 132\n\nالتحضير :ورقة تمر على الكلاس وما يخاسب على التاخير لو تجي اخر دقيقة\nطريقة الشرح :من السلايدات وبعض الاحيان يرسم على السبورة .\nقبل المياجر يشرح طرق مختصره للحل ويقول هذا السؤال لازم يجي زيه\nالريستيشن مره مفيد عنده حتى لو أنت مش من طلابه روح وأفهم\nالكويزات :يعطي سؤال من الورقة خقت الريكموندد كوسشنز وسؤال أولد اجزامز\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:سجل عنده اذا مفتوح ولا يفوتك\nالصوت:ما به شئ\nإضافات :مدرس أخلاق الى أقصى درجة ومتسامح جداجداجدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1372952-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/golibjon-beerdiyorov/152611/6", "user": "sanad_hussein", "ts": 1401231640000, "tid": 152611, "pn": 6}}]}', 1401231640000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9115-phys102', 'stk-user9115', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f160162", "n": "Dr. Muhammad Baseer Haider", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "http://faculty.kfupm.edu.sa/phys/mhaider/haider33.png\n\nراح انزل عنده PHYS 102 ان شاء الله\n\nالتحضير:\n\nالشرح :\n\nالكويزات:\n\nالمياجر:\n\nاي معلومات عنه يا شباب الله يعطيكم العافية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1355363-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhammad-baseer-haider/160162/1", "user": "user9115", "ts": 1398108379000, "tid": 160162, "pn": 1}}]}', 1398108379000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammedj-phys102', 'stk-mohammedj', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f175802", "n": "Dr. Qasem Drmosh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "phys102 term162\n\nالتحضير :ورقة يمررها للطلاب .\n\nطريقة الشرح :يشرح باستخدام السبورة و السلايدات شرحه اشوفه ممتاز ، في البداية يأخذ تقريبا 5 دقايق يراجع الدرس اللي قبله بعدها يبدا في الدرس الجديد , يبدأ بتعريفات بسيطة و يشتق القوانين بعدها يحل كم مسألة بعدها يشرح حالات أصعب ويحل مسائل كثيرة ، في بعض الأحيان يشغل فيديوات كويسة تساعد على الفهم .\n\nالكويزات :متوسطة الصعوبة ، سؤال يجي نسخ لصق من الأمثلة اللي حلها وسؤال من أسئلة الهوموركات اللي يرفعها في البلاك بورد ، الكويزات مب شرط تكون في الريسايتيشن .\n\nالمياجر:---\n\nالفاينلات :----\n\nالقريد النهائي:A+\n\nالصوت:واضح .\n\nإضافات :\n- سلايداته مرره كويسه كنت استخدمها كمصدر للمذاكرة . https://drive.google.com/open?id=0B6TWh2zgUBWTR0lnRVFUSEo1X1U\n- في بداية الترم كان يسوي help session لكل تشابتر .\n- يهتم بمدى فهم الطلاب ، كان دايم يسأل في احد مب فاهم بعدها يعيد الشرح بطريقة مختلفة .\n- كان يخلينا نختار وقت الكويز .\n- دكتور فاهم وأخلاق و متعاون مع الطلاب .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474309-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/qasem-drmosh/175802/4", "user": "mohammedj", "ts": 1496325322000, "tid": 175802, "pn": 4}}]}', 1496325322000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-k.m.r-phys102', 'stk-k.m.r', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f175802", "n": "Dr. Qasem Drmosh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102\nالتحضير :ورقه تمر ع الطلاب في بداية الكلاس و ما يهتم ابدا بالتحضير كثير طلاب يحضرون و… 🤣\nطريقة الشرح :يشرح باستخدام السبورة و السلايدات شرحه 👍 ، يبدأ بتعريفات بسيطة و يشتق القوانين بعدها يحل كم مسألة\nالكويزات : اعتبره من اكثر مدرسين المادة صعوبة في الكوزات يجيب اسئلة old exams الاصعب\nبعض الاحيان يعطي بونصات وهذه لا تستهين فيها ابد\nالمياجر:\nالفاينلات :\nالقريد النهائي:+A\nالصوت:ممتاز\nإضافات :ما اقول الا الله يسعده دنيا واخرة ❤️ وعلى فكرة انا درست عند الكحيلي في 101 ولكن الدكتور قاسم اعتبره افضل 🤴\nنزل عنده وانت مرتاح البال :tv:", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474346-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/qasem-drmosh/175802/6", "user": "K.M.R", "ts": 1496371067000, "tid": 175802, "pn": 6}}]}', 1496371067000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m-t-j-phys102', 'stk-m-t-j', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f175802", "n": "Dr. Qasem Drmosh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "phys102 term181\n\nلا انصح به\nتحكمه في الكلاس سيئ جدا وبالتالي يؤثر على استيعاب الطلاب للشرح\nبداية الترم كان وضعه حلو . بعد ميجر1 سحب على الاسأله وقام 95% من الوقت شرح الكونسبت وياليت كنت افهم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1502596-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/qasem-drmosh/175802/7", "user": "m-t-j", "ts": 1542609155000, "tid": 175802, "pn": 7}}]}', 1542609155000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khc800-phys102', 'stk-khc800', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f179108", "n": "Dr. Nikolaos Konstantinidis", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102/172\n\nالتحضير : في بداية الترم كان التحضير عن طريق ورقة يمررها على الطلاب، ولكن بعد ما لاحظ تلاعب كبير في التحضير صار يحضر عن طريق السيريال نمبر وسط المحاضرة وياخذ حول الخمس دقايق\n\nطريقة الشرح : الشرح عن طريق سلايدات خاصة فيه يقرأ منها ويتناقش مع الطلاب ثم يحل بعض الأسئلة المتعلقة بكل نقطة، الشرح نوعا ما روتيني شوي ولكن جيد ويركز كثير على الفهم أكثر من حل المسائل\n\nالكويزات : كويزاته سهلة أولد اقزام نسخ لصق والأفرج كان مرتفع اضطر ينزلنا كلنا\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: B+ إلى A\n\nالصوت: واضح جدا، أكسنت أمريكي\n\nإضافات : الدكتور جديد في الجامعة تقريبا كان ثاني ترم له، حبيب وطيب، وهذا يعيبه بعض الأحيان …ولكن في نهاية الترم شد ع الطلاب من ناحية الجوالات والسواليف\nالدكتور يوناني للمعلومية، ومع أنه ما كان ينادي أحد بالاسم إلا أنه طلع عارف أسماء كل الطلاب في السكشن", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492254-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nikolaos-konstantinidis/179108/2", "user": "khc800", "ts": 1526201389000, "tid": 179108, "pn": 2}}]}', 1526201389000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nvm-phys102', 'stk-nvm', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f179108", "n": "Dr. Nikolaos Konstantinidis", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS 102 - 172\n\nالتحضير : فالبداية كان ورقة تمر عالطلاب وشاف كثير يحضرون اخوياهم ف صار ينادي بالرقم الجامعي.\nيحضر المتأخرين الى ربع ساعة.\nطريقة الشرح : شرح عادي جدًا، سلايدات ويقرأ ويحل المسائل اللي فيها.\nالكويزات : سهلة جدًا من الاولد اكزام.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B+\nالصوت: واضح واكسنت مفهموم.\nإضافات : صح ان شرحه عادي لكن مهتم بالطالب كثير، وكنت افهم منه في الريسيتشن اذا حل المسائل اكثر من اللكشر.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1501266-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nikolaos-konstantinidis/179108/4", "user": "nvm", "ts": 1540228655000, "tid": 179108, "pn": 4}}]}', 1540228655000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahm2d1-phys102', 'stk-ahm2d1', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f179109", "n": "Dr. Tariq Al-Abdullah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 - Term 173\n\nالشرح : يبدا بشرح الكونسبت وشرحه الصراحه بطل مع انه اول مره يشرح لكتشر فزكس 102 وبعد ما يخلص المحاضره يبقى حول ربع ساعه يحل فيها اسئله على الي شرحهه .\n\nالتحضير : يحضر كل كلاس ويمديك تحضر خويك و يدري بس ما يستقعد .\n\nالكويزات : اول كم كويز كانت صعبه شوي وبعدها بدا يسهلها .\n\nبالنسبه لي لو رجع بي الزمن واقدر انزل معه 101 نزلته ، الدكتور ممتاز وانصحكم فيه ومحترم ومتساعد واخلاقه كويسه ما عمره فصل او تكلم بدون نفس .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1497438-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tariq-al-abdullah/179109/3", "user": "Ahm2d1", "ts": 1533864479000, "tid": 179109, "pn": 3}}]}', 1533864479000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nawaf_d_albaqami-phys102', 'stk-nawaf_d_albaqami', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f179109", "n": "Dr. Tariq Al-Abdullah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 - Term 173\n\nالتحضير : يحضر في كل كلاس ومايدقق على التأخير .\n\nطريقة الشرح : يشرح من سلايدات اشوفها جيدة لفهم الكونسبت طريقة شرحه يبدأ في البداية يشرح المفاهيم حقت الدرس مفهوم مفهوم وفي نهاية الكلاس تقريبا يحل ٢-٣ اسئلة في اللكتشر وشرحه اشوفه ممتاز نوعًا قبل لاندخل شباتر الكهرباء بس لما دخلنا شباتر الكهرباء صراحة الدكتور تطور شرحه اكثر من اول وماشاء الله احسه فاهم الكورس ذا صح ، اما بالريسيتيشن صراحة طريقته بحل الاسئلة ممتازة وبأقصر الطرق يوصل المعلومة ،طبعًا يحل بالريستيشن أسئلة مجمعها هو من عنده واشوفها صراحة جدًا مفيدة لدرجة ان أسئلته اللي يحلها لازم بالميجر يتكرر اسئلة كثير نفس فكرتها .\n\nالكويزات : مستواها كان صعب بالبداية بس لما شاف الأفرج كان نازل أعطانا كويزات متوسطة .\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالصوت: واضح جدًا\n\nإضافات : الدكتور صراحة أخلاقه عالية وماعمره تنرفز من سؤال وأي حاجة ، وبالأوفيس اورز رهيب ويتقبل أسئلة بصدر رحب ومايتضايق ولا شيء .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1497871-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tariq-al-abdullah/179109/5", "user": "Nawaf_D_Albaqami", "ts": 1534466532000, "tid": 179109, "pn": 5}}]}', 1534466532000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bmm-phys102', 'stk-bmm', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f179109", "n": "Dr. Tariq Al-Abdullah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Phys 102 - Term 173\n\nالتحضير : يحضر كل كلاس ويمديك تحضر خويك و يدري بس ما يستقعد .\n\nالشرح: بالنسبة لي عادي جدا ، يعني مو كويس ولا سيء. (( أحيانا يتعمق جدا في الكونسبت بحيث انك تضيع، وأنت اصلا مو محتاجها)).\n\nالكويزات: وهذا الشيء الي يعيب على الدكتور . الكوزات مررره صعبه وعلى كذا الافرج كان عالي فأضطر انه ينزل كل طالب 0.3.\n\nالدكتور محترم وأخلاق وشرحه متوسط ولكن كوزاته صعبه جدأ", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498221-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tariq-al-abdullah/179109/6", "user": "BMM", "ts": 1535371804000, "tid": 179109, "pn": 6}}]}', 1535371804000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-salman_al-ghamdi-phys102', 'stk-salman_al-ghamdi', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f179109", "n": "Dr. Tariq Al-Abdullah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PHYS102 - 183\n\nالتحضير : ورقة يعطينا إياها آخر الكلاس، ما يدقق لو حضرت خويك او لأ\nطريقة الشرح : يبدأ مع الوقت يشرح الكونسبت اللي بناخذه، مرات يعرض على الكونسبت مقاطع لو كانت بتسهل علينا المعلومة أكثر، وفي لكشر يحل مسائل على الكونسبت اللي اخذناه.\nالكويزات : هذا الصيف صراحة كويزاته كانت سهلة الى متوسطة، كويزات الاترام الماضية كان فيها السهل وفيها الصعب، لكن اللي يوحد كويزاته أنها مليانة أفكار حلوة وحاجات ممكن تجي في المياجر\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A+\nالصوت: واضح جدا، اللهجة ممتازة، البعض يقول ان طريقته تجيب النوم بس ما حسيت بذا الشي أبدا.\nإضافات : الدكتور ما شاء الله جدًا متمكن من المنهج، وشرحه جدًا جميل ويخش المخ غصب، وبالإضافة لكذا فهو حبيب ويونّس وجدًا متعاون، والدكتور عنده طرق للحل وأفكار جدا مفيدة ومرات تجي في المياجر يعني، وأنصح يعني تاخذ نوتات معه، بتفيدك فعلا لأن الكلام اللي يقوله جدا قيم، ومش كله يسجله في السبورة. أنصح وبقوة تسجل عنده، أنا ممتن له طول حياتي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513298-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tariq-al-abdullah/179109/9", "user": "Salman_Al-Ghamdi", "ts": 1564839331000, "tid": 179109, "pn": 9}}]}', 1564839331000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yousef_alamoudi_4507-phys102', 'stk-yousef_alamoudi_4507', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f179109", "n": "Dr. Tariq Al-Abdullah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(PHYS102 - Term 203 LEC&REC (Online\n\nالتحضير : اتوقع إنه يسحب شيت من التيمز بس عادي لو تأخرت 5 دقائق\n\nطريقة الشرح : يبدأ الشابتر يعطي فكرة عامة أبو دقيقة أو دقيقتين عن الشابتر بعدين يبدأ يشرح الكونسبت عن طريق سلايداته و بعدها يحل أمثلة و كل أمثلته أولد إكزامز و شرحه مرة حلو و رايق و في آخرشابتر استخدم موقع محاكاة عشان يفهم الكونسبت هذا بالنسبة للكتشر.\n\nبالنسبة للريستيشن فإن نظامه طول الـ50 دقيقة يحل أسئلة أولد يجمعها هو و يبقي كم سؤال لو إنك فاضي تحلهم بنفسك.\n\nالكويزات : أسلوبه في الكويزات إنه يمشي عالنورم… بمعنى إنه لو أفرج السكشن حقك فوق النورم اللي متفق عليه فتيقن أن الكويز الجاي راح يكون نار و جلد عشان ينزل أفرجكم و العكس صحيح.\n\nنظام كويزاته ريتن يعني تفتح الكويز تلاقي سؤالين او سؤال و على حسب إذا في فيجر أو رسمة مع السؤال و تبدأ تحل في ورقة خارجية و بعدها يعطيك أبو 5 دقايق زيادة عشان ترسلها و كانت عن طريق إنه يفتح دروب في البلاك و كان يعطي للكويز بين 10 دقائق إلى ربع ساعة ( لو سؤال واحد غالبا 10 دقائق و ربع ساعة لو سؤالين ).\n\nلو شاف إنه وضع السكشن مزري في كويز معين بيدفكم في الدرجات و تراه دفييييييف يعني حرفيا عندي حول كوزين كان ممكن آخذ 0 لو كان دكتور ثاني.\n\nأخذنا 7 كويزات معاه و ضاف ثامن حق تعويض لو عندك 0 في احد الكويزات أو جبت درجة مرررة زفت أو فاتتك احد الكويزات.\n\nالميد : كومن و كان صلخ.\n\nالفاينل : كومن و كان سهل.\n\nالتقييم النهائي للدكتور : يستاهل أم الـA+\n\nإضافات : الدكتور مرررة أخلاق و متعاون و حبوب و يرحب بأي سؤال إن شاء الله لو سؤال عن المريخ، لاحظت إن الدكتور أثناء شرحه يهتم بالإثبات يعني ذا القانون من فين و كيف جا، الدكتور كان يسجل المحاضرات بس ما كنت أرجع لها.\n\nأنصح بيه و بقوة\n\nبالنسبة لطريقة مذاكرة المادة كنت اراجع سلايداته و أروح دغري لأولد قوندال أحل من 191 الين 173 أو 172 و بس XD", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531258-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/tariq-al-abdullah/179109/14", "user": "yousef_Alamoudi_4507", "ts": 1629048206000, "tid": 179109, "pn": 14}}]}', 1629048206000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dark_side-phys102', 'stk-dark_side', 'PHYS 102', 'doc', '{"docs": [{"id": "stk-dr-f183506", "n": "Dr. Khan Alam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nرقم الترم: phys-102 | term-213\nالتحضير : كان التحضير عن طريق ورقة يعطيها الطلاب يوقعون عليها - وغالبا يخلي الورقه عنده لين اخر الكلاس يقول للطلاب قبل لايطلعون يوقعون ويمشون -\nطريقة الشرح : سلايدات خاصه مسويها هو يعرضها ويشرح عليها و الصراحه الصيف كنت سلف ستدي ماقدرت افهم على شرحه ابدا (يجيب النوم)… الصراحه سلايداته ماجازت لي انا شخصيا, اشوف حقت الجلال افضل بمراحل\nالكويزات : متوسطه إلى صعبه, و اغلبها من الاولدات القديمه يعني قبل 7 سنين و طالع… غالبا يجيب سؤالين فقط واحد يحله اغلب الكلاس و الثاني هو مثل مايقولون اللي يفصل بين الطلاب الجيدين والباقين (مائل للصعوبه)\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: C\nالصوت: النطق حقه يبي لك وقت عشان تتأقلم عليه\nإضافات : الدكتور حبيب الصراحه و مايخالف على سالفة الاسئلة بوسط الشرح… لكن نصيحتي لك اذا انت انسان تهتم بالشرح, هذا الدكتور ممكن ماراح ينفع لك, برضو الدكتور كان مايخالف على المتأخرين … يعني بعض الشباب يجي قبل نهاية الكلاس بربع ساعه و يوقع على انه حاضر حتى م يسجله متأخر.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535001-phys102", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khan-alam/183506/4", "user": "Dark_Side", "ts": 1660496090000, "tid": 183506, "pn": 4}}]}', 1660496090000, 1794828447, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
